// Telemetry helpers — intent + feedback signals + conversation threads.
// Tudo regex/heuristic (sem LLM call) pra ficar O(1) por turn.

import { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'

export type UserIntent =
    | 'list'
    | 'count'
    | 'create'
    | 'update'
    | 'delete'
    | 'analytics'
    | 'navigate'
    | 'help'
    | 'compare'
    | 'search'
    | 'report'
    | 'unknown'

const INTENT_PATTERNS: Array<[UserIntent, RegExp]> = [
    ['list',      /\b(list[ae]|todas?|tudo|me passa|traga|mostre todas?|lista completa|cada uma)\b/i],
    ['count',     /\b(quantas?|quantos?|total|conta|soma|quantid)\b/i],
    ['create',    /\b(cri[ae]|nov[ao]|adicion[ae]|lan[çc][ae]|cadastr)/i],
    ['update',    /\b(atualiz|edit[ae]|muda[rn]?|alter[ae]|corrig|ajust)/i],
    ['delete',    /\b(del[ei]|apag[ae]|remov[ae]|cancel)/i],
    ['analytics', /\b(an[aá]lise|m[eé]dia|evolu[çc][ãa]o|tendência|compar|KPI|dashboard)/i],
    ['navigate',  /\b(v[aá] p[ao]|abre?|abrir|leva|ir p[ao]|navega|me leve)/i],
    ['help',      /\b(como faz|como [eé]|ajuda|n[ãa]o entendi|explic|ensin|o que [eé])/i],
    ['compare',   /\b(vs|versus|comparar|diferen[çc]a|contra)\b/i],
    ['search',    /\b(busc[ae]|procur[ae]|encontr[ae]|acha[rn]?)\b/i],
    ['report',    /\b(relat[oó]rio|DRE|balanço|export[ae]r?)\b/i],
]

export function detectIntent(text: string): { intent: UserIntent; confidence: number } {
    if (!text || text.length < 3) return { intent: 'unknown', confidence: 0 }
    for (const [intent, re] of INTENT_PATTERNS) {
        if (re.test(text)) return { intent, confidence: 0.75 }
    }
    return { intent: 'unknown', confidence: 0.3 }
}

export type SignalType =
    | 'reformulation'
    | 'complaint'
    | 'repeat_ask'
    | 'thanks'
    | 'correction'
    | 'abandon'
    | 'followup_same'
    | 'followup_switch'

const COMPLAINT_RE = /\b(porra|caralho|n[ãa]o [eé] isso|errad[oa]|n[ãa]o foi isso|t[aá] errado|n[ãa]o entendeu)\b/i
const THANKS_RE = /\b(obrigad|valeu|perfeito|[óo]tim|isso mesmo|exatamente)\b/i
const CORRECTION_RE = /\b(na verdade|n[ãa]o, [eé]|quis dizer|mas eu pedi|eu disse)/i
const REPEAT_RE = /\b(de novo|mais uma vez|j[aá] pedi|pedi antes)\b/i

export function detectFeedbackSignals(
    userText: string,
    prevMiaText?: string | null,
    prevUserText?: string | null,
): Array<{ signal_type: SignalType; polarity: -1 | 0 | 1; evidence: string }> {
    const signals: Array<{ signal_type: SignalType; polarity: -1 | 0 | 1; evidence: string }> = []
    if (!userText) return signals

    const txt = userText.toLowerCase()

    if (COMPLAINT_RE.test(userText)) {
        signals.push({ signal_type: 'complaint', polarity: -1, evidence: userText.slice(0, 120) })
    }
    if (THANKS_RE.test(userText)) {
        signals.push({ signal_type: 'thanks', polarity: 1, evidence: userText.slice(0, 120) })
    }
    if (CORRECTION_RE.test(userText)) {
        signals.push({ signal_type: 'correction', polarity: -1, evidence: userText.slice(0, 120) })
    }
    if (REPEAT_RE.test(userText)) {
        signals.push({ signal_type: 'repeat_ask', polarity: -1, evidence: userText.slice(0, 120) })
    }

    // Reformulação: user repetiu tópico semanticamente próximo — heurística simples
    // baseada em intersecção de tokens com pergunta anterior.
    if (prevUserText) {
        const a = new Set(txt.split(/\s+/).filter(t => t.length > 3))
        const b = new Set(prevUserText.toLowerCase().split(/\s+/).filter(t => t.length > 3))
        if (a.size > 0 && b.size > 0) {
            const shared = [...a].filter(t => b.has(t)).length
            const overlap = shared / Math.max(a.size, b.size)
            if (overlap > 0.45 && shared >= 3) {
                signals.push({
                    signal_type: 'reformulation',
                    polarity: -1,
                    evidence: `overlap=${Math.round(overlap * 100)}% com pergunta anterior`,
                })
            }
        }
    }

    return signals
}

/**
 * Determina satisfaction_signal overall do turn: média ponderada das polaridades.
 * Retorna -1/0/1 ou null quando não há sinal.
 */
export function summarizeSatisfaction(
    signals: Array<{ polarity: -1 | 0 | 1 }>,
): -1 | 0 | 1 | null {
    if (signals.length === 0) return null
    const sum = signals.reduce((s, x) => s + x.polarity, 0)
    if (sum > 0) return 1
    if (sum < 0) return -1
    return 0
}

/**
 * Output format guess: olha a mensagem MIA e categoriza o formato usado.
 */
export function detectOutputFormat(miaText: string): string | null {
    if (!miaText) return null
    if (/\|[^\n]+\|[^\n]+\|/.test(miaText)) return 'tabela'
    if (/^\s*-\s/m.test(miaText) || /^\s*\d+\.\s/m.test(miaText)) return 'lista'
    if (/^R\$\s?[\d,.]+\s*$/m.test(miaText.trim())) return 'numero'
    if (miaText.length < 200) return 'resposta_curta'
    return 'texto'
}

/** Persiste signals em mia_feedback_signals (fire-and-forget). */
export async function saveFeedbackSignals(
    supabase: SupabaseClient,
    userId: string,
    sessionId: string,
    queryLogId: string | null,
    signals: Array<{ signal_type: SignalType; polarity: -1 | 0 | 1; evidence: string }>,
): Promise<void> {
    if (!signals.length || !userId) return
    const rows = signals.map(s => ({
        user_id: userId,
        session_id: sessionId,
        query_log_id: queryLogId,
        signal_type: s.signal_type,
        polarity: s.polarity,
        evidence_text: s.evidence,
        detected_by: 'regex',
        confidence: 0.75,
    }))
    try {
        await supabase.from('mia_feedback_signals').insert(rows)
    } catch (e) {
        console.warn('[telemetry] save feedback signals failed', e)
    }
}

// User memory — fatos persistentes sobre cada usuário (cross-session).
// Inspirado no padrão findRelevantMemories do openclaude:
// 1) recall() busca top-N memórias com filtro simples e score;
// 2) extract() roda após N msgs e grava facts via LLM barato.

import { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { callLLM } from './llm.ts'

export interface UserMemoryRow {
    id: string
    type: 'user' | 'feedback' | 'project' | 'reference' | 'pattern'
    fact: string
    description?: string | null
    confidence: number
    scope?: Record<string, unknown>
    last_used_at?: string | null
    use_count: number
    created_at?: string | null
}

export interface UserProfileSnapshot {
    user_id: string
    total_queries: number | null
    preferred_format: string | null
    verbosity_pref: string | null
    expertise_level: string | null
    top_tools: Array<{ tool: string; count: number }> | null
    top_intents: Array<{ intent: string; count: number }> | null
    top_modules: Array<{ route: string; count: number }> | null
}

/**
 * Busca memórias relevantes para o turn atual. Estratégia em 2 camadas:
 *  - Camada 1: sempre inclui memórias `user` + `feedback` com confidence >= 0.7
 *    (fatos de identidade/preferência são quase sempre úteis).
 *  - Camada 2: filtro textual opcional na query atual (ILIKE em fact+description)
 *    pra puxar até N memórias `project`/`pattern`/`reference` específicas.
 * Retorna no máx `limit` memórias, ordenadas por (type priority, confidence DESC).
 */
export async function recallUserMemories(
    supabase: SupabaseClient,
    userId: string,
    currentQuery: string,
    limit = 8,
): Promise<UserMemoryRow[]> {
    if (!userId) return []

    // Camada 1: identidade + feedback (sempre)
    const { data: coreData, error: coreErr } = await supabase
        .from('mia_user_memory')
        .select('id, type, fact, description, confidence, scope, last_used_at, use_count, created_at')
        .eq('user_id', userId)
        .in('type', ['user', 'feedback'])
        .is('archived_at', null)
        .is('superseded_by', null)
        .gte('confidence', 0.70)
        .order('confidence', { ascending: false })
        .limit(Math.min(limit, 6))

    if (coreErr) console.warn('[mem/recall] core query failed', coreErr)
    const core = (coreData || []) as UserMemoryRow[]

    // Camada 2: project/pattern/reference com match textual
    const remaining = Math.max(0, limit - core.length)
    let contextual: UserMemoryRow[] = []
    if (remaining > 0 && currentQuery && currentQuery.trim().length > 3) {
        const q = currentQuery.trim().substring(0, 120).replace(/[%_]/g, '')
        const terms = q.split(/\s+/).filter(t => t.length > 3).slice(0, 5)
        if (terms.length > 0) {
            const orFilter = terms.map(t => `fact.ilike.%${t}%,description.ilike.%${t}%`).join(',')
            const { data: ctxData, error: ctxErr } = await supabase
                .from('mia_user_memory')
                .select('id, type, fact, description, confidence, scope, last_used_at, use_count, created_at')
                .eq('user_id', userId)
                .in('type', ['project', 'pattern', 'reference'])
                .is('archived_at', null)
                .is('superseded_by', null)
                .or(orFilter)
                .order('confidence', { ascending: false })
                .limit(remaining)
            if (ctxErr) console.warn('[mem/recall] ctx query failed', ctxErr)
            contextual = (ctxData || []) as UserMemoryRow[]
        }
    }

    const selected = [...core, ...contextual]

    // Atualiza telemetria de uso (fire-and-forget) — incrementa use_count
    if (selected.length > 0) {
        const ids = selected.map(m => m.id)
        supabase
            .rpc('increment_mia_memory_use', { p_ids: ids })
            .then(() => {}, () => {
                // fallback: só last_used_at
                supabase
                    .from('mia_user_memory')
                    .update({ last_used_at: new Date().toISOString() })
                    .in('id', ids)
                    .then(() => {}, () => {})
            })
    }

    return selected
}

function humanAge(iso?: string | null): string {
    if (!iso) return ''
    const ms = Date.now() - new Date(iso).getTime()
    if (ms < 0) return ''
    const h = ms / 3_600_000
    if (h < 24) return `há ${Math.max(1, Math.round(h))}h`
    const d = h / 24
    if (d < 30) return `há ${Math.round(d)}d`
    const mo = d / 30
    if (mo < 12) return `há ${Math.round(mo)}mo`
    return `há ${Math.round(mo / 12)}a`
}

/**
 * Formata memórias em bloco Markdown estável pra injeção no system prompt.
 * Inclui idade + use_count pra LLM julgar staleness (openclaude-pattern).
 * Retorna string vazia se não há memória — pra não poluir prompt.
 */
export function formatMemoriesForPrompt(mems: UserMemoryRow[], profile?: UserProfileSnapshot): string {
    if (!mems.length && !profile) return ''
    const out: string[] = ['<user_memory>']
    out.push('# Memórias persistentes sobre o usuário. Idade indica quando foram aprendidas;')
    out.push('# memórias antigas podem estar desatualizadas — valide com dados atuais antes de agir.')

    if (profile) {
        const pref = [profile.verbosity_pref, profile.preferred_format].filter(Boolean).join(' · ')
        if (pref) out.push(`Preferências: ${pref}`)
        if (profile.expertise_level) out.push(`Nível: ${profile.expertise_level}`)
        if (profile.top_modules?.length) {
            const mods = profile.top_modules.slice(0, 3).map(m => m.route).join(', ')
            out.push(`Módulos frequentes: ${mods}`)
        }
        if (profile.top_tools?.length) {
            const tools = profile.top_tools.slice(0, 3).map(t => t.tool).join(', ')
            out.push(`Tools mais usados: ${tools}`)
        }
    }

    if (mems.length) {
        const byType: Record<string, UserMemoryRow[]> = {}
        for (const m of mems) (byType[m.type] ||= []).push(m)
        const order: Array<UserMemoryRow['type']> = ['user', 'feedback', 'project', 'pattern', 'reference']
        for (const t of order) {
            const list = byType[t]
            if (!list?.length) continue
            out.push(`\n[${t}]`)
            for (const m of list) {
                const age = humanAge(m.created_at)
                const used = m.use_count > 0 ? `, usada ${m.use_count}x` : ''
                const meta = age ? ` (${age}${used})` : ''
                out.push(`- ${m.fact}${meta}`)
            }
        }
    }

    out.push('</user_memory>')
    return out.join('\n')
}

/**
 * Extrai facts novos da conversa recente e persiste.
 * Roda em fire-and-forget após a resposta (não bloqueia UX).
 * Usa LLM rápido/barato pra classificar.
 */
export async function extractAndSaveMemories(
    supabase: SupabaseClient,
    userId: string,
    sessionId: string,
    recentMessages: Array<{ role: string; content: string }>,
): Promise<number> {
    if (!userId || recentMessages.length < 4) return 0  // só a partir do 4º turno
    const transcript = recentMessages
        .slice(-10)
        .map(m => `${m.role.toUpperCase()}: ${(m.content || '').slice(0, 500)}`)
        .join('\n')
    if (transcript.length < 150) return 0

    // Rate-limit: não re-extrair se já gravamos algo dessa sessão nos últimos 10 min.
    // Evita inflar memory table com duplicatas a cada turno.
    try {
        const tenMinAgo = new Date(Date.now() - 10 * 60_000).toISOString()
        const { count } = await supabase
            .from('mia_user_memory')
            .select('id', { count: 'exact', head: true })
            .eq('source_session_id', sessionId)
            .gte('created_at', tenMinAgo)
        if ((count ?? 0) > 0) return 0
    } catch {}

    const extractionPrompt = `Você extrai FATOS persistentes sobre o usuário a partir de uma conversa com a MIA (assistente da Momma).

Extraia APENAS fatos que serão úteis em conversas futuras. Tipos:
- user: papel, responsabilidades, preferências de formato/verbosidade
- feedback: correção explícita ou validação de abordagem
- project: contexto de trabalho (loja de foco, iniciativa em andamento)
- reference: onde encontrar dados externos (sistemas, dashboards, pessoas)
- pattern: comportamento observado (ex: "sempre pede lista detalhada em vez de resumo")

NÃO extraia:
- Dados transacionais do dia (números, valores, datas específicas)
- Info já derivável do sistema (stores, permissions)
- Informação trivial ou de curto prazo

Responda APENAS com JSON válido neste formato exato (array; pode ser vazio):
[{"type":"user","fact":"Pedro é CTO da Momma","description":"papel do usuário","confidence":0.95}]

CONVERSA:
${transcript}`

    try {
        const res = await callLLM(
            [{ role: 'system', content: extractionPrompt }],
            [],
            'x-ai/grok-4.1-fast',
            0.1,
        )
        const text = res?.content || ''
        const match = text.match(/\[[\s\S]*\]/)
        if (!match) return 0
        const facts = JSON.parse(match[0])
        if (!Array.isArray(facts) || facts.length === 0) return 0

        const rows = facts
            .filter((f: any) => f?.type && f?.fact && typeof f.fact === 'string' && f.fact.length > 10)
            .slice(0, 10)
            .map((f: any) => ({
                user_id: userId,
                type: f.type,
                fact: f.fact.slice(0, 500),
                description: f.description?.slice(0, 200),
                confidence: Math.min(1, Math.max(0.5, Number(f.confidence) || 0.7)),
                source_session_id: sessionId,
                extracted_by: 'x-ai/grok-4.1-fast',
            }))

        if (rows.length === 0) return 0
        const { error } = await supabase.from('mia_user_memory').insert(rows)
        if (error) {
            console.warn('[mem/extract] insert failed', error.message)
            return 0
        }
        console.log(`[mem/extract] saved ${rows.length} memories for user ${userId.slice(0, 8)}`)
        return rows.length
    } catch (e) {
        console.warn('[mem/extract] exception', e)
        return 0
    }
}

/** Carrega snapshot leve do perfil do user pra injeção no prompt (pode ser null). */
export async function getUserProfile(
    supabase: SupabaseClient,
    userId: string,
): Promise<UserProfileSnapshot | null> {
    if (!userId) return null
    const { data, error } = await supabase
        .from('mia_user_patterns')
        .select('user_id, total_queries, preferred_format, verbosity_pref, expertise_level, top_tools, top_intents, top_modules')
        .eq('user_id', userId)
        .maybeSingle()
    if (error || !data) return null
    return data as UserProfileSnapshot
}

import { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { callLLM } from './llm.ts'

export interface ChatMessage {
    telegram_id?: number | null
    role: 'user' | 'assistant' | 'system' | 'tool'
    content: string
    tool_calls?: any[]
    created_at?: string
    session_id?: string
    channel?: 'web' | 'telegram'
    user_id?: string
}

export async function saveMessage(supabase: SupabaseClient, message: ChatMessage) {
    const { error } = await supabase.from('chat_messages').insert(message)
    if (error) console.error('[MEMORY] Error saving message:', error)
}

/** Upsert MIA session — creates or updates session tracking for analytics */
export async function upsertSession(supabase: SupabaseClient, session: {
    id: string
    user_id?: string
    channel: 'web' | 'telegram'
    domain_hint?: string
}) {
    const { error } = await supabase.from('mia_sessions').upsert({
        id: session.id,
        user_id: session.user_id,
        channel: session.channel,
        last_activity_at: new Date().toISOString(),
        domain_hint: session.domain_hint,
        message_count: 1,
    }, {
        onConflict: 'id',
        ignoreDuplicates: false,
    })
    if (error) {
        // If upsert fails, try incrementing message_count via RPC or simple update
        await supabase.rpc('increment_session_counter', {
            p_session_id: session.id,
            p_domain_hint: session.domain_hint,
        }).then(null, () => {}) // silent fallback
    }
}

/** Log a tool call for persistent analytics */
export async function logToolCall(supabase: SupabaseClient, call: {
    session_id?: string
    user_id?: string
    tool_name: string
    domain: string
    duration_ms?: number
    success?: boolean
    error_message?: string
}) {
    const { error } = await supabase.from('mia_tool_calls').insert(call)
    if (error) console.error('[MEMORY] Error logging tool call:', error)
}

export async function getHistory(supabase: SupabaseClient, telegramId: number, limit = 10): Promise<ChatMessage[]> {
    const { data, error } = await supabase
        .from('chat_messages')
        .select('*')
        .eq('telegram_id', telegramId)
        .order('created_at', { ascending: false })
        .limit(limit)

    if (error) {
        console.error('[MEMORY] Error fetching history:', error)
        return []
    }

    return (data || []).reverse() as ChatMessage[]
}

export async function getSessionHistory(
    supabase: SupabaseClient,
    sessionId: string,
    maxTokens: number = 8000
): Promise<{ messages: ChatMessage[], summary?: string }> {
    const { data, error } = await supabase
        .from('chat_messages')
        .select('*')
        .eq('session_id', sessionId)
        .order('created_at', { ascending: false })
        .limit(20)

    if (error) {
        console.error('[MEMORY] Error fetching session history:', error)
        return { messages: [] }
    }

    const messages = (data || []).reverse() as ChatMessage[]

    if (messages.length === 0) {
        return { messages: [] }
    }

    // Estimate tokens: rough PT-BR approximation (1 token ~ 4 chars)
    const totalEstimatedTokens = messages.reduce((sum, m) => sum + (m.content?.length || 0) / 4, 0)

    if (totalEstimatedTokens < maxTokens) {
        return { messages }
    }

    // Over token budget: keep last 5 verbatim, summarize the rest
    const last5 = messages.slice(-5)
    const olderMessages = messages.slice(0, -5)

    if (olderMessages.length === 0) {
        return { messages: last5 }
    }

    const summary = await summarizeMessages(olderMessages)

    return {
        messages: [
            { telegram_id: 0, role: 'system', content: summary } as ChatMessage,
            ...last5
        ],
        summary
    }
}

async function summarizeMessages(messages: ChatMessage[]): Promise<string> {
    try {
        const conversation = messages
            .map(m => `${m.role}: ${m.content}`)
            .join('\n')

        const prompt = `Resuma esta conversa em 2-3 frases concisas em PT-BR. Inclua: o que o usuário pediu, o que foi feito, e resultados importantes.\n\nConversa:\n${conversation}`

        const response = await callLLM(
            [{ role: 'user', content: prompt }],
            [],
            'x-ai/grok-4.1-fast',
            0
        )

        return response.content
    } catch (error) {
        console.error('[MEMORY] Error summarizing messages:', error)

        // Fallback: simple concatenation of last message from each role
        const byRole = new Map<string, string>()
        for (const m of messages) {
            byRole.set(m.role, m.content)
        }

        return Array.from(byRole.entries())
            .map(([role, content]) => `${role}: ${content}`)
            .join(' | ')
    }
}

// MIA Observability — structured logs + alerts + health (Crítico #1, jan/2026)
//
// Edge functions chamam:
//   - logStructured({ level, source, category, message, context })
//   - createAlert({ severity, source, category, message, context })
//
// Health check endpoint vive em mia/index.ts via GET /health.
// CI smoke test valida health + queries vw_mia_alerts_critical_24h.

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const SUPABASE_URL = Deno.env.get('SUPABASE_URL')
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')

const supabaseAdmin = (SUPABASE_URL && SUPABASE_SERVICE_ROLE_KEY)
    ? createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)
    : null

export type LogLevel = 'debug' | 'info' | 'warn' | 'error'
export type AlertSeverity = 'info' | 'warning' | 'error' | 'critical'

export interface StructuredLogArgs {
    level: LogLevel
    source: string
    category: string
    message: string
    context?: Record<string, unknown>
    user_id?: string | null
}

export interface AlertArgs {
    severity: AlertSeverity
    source: string
    category: string
    message: string
    context?: Record<string, unknown>
    user_id?: string | null
}

/**
 * Log estruturado JSON pro console + (se error/warn) cria alert.
 * Best-effort — não bloqueia flow do user.
 */
export function logStructured(args: StructuredLogArgs): void {
    const entry = {
        ts: new Date().toISOString(),
        level: args.level,
        source: args.source,
        category: args.category,
        message: args.message,
        ...(args.context ?? {}),
    }

    // Console com prefix uniforme pra agregação em Supabase Edge Function Logs
    const prefix = `[MIA-${args.source}]`
    const json = JSON.stringify(entry)
    switch (args.level) {
        case 'error':
            console.error(prefix, json)
            void createAlert({
                severity: 'error',
                source: args.source,
                category: args.category,
                message: args.message,
                context: args.context,
                user_id: args.user_id,
            })
            break
        case 'warn':
            console.warn(prefix, json)
            break
        case 'info':
            console.log(prefix, json)
            break
        case 'debug':
            console.debug(prefix, json)
            break
    }
}

/**
 * Insere alert em mia_system_alerts. Usado pra agregar eventos críticos
 * detectáveis via vw_mia_alerts_critical_24h.
 *
 * NÃO bloqueia — best-effort.
 */
export async function createAlert(args: AlertArgs): Promise<void> {
    if (!supabaseAdmin) return
    try {
        await supabaseAdmin.from('mia_system_alerts').insert({
            severity: args.severity,
            source: args.source,
            category: args.category,
            message: args.message.slice(0, 1000),
            context: args.context ?? {},
            user_id: args.user_id ?? null,
        })
    } catch (err) {
        console.error('[MIA-observability] createAlert failed:', err)
    }
}

/**
 * Health check completo. Verifica:
 * 1. Env vars críticos presentes
 * 2. Supabase conectividade (SELECT 1)
 * 3. Tabelas críticas existem (mia_page_models, mia_user_workflows, etc)
 * 4. Quantidade de alerts críticos não-resolvidos últimas 24h
 *
 * Retorna 200 se tudo OK, 503 se algo crítico falhou.
 */
export interface HealthCheckResult {
    ok: boolean
    timestamp: string
    checks: {
        env_vars: { ok: boolean; missing: string[] }
        supabase: { ok: boolean; error?: string }
        critical_tables: { ok: boolean; missing: string[] }
        critical_alerts_24h: { ok: boolean; count: number; threshold: number }
        llm_provider: { ok: boolean; configured: boolean }
    }
}

const CRITICAL_ENVS = ['SUPABASE_URL', 'SUPABASE_SERVICE_ROLE_KEY', 'OPENROUTER_API_KEY']
const CRITICAL_TABLES = [
    'mia_page_models',
    'mia_user_workflows',
    'mia_user_memory',
    'mia_action_log',
    'mia_glass_box_step_results',
    'mia_system_alerts',
]
const CRITICAL_ALERTS_THRESHOLD = 10  // mais que 10 críticos em 24h = unhealthy

export async function runHealthCheck(): Promise<HealthCheckResult> {
    const result: HealthCheckResult = {
        ok: true,
        timestamp: new Date().toISOString(),
        checks: {
            env_vars: { ok: true, missing: [] },
            supabase: { ok: true },
            critical_tables: { ok: true, missing: [] },
            critical_alerts_24h: { ok: true, count: 0, threshold: CRITICAL_ALERTS_THRESHOLD },
            llm_provider: { ok: true, configured: true },
        },
    }

    // 1. Env vars
    for (const v of CRITICAL_ENVS) {
        if (!Deno.env.get(v)) result.checks.env_vars.missing.push(v)
    }
    if (result.checks.env_vars.missing.length > 0) {
        result.checks.env_vars.ok = false
        result.ok = false
    }
    result.checks.llm_provider.configured = !!Deno.env.get('OPENROUTER_API_KEY')
    if (!result.checks.llm_provider.configured) {
        result.checks.llm_provider.ok = false
        result.ok = false
    }

    // 2. Supabase conectividade
    if (supabaseAdmin) {
        try {
            const { error } = await supabaseAdmin.from('mia_action_log').select('id').limit(1)
            if (error) {
                result.checks.supabase.ok = false
                result.checks.supabase.error = error.message.slice(0, 200)
                result.ok = false
            }
        } catch (err) {
            result.checks.supabase.ok = false
            result.checks.supabase.error = String(err).slice(0, 200)
            result.ok = false
        }
    } else {
        result.checks.supabase.ok = false
        result.checks.supabase.error = 'admin client not initialized'
        result.ok = false
    }

    // 3. Tabelas críticas
    if (supabaseAdmin && result.checks.supabase.ok) {
        for (const tbl of CRITICAL_TABLES) {
            try {
                const { error } = await supabaseAdmin.from(tbl).select('*', { count: 'exact', head: true }).limit(1)
                if (error && (error.message || '').includes('does not exist')) {
                    result.checks.critical_tables.missing.push(tbl)
                }
            } catch {
                result.checks.critical_tables.missing.push(tbl)
            }
        }
        if (result.checks.critical_tables.missing.length > 0) {
            result.checks.critical_tables.ok = false
            result.ok = false
        }
    }

    // 4. Critical alerts 24h
    if (supabaseAdmin && result.checks.supabase.ok) {
        try {
            const { count } = await supabaseAdmin
                .from('mia_system_alerts')
                .select('*', { count: 'exact', head: true })
                .is('resolved_at', null)
                .in('severity', ['error', 'critical'])
                .gte('created_at', new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString())
            result.checks.critical_alerts_24h.count = count ?? 0
            if ((count ?? 0) > CRITICAL_ALERTS_THRESHOLD) {
                result.checks.critical_alerts_24h.ok = false
                result.ok = false
            }
        } catch {
            // alerts table pode não existir ainda — não fail health
        }
    }

    return result
}

