/**
 * Métricas de negócio específicas da feature MIA.
 *
 * Counters: mia_requests_total, mia_tool_calls_total, mia_fallback_activations_total
 * Histograma: mia_agent_duration_ms
 *
 * Zero overhead quando VITE_OTEL_ENABLED !== 'true' — todas as funções são NOOPs.
 *
 * Uso: chamar initMiaMetrics() no startup e então usar recordMia* nos handlers.
 */

import type { Counter, Histogram } from '@opentelemetry/api';
import { isInitialized, getTelemetryConfig } from '@/shared/lib/telemetry/telemetry';

// ---------------------------------------------------------------------------
// Estado do módulo
// ---------------------------------------------------------------------------

let _initialized = false;
let _requestsTotal: Counter | null = null;
let _toolCallsTotal: Counter | null = null;
let _agentDurationMs: Histogram | null = null;
let _fallbackActivationsTotal: Counter | null = null;

// ---------------------------------------------------------------------------
// Inicialização
// ---------------------------------------------------------------------------

/** Inicializa as métricas MIA. Idempotente — seguro chamar múltiplas vezes. */
export async function initMiaMetrics(): Promise<void> {
  if (_initialized) return;

  const config = getTelemetryConfig();
  if (!config.enabled || !isInitialized()) {
    _initialized = true;
    return;
  }

  const { metrics } = await import('@opentelemetry/api');
  const meter = metrics.getMeter(config.serviceName, config.serviceVersion);

  _requestsTotal = meter.createCounter('mia_requests_total', {
    description: 'Total de requisições da MIA por domínio, modelo e status',
  });
  _toolCallsTotal = meter.createCounter('mia_tool_calls_total', {
    description: 'Total de tool calls da MIA por nome da tool',
  });
  _agentDurationMs = meter.createHistogram('mia_agent_duration_ms', {
    description: 'Duração das invocações do agente MIA por domínio em milissegundos',
    unit: 'ms',
    advice: {
      explicitBucketBoundaries: [100, 500, 1000, 2500, 5000, 10000, 20000, 30000, 60000],
    },
  });
  _fallbackActivationsTotal = meter.createCounter('mia_fallback_activations_total', {
    description: 'Total de ativações de fallback do LLM da MIA por nível',
  });

  _initialized = true;
}

// ---------------------------------------------------------------------------
// Helpers — NOOPs quando não inicializado
// ---------------------------------------------------------------------------

/** Registra uma requisição MIA concluída (counter por domain+model+status) */
export function recordMiaRequest(
  domain: string,
  model: string,
  status: 'success' | 'error',
): void {
  _requestsTotal?.add(1, {
    'mia.agent.domain': domain,
    'mia.llm.model': model,
    'mia.request.status': status,
  });
}

/** Registra uma tool call da MIA (counter por tool name) */
export function recordMiaToolCall(toolName: string, attrs?: Record<string, string>): void {
  _toolCallsTotal?.add(1, { 'mia.tool.name': toolName, ...attrs });
}

/** Registra duração de uma invocação do agente MIA (histogram por domain) */
export function recordMiaAgentDuration(domain: string, durationMs: number): void {
  _agentDurationMs?.record(durationMs, { 'mia.agent.domain': domain });
}

/** Registra ativação de fallback do LLM da MIA (counter por fallback level) */
export function recordMiaFallbackActivation(
  fallbackLevel: string,
  attrs?: Record<string, string>,
): void {
  _fallbackActivationsTotal?.add(1, {
    'mia.llm.fallback_level': fallbackLevel,
    ...attrs,
  });
}

