1	import { useEffect, useRef, useCallback } from 'react';
2	import { useLocation } from 'react-router-dom';
3	import { useAuth } from '@/hooks/useAuth';
4	import { supabase } from '@/integrations/supabase/client';
5	import type { User } from '@supabase/supabase-js';
6	
7	const HEARTBEAT_INTERVAL = 30000; // 30 seconds
8	const SESSION_KEY = 'momma_session_id';
9	
10	function getDeviceType(): string {
11	  const width = window.innerWidth;
12	  if (width < 768) return 'mobile';
13	  if (width < 1024) return 'tablet';
14	  return 'desktop';
15	}
16	
17	export function useActivityTracker() {
18	  const { user } = useAuth();
19	  const location = useLocation();
20	  const sessionIdRef = useRef<string | null>(null);
21	  const lastRouteRef = useRef<string>('');
22	  const prevUserRef = useRef<string | null>(null);
23	
24	  // Create or resume session
25	  const ensureSession = useCallback(async () => {
26	    if (!user) return null;
27	
28	    let sessionId = sessionStorage.getItem(SESSION_KEY);
29	
30	    if (!sessionId) {
31	      const { data } = await (supabase as any).from('user_sessions').insert({
32	        user_id: user.id,
33	        user_agent: navigator.userAgent,
34	        device_type: getDeviceType(),
35	        current_route: location.pathname,
36	        is_online: true,
37	      }).select('id').single();
38	
39	      if (data) {
40	        sessionId = data.id;
41	        sessionStorage.setItem(SESSION_KEY, sessionId!);
42	      }
43	    }
44	
45	    sessionIdRef.current = sessionId;
46	    return sessionId;
47	  }, [user, location.pathname]);
48	
49	  // Log activity event
50	  const logEvent = useCallback(async (eventType: string, extra?: Record<string, any>) => {
51	    if (!user) return;
52	    const sessionId = sessionIdRef.current || await ensureSession();
53	
54	    await (supabase as any).from('user_activity_log').insert({
55	      user_id: user.id,
56	      event_type: eventType,
57	      page_route: location.pathname,
58	      element_id: extra?.element_id || null,
59	      session_id: sessionId,
60	      metadata: {
61	        screen_width: window.innerWidth,
62	        screen_height: window.innerHeight,
63	        device_type: getDeviceType(),
64	        ...extra,
65	      },
66	    }).then(() => {}, () => {}); // Silent - never break UX
67	  }, [user, location.pathname, ensureSession]);
68	
69	  // Track page views on route change
70	  useEffect(() => {
71	    if (!user || location.pathname === lastRouteRef.current) return;
72	    lastRouteRef.current = location.pathname;
73	    logEvent('page_view');
74	
75	    // Update session current_route
76	    if (sessionIdRef.current) {
77	      (supabase as any).from('user_sessions')
78	        .update({ current_route: location.pathname, last_activity: new Date().toISOString() })
79	        .eq('id', sessionIdRef.current)
80	        .then(() => {}, () => {});
81	    }
82	  }, [user, location.pathname, logEvent]);
83	
84	  // Session heartbeat (every 30s)
85	  useEffect(() => {
86	    if (!user) return;
87	    ensureSession();
88	
89	    const interval = setInterval(async () => {
90	      if (sessionIdRef.current) {
91	        try {
92	          await (supabase as any).from('user_sessions')
93	            .update({ last_activity: new Date().toISOString(), is_online: true, current_route: location.pathname })
94	            .eq('id', sessionIdRef.current);
95	        } catch { /* Silent - never break UX */ }
96	      }
97	    }, HEARTBEAT_INTERVAL);
98	
99	    return () => clearInterval(interval);
100	  }, [user, ensureSession, location.pathname]);
101	
102	  // Track login
103	  useEffect(() => {
104	    if (user) logEvent('login');
105	    // eslint-disable-next-line react-hooks/exhaustive-deps
106	  }, [user?.id]); // Only on user change
107	
108	  // Track logout / tab close
109	  useEffect(() => {
110	    const handleBeforeUnload = () => {
111	      if (sessionIdRef.current) {
112	        // Use sendBeacon for reliable delivery on page close
113	        const url = `${import.meta.env.VITE_SUPABASE_URL}/rest/v1/user_sessions?id=eq.${sessionIdRef.current}`;
114	        const payload = JSON.stringify({
115	          is_online: false,
116	          ended_at: new Date().toISOString(),
117	          last_activity: new Date().toISOString(),
118	        });
119	        const headers = {
120	          'Content-Type': 'application/json',
121	          'apikey': import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY,
122	          'Authorization': `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}`,
123	          'Prefer': 'return=minimal',
124	        };
125	        // sendBeacon only supports Blob with specific content types
126	        const blob = new Blob([payload], { type: 'application/json' });
127	        try {
128	          // Try fetch with keepalive first (supports custom headers)
129	          fetch(url, {
130	            method: 'PATCH',
131	            headers,
132	            body: payload,
133	            keepalive: true,
134	          }).catch(() => {});
135	        } catch {
136	          // Fallback: sendBeacon (no custom headers, limited use)
137	          navigator.sendBeacon?.(url, blob);
138	        }
139	      }
140	    };
141	
142	    window.addEventListener('beforeunload', handleBeforeUnload);
143	    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
144	  }, []);
145	
146	  // Track JS errors
147	  useEffect(() => {
148	    const handleError = (event: ErrorEvent) => {
149	      logEvent('error', {
150	        error_message: event.message,
151	        error_source: event.filename,
152	        error_line: event.lineno,
153	        error_col: event.colno,
154	      });
155	    };
156	
157	    window.addEventListener('error', handleError);
158	    return () => window.removeEventListener('error', handleError);
159	  }, [logEvent]);
160	
161	  // Click tracking via data-track attribute
162	  useEffect(() => {
163	    if (!user) return;
164	
165	    const handleClick = (event: MouseEvent) => {
166	      const target = event.target as HTMLElement;
167	      const tracked = target.closest('[data-track]') as HTMLElement | null;
168	      if (tracked) {
169	        const trackId = tracked.getAttribute('data-track');
170	        logEvent('click', {
171	          element_id: trackId,
172	          element_tag: tracked.tagName.toLowerCase(),
173	          element_text: tracked.textContent?.slice(0, 100) || '',
174	        });
175	      }
176	    };
177	
178	    document.addEventListener('click', handleClick, { capture: true });
179	    return () => document.removeEventListener('click', handleClick, { capture: true });
180	  }, [user, logEvent]);
181	
