import { useEffect, useRef, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/integrations/supabase/client';
import type { User } from '@supabase/supabase-js';

const HEARTBEAT_INTERVAL = 30000; // 30 seconds
const SESSION_KEY = 'momma_session_id';

function getDeviceType(): string {
  const width = window.innerWidth;
  if (width < 768) return 'mobile';
  if (width < 1024) return 'tablet';
  return 'desktop';
}

export function useActivityTracker() {
  const { user } = useAuth();
  const location = useLocation();
  const sessionIdRef = useRef<string | null>(null);
  const lastRouteRef = useRef<string>('');
  const prevUserRef = useRef<string | null>(null);

  // Create or resume session
  const ensureSession = useCallback(async () => {
    if (!user) return null;

    let sessionId = sessionStorage.getItem(SESSION_KEY);

    if (!sessionId) {
      const { data } = await (supabase as any).from('user_sessions').insert({
        user_id: user.id,
        user_agent: navigator.userAgent,
        device_type: getDeviceType(),
        current_route: location.pathname,
        is_online: true,
      }).select('id').single();

      if (data) {
        sessionId = data.id;
        sessionStorage.setItem(SESSION_KEY, sessionId!);
      }
    }

    sessionIdRef.current = sessionId;
    return sessionId;
  }, [user, location.pathname]);

  // Log activity event
  const logEvent = useCallback(async (eventType: string, extra?: Record<string, any>) => {
    if (!user) return;
    const sessionId = sessionIdRef.current || await ensureSession();

    await (supabase as any).from('user_activity_log').insert({
      user_id: user.id,
      event_type: eventType,
      page_route: location.pathname,
      element_id: extra?.element_id || null,
      session_id: sessionId,
      metadata: {
        screen_width: window.innerWidth,
        screen_height: window.innerHeight,
        device_type: getDeviceType(),
        ...extra,
      },
    }).then(() => {}, () => {}); // Silent - never break UX
  }, [user, location.pathname, ensureSession]);

  // Track page views on route change
  useEffect(() => {
    if (!user || location.pathname === lastRouteRef.current) return;
    lastRouteRef.current = location.pathname;
    logEvent('page_view');

    // Update session current_route
    if (sessionIdRef.current) {
      (supabase as any).from('user_sessions')
        .update({ current_route: location.pathname, last_activity: new Date().toISOString() })
        .eq('id', sessionIdRef.current)
        .then(() => {}, () => {});
    }
  }, [user, location.pathname, logEvent]);

  // Session heartbeat (every 30s)
  useEffect(() => {
    if (!user) return;
    ensureSession();

    const interval = setInterval(async () => {
      if (sessionIdRef.current) {
        try {
          await (supabase as any).from('user_sessions')
            .update({ last_activity: new Date().toISOString(), is_online: true, current_route: location.pathname })
            .eq('id', sessionIdRef.current);
        } catch { /* Silent - never break UX */ }
      }
    }, HEARTBEAT_INTERVAL);

    return () => clearInterval(interval);
  }, [user, ensureSession, location.pathname]);

  // Track login
  useEffect(() => {
    if (user) logEvent('login');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]); // Only on user change

  // Track logout / tab close
  useEffect(() => {
    const handleBeforeUnload = () => {
      if (sessionIdRef.current) {
        // Use sendBeacon for reliable delivery on page close
        const url = `${import.meta.env.VITE_SUPABASE_URL}/rest/v1/user_sessions?id=eq.${sessionIdRef.current}`;
        const payload = JSON.stringify({
          is_online: false,
          ended_at: new Date().toISOString(),
          last_activity: new Date().toISOString(),
        });
        const headers = {
          'Content-Type': 'application/json',
          'apikey': import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY,
          'Authorization': `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}`,
          'Prefer': 'return=minimal',
        };
        // sendBeacon only supports Blob with specific content types
        const blob = new Blob([payload], { type: 'application/json' });
        try {
          // Try fetch with keepalive first (supports custom headers)
          fetch(url, {
            method: 'PATCH',
            headers,
            body: payload,
            keepalive: true,
          }).catch(() => {});
        } catch {
          // Fallback: sendBeacon (no custom headers, limited use)
          navigator.sendBeacon?.(url, blob);
        }
      }
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, []);

  // Track JS errors
  useEffect(() => {
    const handleError = (event: ErrorEvent) => {
      logEvent('error', {
        error_message: event.message,
        error_source: event.filename,
        error_line: event.lineno,
        error_col: event.colno,
      });
    };

    window.addEventListener('error', handleError);
    return () => window.removeEventListener('error', handleError);
  }, [logEvent]);

  // Click tracking via data-track attribute
  useEffect(() => {
    if (!user) return;

    const handleClick = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      const tracked = target.closest('[data-track]') as HTMLElement | null;
      if (tracked) {
        const trackId = tracked.getAttribute('data-track');
        logEvent('click', {
          element_id: trackId,
          element_tag: tracked.tagName.toLowerCase(),
          element_text: tracked.textContent?.slice(0, 100) || '',
        });
      }
    };

    document.addEventListener('click', handleClick, { capture: true });
    return () => document.removeEventListener('click', handleClick, { capture: true });
  }, [user, logEvent]);

  // Logout tracking: detect user -> null transition
  useEffect(() => {
    if (prevUserRef.current && !user) {
      // User was logged in and is now null => logout
      if (sessionIdRef.current) {
        (supabase as any).from('user_activity_log').insert({
          user_id: prevUserRef.current,
          event_type: 'logout',
          page_route: location.pathname,
          session_id: sessionIdRef.current,
          metadata: { device_type: getDeviceType() },
        }).then(() => {}, () => {});
      }
    }
    prevUserRef.current = user?.id || null;
  }, [user?.id, location.pathname]);

  return { logEvent }; // Expose for manual tracking if needed
}

