1	/**
2	 * Módulo de Real User Monitoring (RUM) via Web Vitals + OpenTelemetry.
3	 *
4	 * Coleta automaticamente Web Vitals (LCP, INP, CLS, TTFB, FCP)
5	 * e expõe helpers para rastreamento de navegação entre rotas.
6	 *
7	 * Zero overhead quando desabilitado — initRum() retorna imediatamente.
8	 *
9	 * Config via env:
10	 *   VITE_RUM_ENABLED     — segue VITE_OTEL_ENABLED por padrão
11	 *   VITE_RUM_SAMPLE_RATE — taxa de amostragem (padrão: '1.0')
12	 */
13	
14	import type { Histogram, Counter, UpDownCounter } from '@opentelemetry/api';
15	import { isInitialized, getTelemetryConfig } from './telemetry';
16	import { getGlobalAttributes } from './global-attributes';
17	
18	// ---------------------------------------------------------------------------
19	// Estado do módulo
20	// ---------------------------------------------------------------------------
21	
22	let _rumInitialized = false;
23	let _routeChangeCounter: Counter | null = null;
24	let _routeChangeDuration: Histogram | null = null;
25	let _webVitalHistogram: Histogram | null = null;
26	let _tbtHistogram: Histogram | null = null;
27	let _ttiHistogram: Histogram | null = null;
28	let _jsErrorCounter: Counter | null = null;
29	let _sessionCounter: Counter | null = null;
30	let _swRegistrationCounter: Counter | null = null;
31	let _swCacheHitRatioHistogram: Histogram | null = null;
32	let _installPromptCounter: Counter | null = null;
33	let _appInstallCounter: Counter | null = null;
34	let _resourceLoadHistogram: Histogram | null = null;
35	let _activeSessionsUpDown: UpDownCounter | null = null;
36	let _rumStoreChangeCounter: Counter | null = null;
37	
38	// Navegação — timestamps para medir duração de troca de rota
39	let _routeChangeStartTime: number | null = null;
40	let _routeChangeFromPath: string | null = null;
41	
42	// Tail sampling rates para RUM (mesmas env vars do wide-events)
43	let _tailSampleErrorRate = 1.0;
44	let _tailSampleSuccessRate = 0.01;
45	
46	// TBT — Total Blocking Time: soma de (duration - 50ms) para Long Tasks
47	let _tbtAccumulator = 0;
48	let _tbtReportTimer: ReturnType<typeof setInterval> | null = null;
49	
50	// TTI — Time to Interactive: último Long Task + 5s de quietude
51	let _lastLongTaskEnd = 0;
52	let _ttiTimer: ReturnType<typeof setTimeout> | null = null;
53	let _ttiReported = false;
54	
55	// PWA — Cache hit tracking via PerformanceObserver 'resource'
56	let _cacheHits = 0;
57	let _cacheTotal = 0;
58	let _cacheHitReportTimer: ReturnType<typeof setInterval> | null = null;
59	
60	// ---------------------------------------------------------------------------
61	// Inicialização
62	// ---------------------------------------------------------------------------
63	
64	export async function initRum(): Promise<void> {
65	  if (_rumInitialized) return;
66	
67	  const config = getTelemetryConfig();
68	  const env = import.meta.env;
69	  const rumEnabled =
70	    (env.VITE_RUM_ENABLED ?? (config.enabled ? 'true' : 'false')) === 'true';
71	
72	  if (!rumEnabled || !isInitialized()) {
73	    _rumInitialized = true;
74	    return;
75	  }
76	
77	  const { metrics } = await import('@opentelemetry/api');
78	  const meter = metrics.getMeter(config.serviceName, config.serviceVersion);
79	
80	  _routeChangeCounter = meter.createCounter('momma.rum.route_change.count', {
81	    description: 'Número de navegações entre rotas',
82	  });
83	  _routeChangeDuration = meter.createHistogram('momma.rum.route_change.duration', {
84	    description: 'Duração de navegação entre rotas em milissegundos',
85	    unit: 'ms',
86	  });
87	  _webVitalHistogram = meter.createHistogram('momma.rum.web_vital', {
88	    description: 'Métricas Web Vitals',
89	  });
90	  _tbtHistogram = meter.createHistogram('momma.rum.tbt', {
91	    description: 'Total Blocking Time — soma de Long Tasks (>50ms) em milissegundos',
92	    unit: 'ms',
93	  });
94	  _ttiHistogram = meter.createHistogram('momma.rum.tti', {
95	    description: 'Time to Interactive — estimativa via heurística de 5s sem Long Tasks',
96	    unit: 'ms',
97	  });
98	  _jsErrorCounter = meter.createCounter('momma.rum.js_error.count', {
99	    description: 'Erros JavaScript (uncaught e unhandled rejections)',
100	  });
101	  _sessionCounter = meter.createCounter('momma.rum.session.count', {
102	    description: 'Sessões RUM iniciadas (para cálculo de % de sessões com erro)',
103	  });
104	  _swRegistrationCounter = meter.createCounter('momma.rum.sw_registration.count', {
105	    description: 'Registros de Service Worker (success/failure)',
106	  });
107	  _swCacheHitRatioHistogram = meter.createHistogram('momma.rum.sw_cache_hit_ratio', {
108	    description: 'Taxa de cache hit do Service Worker (%)',
109	    unit: '%',
110	  });
111	  _installPromptCounter = meter.createCounter('momma.rum.install_prompt.count', {
112	    description: 'Eventos beforeinstallprompt (PWA install prompt exibido)',
113	  });
114	  _appInstallCounter = meter.createCounter('momma.rum.app_install.count', {
115	    description: 'Eventos appinstalled (PWA instalada)',
116	  });
117	  _resourceLoadHistogram = meter.createHistogram('momma.rum.resource_load.duration', {
118	    description: 'Tempo de carregamento de recursos (JS, CSS, Img, Font) em milissegundos',
119	    unit: 'ms',
120	  });
121	  _activeSessionsUpDown = meter.createUpDownCounter('momma.rum.active_sessions.count', {
122	    description: 'Sessões ativas no momento (incrementa no login, decrementa no logout/beforeunload)',
123	  });
124	  _rumStoreChangeCounter = meter.createCounter('momma.rum.store_change.count', {
125	    description: 'Trocas de unidade registradas no RUM',
126	  });
127	
128	  // Incrementar sessão 1x na inicialização
129	  _sessionCounter.add(1);
130	
131	  // Decrementar sessões ativas ao sair da página
132	  window.addEventListener('beforeunload', () => {
133	    _activeSessionsUpDown?.add(-1, _getRumSessionAttrs());
134	  });
135	
136	  // Tail sampling rates
137	  _tailSampleErrorRate =
138	    parseFloat(env.VITE_TAIL_SAMPLE_ERROR_RATE || '1.0') || 1.0;
139	  _tailSampleSuccessRate =
140	    parseFloat(env.VITE_TAIL_SAMPLE_SUCCESS_RATE || '0.01') || 0.01;
141	
142	  // Coletar Web Vitals com tail sampling por rating
143	  try {
144	    const webVitals = await import('web-vitals');
145	    const report =
146	      (name: string) =>
147	      (metric: { value: number; rating: 'good' | 'needs-improvement' | 'poor' }) => {
148	        // Tail sampling: 'poor' usa taxa de erro (100%), 'good'/'needs-improvement' usa taxa de sucesso (0.5%)
149	        const rate =
150	          metric.rating === 'poor' ? _tailSampleErrorRate : _tailSampleSuccessRate;
151	        if (rate < 1.0 && Math.random() >= rate) return;
152	
153	        _webVitalHistogram?.record(metric.value, {
154	          ..._getRumSessionAttrs(),
155	          'web_vital.name': name,
156	          'web_vital.rating': metric.rating,
157	        });
158	      };
159	    webVitals.onLCP(report('LCP'));
160	    webVitals.onINP(report('INP'));
161	    webVitals.onCLS(report('CLS'));
162	    webVitals.onTTFB(report('TTFB'));
163	    webVitals.onFCP(report('FCP'));
164	  } catch {
165	    // web-vitals não disponível — ignora silenciosamente
166	  }
167	
168	  // -------------------------------------------------------------------------
169	  // Long Tasks → TBT e TTI
170	  // -------------------------------------------------------------------------
171	  _initLongTaskObserver();
172	
173	  // -------------------------------------------------------------------------
174	  // Error Rates — JS errors e unhandled rejections
175	  // -------------------------------------------------------------------------
176	  _initErrorHandlers();
177	
178	  // -------------------------------------------------------------------------
179	  // PWA — Service Worker, Cache Hit Ratio, Install Prompt
180	  // -------------------------------------------------------------------------
181	  _initPwaMetrics();
182	
183	  _rumInitialized = true;
184	}
185	
186	// ---------------------------------------------------------------------------
187	// Long Tasks — TBT e TTI
188	// ---------------------------------------------------------------------------
189	
190	/**
191	 * Retorna atributos de sessão de baixa cardinalidade para labels de métricas RUM.
192	 * Lê atributos globais injetados pelo TelemetryContext via global-attributes.ts.
193	 * Atributos: user.role, unidade.nome, session.id, modulo, device.type, page.route
194	 */
195	function _getRumSessionAttrs(): Record<string, string> {
196	  const global = getGlobalAttributes();
197	  const attrs: Record<string, string> = {
198	    'page.route': window.location.pathname,
199	    'device.type': String(global['device.type'] || (
200	      /Mobi|Android/i.test(navigator.userAgent) ? 'mobile' :
201	      /Tablet|iPad/i.test(navigator.userAgent) ? 'tablet' : 'desktop'
202	    )),
203	  };
204	  if (global['user.role']) attrs['user.role'] = String(global['user.role']);
205	  if (global['unidade.nome']) attrs['unidade.nome'] = String(global['unidade.nome']);
206	  if (global['session.id']) attrs['session.id'] = String(global['session.id']);
207	  if (global['modulo']) attrs['modulo'] = String(global['modulo']);
208	  return attrs;
209	}
210	
211	function _reportTbt(): void {
212	  if (_tbtAccumulator <= 0) return;
213	  _tbtHistogram?.record(_tbtAccumulator, _getRumSessionAttrs());
214	  _tbtAccumulator = 0;
215	}
216	
217	function _scheduleTtiCheck(): void {
218	  if (_ttiReported) return;
219	  if (_ttiTimer !== null) clearTimeout(_ttiTimer);
220	  _ttiTimer = setTimeout(() => {
221	    if (_ttiReported) return;
222	    // 5s sem Long Tasks — TTI = fim do último Long Task
223	    _ttiHistogram?.record(_lastLongTaskEnd, _getRumSessionAttrs());
224	    _ttiReported = true;
225	  }, 5000);
226	}
227	
228	function _initLongTaskObserver(): void {
229	  if (typeof PerformanceObserver === 'undefined') return;
230	
231	  try {
232	    const observer = new PerformanceObserver((list) => {
233	      for (const entry of list.getEntries()) {
234	        // TBT: soma de (duration - 50ms) para cada Long Task
235	        if (entry.duration > 50) {
236	          _tbtAccumulator += entry.duration - 50;
237	        }
238	        // TTI: registrar fim do último Long Task e reiniciar timer de 5s
239	        _lastLongTaskEnd = entry.startTime + entry.duration;
240	        _scheduleTtiCheck();
241	      }
242	    });
243	    observer.observe({ type: 'longtask', buffered: true });
244	
245	    // Reportar TBT acumulado a cada 10s
246	    _tbtReportTimer = setInterval(_reportTbt, 10_000);
247	
248	    // Reportar TBT pendente quando a página perde foco (visibilitychange)
249	    document.addEventListener('visibilitychange', () => {
250	      if (document.visibilityState === 'hidden') {
251	        _reportTbt();
252	      }
253	    });
254	  } catch {
255	    // PerformanceObserver 'longtask' não suportado — ignora silenciosamente
256	  }
257	}
258	
259	// ---------------------------------------------------------------------------
260	// Error Rates — JS errors e unhandled promise rejections
261	// ---------------------------------------------------------------------------
262	
263	function _truncate(str: string, maxLen: number): string {
264	  return str.length > maxLen ? str.slice(0, maxLen) : str;
265	}
266	
267	/** Extrai pathname de uma URL (sem query string) e trunca */
268	function _truncateUrl(url: string, maxLen: number): string {
269	  try {
270	    const parsed = new URL(url);
271	    const pathname = parsed.pathname;
272	    return pathname.length > maxLen ? pathname.slice(0, maxLen) : pathname;
273	  } catch {
274	    return _truncate(url, maxLen);
275	  }
276	}
277	
278	function _initErrorHandlers(): void {
279	  // Erros JS não capturados (throw, referência a variável inexistente, etc.)
280	  window.addEventListener('error', (event: ErrorEvent) => {
281	    _jsErrorCounter?.add(1, {
282	      ..._getRumSessionAttrs(),
283	      'error.message': _truncate(event.message || 'unknown', 200),
284	      'error.source': event.filename || 'unknown',
285	    });
286	  });
287	
288	  // Promise rejections não tratadas
289	  window.addEventListener('unhandledrejection', (event: PromiseRejectionEvent) => {
290	    const message = event.reason instanceof Error
291	      ? event.reason.message
292	      : String(event.reason ?? 'unknown');
293	    _jsErrorCounter?.add(1, {
294	      ..._getRumSessionAttrs(),
295	      'error.message': _truncate(message, 200),
296	      'error.type': 'unhandledrejection',
297	    });
298	  });
299	}
300	
301	// ---------------------------------------------------------------------------
302	// PWA — Service Worker registration, Cache Hit Ratio, Install Prompt
303	// ---------------------------------------------------------------------------
304	
305	function _initPwaMetrics(): void {
306	  // Service Worker registration tracking
307	  if ('serviceWorker' in navigator) {
308	    navigator.serviceWorker.ready
309	      .then(() => {
310	        _swRegistrationCounter?.add(1, { result: 'success' });
311	      })
312	      .catch(() => {
313	        _swRegistrationCounter?.add(1, { result: 'failure' });
314	      });
315	  }
316	
317	  // Cache hit ratio + Resource Load Time via PerformanceObserver 'resource'
318	  if (typeof PerformanceObserver !== 'undefined') {
319	    try {
320	      const origin = window.location.origin;
321	      const observer = new PerformanceObserver((list) => {
322	        for (const entry of list.getEntries()) {
323	          const res = entry as PerformanceResourceTiming;
324	
325	          // Cache hit tracking (todas as resources)
326	          _cacheTotal++;
327	          if (res.transferSize === 0) {
328	            _cacheHits++;
329	          }
330	
331	          // Resource Load Time — apenas recursos do próprio domínio
332	          if (_resourceLoadHistogram && res.name.startsWith(origin)) {
333	            _resourceLoadHistogram.record(res.duration, {
334	              ..._getRumSessionAttrs(),
335	              'resource.type': res.initiatorType || 'other',
336	              'resource.name': _truncateUrl(res.name, 100),
337	              'resource.size': String(res.transferSize ?? 0),
338	              'resource.protocol': res.nextHopProtocol || 'unknown',
339	            });
340	          }
341	        }
342	      });
343	      observer.observe({ type: 'resource', buffered: true });
344	
345	      // Reportar cache hit ratio a cada 30s
346	      _cacheHitReportTimer = setInterval(() => {
347	        if (_cacheTotal === 0) return;
348	        const ratio = (_cacheHits / _cacheTotal) * 100;
349	        _swCacheHitRatioHistogram?.record(ratio, _getRumSessionAttrs());
350	        // Resetar contadores para próximo período
351	        _cacheHits = 0;
352	        _cacheTotal = 0;
353	      }, 30_000);
354	    } catch {
355	      // PerformanceObserver 'resource' não suportado — ignora silenciosamente
356	    }
357	  }
358	
359	  // PWA Install Prompt e Install tracking
360	  window.addEventListener('beforeinstallprompt', () => {
361	    _installPromptCounter?.add(1);
362	  });
363	  window.addEventListener('appinstalled', () => {
364	    _appInstallCounter?.add(1);
365	  });
366	}
367	
368	// ---------------------------------------------------------------------------
369	// Route tracking — usado pelo componente RouteTracker
370	// ---------------------------------------------------------------------------
371	
372	/** Chamado no início de uma navegação de rota */
373	export function onRouteChangeStart(fromPath: string): void {
374	  _routeChangeStartTime = performance.now();
375	  _routeChangeFromPath = fromPath;
376	}
377	
378	// ---------------------------------------------------------------------------
379	// Active Sessions — UpDownCounter (login/logout/beforeunload)
380	// ---------------------------------------------------------------------------
381	
382	/** Incrementa sessões ativas (chamar no login) */
383	export function rumSessionStart(): void {
384	  _activeSessionsUpDown?.add(1, _getRumSessionAttrs());
385	}
386	
387	/** Decrementa sessões ativas (chamar no logout) */
388	export function rumSessionEnd(): void {
389	  _activeSessionsUpDown?.add(-1, _getRumSessionAttrs());
390	}
391	
392	// ---------------------------------------------------------------------------
393	// Store Change — registra troca de unidade no RUM
394	// ---------------------------------------------------------------------------
395	
396	/** Registra troca de unidade com atributo unidade.nome */
397	export function recordRumStoreChange(unidadeNome: string): void {
398	  _rumStoreChangeCounter?.add(1, {
399	    ..._getRumSessionAttrs(),
400	    'unidade.nome': unidadeNome,
401	  });
402	}
403	
404	/** Chamado ao completar a navegação para a nova rota */
405	export function onRouteChangeComplete(toPath: string): void {
406	  if (_routeChangeStartTime === null) return;
407	
408	  const durationMs = performance.now() - _routeChangeStartTime;
409	  const attrs = {
410	    ..._getRumSessionAttrs(),
411	    'route.from': _routeChangeFromPath ?? 'unknown',
412	    'route.to': toPath,
413	  };
414	
415	  _routeChangeCounter?.add(1, attrs);
416	  _routeChangeDuration?.record(durationMs, attrs);
417	
