/**
 * Módulo de Real User Monitoring (RUM) via Web Vitals + OpenTelemetry.
 *
 * Coleta automaticamente Web Vitals (LCP, INP, CLS, TTFB, FCP)
 * e expõe helpers para rastreamento de navegação entre rotas.
 *
 * Zero overhead quando desabilitado — initRum() retorna imediatamente.
 *
 * Config via env:
 *   VITE_RUM_ENABLED     — segue VITE_OTEL_ENABLED por padrão
 *   VITE_RUM_SAMPLE_RATE — taxa de amostragem (padrão: '1.0')
 */

import type { Histogram, Counter, UpDownCounter } from '@opentelemetry/api';
import { isInitialized, getTelemetryConfig } from './telemetry';
import { getGlobalAttributes } from './global-attributes';

// ---------------------------------------------------------------------------
// Estado do módulo
// ---------------------------------------------------------------------------

let _rumInitialized = false;
let _routeChangeCounter: Counter | null = null;
let _routeChangeDuration: Histogram | null = null;
let _webVitalHistogram: Histogram | null = null;
let _tbtHistogram: Histogram | null = null;
let _ttiHistogram: Histogram | null = null;
let _jsErrorCounter: Counter | null = null;
let _sessionCounter: Counter | null = null;
let _swRegistrationCounter: Counter | null = null;
let _swCacheHitRatioHistogram: Histogram | null = null;
let _installPromptCounter: Counter | null = null;
let _appInstallCounter: Counter | null = null;
let _resourceLoadHistogram: Histogram | null = null;
let _activeSessionsUpDown: UpDownCounter | null = null;
let _rumStoreChangeCounter: Counter | null = null;

// Navegação — timestamps para medir duração de troca de rota
let _routeChangeStartTime: number | null = null;
let _routeChangeFromPath: string | null = null;

// Tail sampling rates para RUM (mesmas env vars do wide-events)
let _tailSampleErrorRate = 1.0;
let _tailSampleSuccessRate = 0.01;

// TBT — Total Blocking Time: soma de (duration - 50ms) para Long Tasks
let _tbtAccumulator = 0;
let _tbtReportTimer: ReturnType<typeof setInterval> | null = null;

// TTI — Time to Interactive: último Long Task + 5s de quietude
let _lastLongTaskEnd = 0;
let _ttiTimer: ReturnType<typeof setTimeout> | null = null;
let _ttiReported = false;

// PWA — Cache hit tracking via PerformanceObserver 'resource'
let _cacheHits = 0;
let _cacheTotal = 0;
let _cacheHitReportTimer: ReturnType<typeof setInterval> | null = null;

// ---------------------------------------------------------------------------
// Inicialização
// ---------------------------------------------------------------------------

export async function initRum(): Promise<void> {
  if (_rumInitialized) return;

  const config = getTelemetryConfig();
  const env = import.meta.env;
  const rumEnabled =
    (env.VITE_RUM_ENABLED ?? (config.enabled ? 'true' : 'false')) === 'true';

  if (!rumEnabled || !isInitialized()) {
    _rumInitialized = true;
    return;
  }

  const { metrics } = await import('@opentelemetry/api');
  const meter = metrics.getMeter(config.serviceName, config.serviceVersion);

  _routeChangeCounter = meter.createCounter('momma.rum.route_change.count', {
    description: 'Número de navegações entre rotas',
  });
  _routeChangeDuration = meter.createHistogram('momma.rum.route_change.duration', {
    description: 'Duração de navegação entre rotas em milissegundos',
    unit: 'ms',
  });
  _webVitalHistogram = meter.createHistogram('momma.rum.web_vital', {
    description: 'Métricas Web Vitals',
  });
  _tbtHistogram = meter.createHistogram('momma.rum.tbt', {
    description: 'Total Blocking Time — soma de Long Tasks (>50ms) em milissegundos',
    unit: 'ms',
  });
  _ttiHistogram = meter.createHistogram('momma.rum.tti', {
    description: 'Time to Interactive — estimativa via heurística de 5s sem Long Tasks',
    unit: 'ms',
  });
  _jsErrorCounter = meter.createCounter('momma.rum.js_error.count', {
    description: 'Erros JavaScript (uncaught e unhandled rejections)',
  });
  _sessionCounter = meter.createCounter('momma.rum.session.count', {
    description: 'Sessões RUM iniciadas (para cálculo de % de sessões com erro)',
  });
  _swRegistrationCounter = meter.createCounter('momma.rum.sw_registration.count', {
    description: 'Registros de Service Worker (success/failure)',
  });
  _swCacheHitRatioHistogram = meter.createHistogram('momma.rum.sw_cache_hit_ratio', {
    description: 'Taxa de cache hit do Service Worker (%)',
    unit: '%',
  });
  _installPromptCounter = meter.createCounter('momma.rum.install_prompt.count', {
    description: 'Eventos beforeinstallprompt (PWA install prompt exibido)',
  });
  _appInstallCounter = meter.createCounter('momma.rum.app_install.count', {
    description: 'Eventos appinstalled (PWA instalada)',
  });
  _resourceLoadHistogram = meter.createHistogram('momma.rum.resource_load.duration', {
    description: 'Tempo de carregamento de recursos (JS, CSS, Img, Font) em milissegundos',
    unit: 'ms',
  });
  _activeSessionsUpDown = meter.createUpDownCounter('momma.rum.active_sessions.count', {
    description: 'Sessões ativas no momento (incrementa no login, decrementa no logout/beforeunload)',
  });
  _rumStoreChangeCounter = meter.createCounter('momma.rum.store_change.count', {
    description: 'Trocas de unidade registradas no RUM',
  });

  // Incrementar sessão 1x na inicialização
  _sessionCounter.add(1);

  // Decrementar sessões ativas ao sair da página
  window.addEventListener('beforeunload', () => {
    _activeSessionsUpDown?.add(-1, _getRumSessionAttrs());
  });

  // Tail sampling rates
  _tailSampleErrorRate =
    parseFloat(env.VITE_TAIL_SAMPLE_ERROR_RATE || '1.0') || 1.0;
  _tailSampleSuccessRate =
    parseFloat(env.VITE_TAIL_SAMPLE_SUCCESS_RATE || '0.01') || 0.01;

  // Coletar Web Vitals com tail sampling por rating
  try {
    const webVitals = await import('web-vitals');
    const report =
      (name: string) =>
      (metric: { value: number; rating: 'good' | 'needs-improvement' | 'poor' }) => {
        // Tail sampling: 'poor' usa taxa de erro (100%), 'good'/'needs-improvement' usa taxa de sucesso (0.5%)
        const rate =
          metric.rating === 'poor' ? _tailSampleErrorRate : _tailSampleSuccessRate;
        if (rate < 1.0 && Math.random() >= rate) return;

        _webVitalHistogram?.record(metric.value, {
          ..._getRumSessionAttrs(),
          'web_vital.name': name,
          'web_vital.rating': metric.rating,
        });
      };
    webVitals.onLCP(report('LCP'));
    webVitals.onINP(report('INP'));
    webVitals.onCLS(report('CLS'));
    webVitals.onTTFB(report('TTFB'));
    webVitals.onFCP(report('FCP'));
  } catch {
    // web-vitals não disponível — ignora silenciosamente
  }

  // -------------------------------------------------------------------------
  // Long Tasks → TBT e TTI
  // -------------------------------------------------------------------------
  _initLongTaskObserver();

  // -------------------------------------------------------------------------
  // Error Rates — JS errors e unhandled rejections
  // -------------------------------------------------------------------------
  _initErrorHandlers();

  // -------------------------------------------------------------------------
  // PWA — Service Worker, Cache Hit Ratio, Install Prompt
  // -------------------------------------------------------------------------
  _initPwaMetrics();

  _rumInitialized = true;
}

// ---------------------------------------------------------------------------
// Long Tasks — TBT e TTI
// ---------------------------------------------------------------------------

/**
 * Retorna atributos de sessão de baixa cardinalidade para labels de métricas RUM.
 * Lê atributos globais injetados pelo TelemetryContext via global-attributes.ts.
 * Atributos: user.role, unidade.nome, session.id, modulo, device.type, page.route
 */
function _getRumSessionAttrs(): Record<string, string> {
  const global = getGlobalAttributes();
  const attrs: Record<string, string> = {
    'page.route': window.location.pathname,
    'device.type': String(global['device.type'] || (
      /Mobi|Android/i.test(navigator.userAgent) ? 'mobile' :
      /Tablet|iPad/i.test(navigator.userAgent) ? 'tablet' : 'desktop'
    )),
  };
  if (global['user.role']) attrs['user.role'] = String(global['user.role']);
  if (global['unidade.nome']) attrs['unidade.nome'] = String(global['unidade.nome']);
  if (global['session.id']) attrs['session.id'] = String(global['session.id']);
  if (global['modulo']) attrs['modulo'] = String(global['modulo']);
  return attrs;
}

function _reportTbt(): void {
  if (_tbtAccumulator <= 0) return;
  _tbtHistogram?.record(_tbtAccumulator, _getRumSessionAttrs());
  _tbtAccumulator = 0;
}

function _scheduleTtiCheck(): void {
  if (_ttiReported) return;
  if (_ttiTimer !== null) clearTimeout(_ttiTimer);
  _ttiTimer = setTimeout(() => {
    if (_ttiReported) return;
    // 5s sem Long Tasks — TTI = fim do último Long Task
    _ttiHistogram?.record(_lastLongTaskEnd, _getRumSessionAttrs());
    _ttiReported = true;
  }, 5000);
}

function _initLongTaskObserver(): void {
  if (typeof PerformanceObserver === 'undefined') return;

  try {
    const observer = new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        // TBT: soma de (duration - 50ms) para cada Long Task
        if (entry.duration > 50) {
          _tbtAccumulator += entry.duration - 50;
        }
        // TTI: registrar fim do último Long Task e reiniciar timer de 5s
        _lastLongTaskEnd = entry.startTime + entry.duration;
        _scheduleTtiCheck();
      }
    });
    observer.observe({ type: 'longtask', buffered: true });

    // Reportar TBT acumulado a cada 10s
    _tbtReportTimer = setInterval(_reportTbt, 10_000);

    // Reportar TBT pendente quando a página perde foco (visibilitychange)
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden') {
        _reportTbt();
      }
    });
  } catch {
    // PerformanceObserver 'longtask' não suportado — ignora silenciosamente
  }
}

// ---------------------------------------------------------------------------
// Error Rates — JS errors e unhandled promise rejections
// ---------------------------------------------------------------------------

function _truncate(str: string, maxLen: number): string {
  return str.length > maxLen ? str.slice(0, maxLen) : str;
}

/** Extrai pathname de uma URL (sem query string) e trunca */
function _truncateUrl(url: string, maxLen: number): string {
  try {
    const parsed = new URL(url);
    const pathname = parsed.pathname;
    return pathname.length > maxLen ? pathname.slice(0, maxLen) : pathname;
  } catch {
    return _truncate(url, maxLen);
  }
}

function _initErrorHandlers(): void {
  // Erros JS não capturados (throw, referência a variável inexistente, etc.)
  window.addEventListener('error', (event: ErrorEvent) => {
    _jsErrorCounter?.add(1, {
      ..._getRumSessionAttrs(),
      'error.message': _truncate(event.message || 'unknown', 200),
      'error.source': event.filename || 'unknown',
    });
  });

  // Promise rejections não tratadas
  window.addEventListener('unhandledrejection', (event: PromiseRejectionEvent) => {
    const message = event.reason instanceof Error
      ? event.reason.message
      : String(event.reason ?? 'unknown');
    _jsErrorCounter?.add(1, {
      ..._getRumSessionAttrs(),
      'error.message': _truncate(message, 200),
      'error.type': 'unhandledrejection',
    });
  });
}

// ---------------------------------------------------------------------------
// PWA — Service Worker registration, Cache Hit Ratio, Install Prompt
// ---------------------------------------------------------------------------

function _initPwaMetrics(): void {
  // Service Worker registration tracking
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.ready
      .then(() => {
        _swRegistrationCounter?.add(1, { result: 'success' });
      })
      .catch(() => {
        _swRegistrationCounter?.add(1, { result: 'failure' });
      });
  }

  // Cache hit ratio + Resource Load Time via PerformanceObserver 'resource'
  if (typeof PerformanceObserver !== 'undefined') {
    try {
      const origin = window.location.origin;
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          const res = entry as PerformanceResourceTiming;

          // Cache hit tracking (todas as resources)
          _cacheTotal++;
          if (res.transferSize === 0) {
            _cacheHits++;
          }

          // Resource Load Time — apenas recursos do próprio domínio
          if (_resourceLoadHistogram && res.name.startsWith(origin)) {
            _resourceLoadHistogram.record(res.duration, {
              ..._getRumSessionAttrs(),
              'resource.type': res.initiatorType || 'other',
              'resource.name': _truncateUrl(res.name, 100),
              'resource.size': String(res.transferSize ?? 0),
              'resource.protocol': res.nextHopProtocol || 'unknown',
            });
          }
        }
      });
      observer.observe({ type: 'resource', buffered: true });

      // Reportar cache hit ratio a cada 30s
      _cacheHitReportTimer = setInterval(() => {
        if (_cacheTotal === 0) return;
        const ratio = (_cacheHits / _cacheTotal) * 100;
        _swCacheHitRatioHistogram?.record(ratio, _getRumSessionAttrs());
        // Resetar contadores para próximo período
        _cacheHits = 0;
        _cacheTotal = 0;
      }, 30_000);
    } catch {
      // PerformanceObserver 'resource' não suportado — ignora silenciosamente
    }
  }

  // PWA Install Prompt e Install tracking
  window.addEventListener('beforeinstallprompt', () => {
    _installPromptCounter?.add(1);
  });
  window.addEventListener('appinstalled', () => {
    _appInstallCounter?.add(1);
  });
}

// ---------------------------------------------------------------------------
// Route tracking — usado pelo componente RouteTracker
// ---------------------------------------------------------------------------

/** Chamado no início de uma navegação de rota */
export function onRouteChangeStart(fromPath: string): void {
  _routeChangeStartTime = performance.now();
  _routeChangeFromPath = fromPath;
}

// ---------------------------------------------------------------------------
// Active Sessions — UpDownCounter (login/logout/beforeunload)
// ---------------------------------------------------------------------------

/** Incrementa sessões ativas (chamar no login) */
export function rumSessionStart(): void {
  _activeSessionsUpDown?.add(1, _getRumSessionAttrs());
}

/** Decrementa sessões ativas (chamar no logout) */
export function rumSessionEnd(): void {
  _activeSessionsUpDown?.add(-1, _getRumSessionAttrs());
}

// ---------------------------------------------------------------------------
// Store Change — registra troca de unidade no RUM
// ---------------------------------------------------------------------------

/** Registra troca de unidade com atributo unidade.nome */
export function recordRumStoreChange(unidadeNome: string): void {
  _rumStoreChangeCounter?.add(1, {
    ..._getRumSessionAttrs(),
    'unidade.nome': unidadeNome,
  });
}

/** Chamado ao completar a navegação para a nova rota */
export function onRouteChangeComplete(toPath: string): void {
  if (_routeChangeStartTime === null) return;

  const durationMs = performance.now() - _routeChangeStartTime;
  const attrs = {
    ..._getRumSessionAttrs(),
    'route.from': _routeChangeFromPath ?? 'unknown',
    'route.to': toPath,
  };

  _routeChangeCounter?.add(1, attrs);
  _routeChangeDuration?.record(durationMs, attrs);

  _routeChangeStartTime = null;
  _routeChangeFromPath = null;
}

