-- MIA Behavioral Intelligence — SOTA learning pipeline
-- Captura completa de comportamento + aprendizado contínuo + proativo

-- ============================================================
-- 1. gidape_events — stream behavioural (L1)
-- ============================================================
CREATE TABLE IF NOT EXISTS gidape_events (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    session_id  text NOT NULL,
    event_type  text NOT NULL,   -- page_enter | page_exit | feature_use | search_query | mia_opened | mia_suggestion_acted | click | form_submit | error_seen
    page        text NOT NULL,   -- route pathname
    properties  jsonb NOT NULL DEFAULT '{}',
    -- derivado para filtragem rápida
    loja_id     int4,
    role        text,
    device_type text,            -- mobile | tablet | desktop
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS gidape_events_user_id_idx    ON gidape_events(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS gidape_events_session_idx    ON gidape_events(session_id, created_at);
CREATE INDEX IF NOT EXISTS gidape_events_type_idx       ON gidape_events(event_type, created_at DESC);
CREATE INDEX IF NOT EXISTS gidape_events_page_idx       ON gidape_events(page, created_at DESC);

ALTER TABLE gidape_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "gidape_events_insert_own" ON gidape_events FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "gidape_events_select_own" ON gidape_events FOR SELECT USING (auth.uid() = user_id);
-- admins podem ver todos
CREATE POLICY "gidape_events_select_admin" ON gidape_events FOR SELECT
    USING (EXISTS (
        SELECT 1 FROM profiles WHERE id = auth.uid()
            AND role IN ('admin', 'master', 'administrator')
    ));

-- ============================================================
-- 2. user_nav_graph — grafo de transições de página (L3)
-- ============================================================
CREATE TABLE IF NOT EXISTS user_nav_graph (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    from_page   text NOT NULL,
    to_page     text NOT NULL,
    weight      int4 NOT NULL DEFAULT 1,   -- frequência acumulada
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(user_id, from_page, to_page)
);

CREATE INDEX IF NOT EXISTS user_nav_graph_user_idx ON user_nav_graph(user_id, weight DESC);

ALTER TABLE user_nav_graph ENABLE ROW LEVEL SECURITY;
CREATE POLICY "nav_graph_own" ON user_nav_graph FOR ALL USING (auth.uid() = user_id);

-- ============================================================
-- 3. user_loops — loops de fricção detectados (L3)
-- ============================================================
CREATE TABLE IF NOT EXISTS user_loops (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    loop_pages    text[] NOT NULL,    -- sequência que se repete (ex: ['/estoque', '/requisicao', '/estoque'])
    occurrences   int4 NOT NULL DEFAULT 1,
    first_seen_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at  timestamptz NOT NULL DEFAULT now(),
    resolved      bool NOT NULL DEFAULT false
);

CREATE INDEX IF NOT EXISTS user_loops_user_idx ON user_loops(user_id, last_seen_at DESC);

ALTER TABLE user_loops ENABLE ROW LEVEL SECURITY;
CREATE POLICY "user_loops_own" ON user_loops FOR ALL USING (auth.uid() = user_id);

-- ============================================================
-- 4. mia_counterfactual_sessions — sessões sem MIA (Padrão 2)
-- ============================================================
CREATE TABLE IF NOT EXISTS mia_counterfactual_sessions (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    session_id      text NOT NULL UNIQUE,
    started_at      timestamptz NOT NULL DEFAULT now(),
    ended_at        timestamptz,
    duration_ms     int8,
    pages_visited   text[] NOT NULL DEFAULT '{}',
    page_count      int4 NOT NULL DEFAULT 0,
    loops_detected  int4 NOT NULL DEFAULT 0,
    mia_opened      bool NOT NULL DEFAULT false,   -- se true → sessão de controle, não counterfactual
    -- métricas de tarefa (estimadas via dwell_time)
    avg_dwell_ms    int8,
    total_clicks    int4 NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS mia_cf_sessions_user_idx ON mia_counterfactual_sessions(user_id, started_at DESC);

ALTER TABLE mia_counterfactual_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "mia_cf_own" ON mia_counterfactual_sessions FOR ALL USING (auth.uid() = user_id);

-- ============================================================
-- 5. mia_distilled_patterns — output do distillation loop (Padrão 1)
-- ============================================================
CREATE TABLE IF NOT EXISTS mia_distilled_patterns (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    scope        text NOT NULL,    -- 'global' | 'role:gerente' | 'user:<uuid>'
    category     text NOT NULL,    -- 'skill_update' | 'workflow_pattern' | 'language_pattern' | 'friction_insight'
    title        text NOT NULL,
    content      text NOT NULL,    -- texto injetável no prompt MIA
    evidence     jsonb NOT NULL DEFAULT '{}',   -- métricas que suportam o pattern
    confidence   float4 NOT NULL DEFAULT 0.7,
    active       bool NOT NULL DEFAULT true,
    distilled_at timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz,      -- null = permanente
    created_by   text NOT NULL DEFAULT 'mia-distillation'
);

CREATE INDEX IF NOT EXISTS mia_distilled_active_idx ON mia_distilled_patterns(active, scope, distilled_at DESC);

ALTER TABLE mia_distilled_patterns ENABLE ROW LEVEL SECURITY;
-- só service_role escreve; usuários lêem apenas os de scope global/role
CREATE POLICY "mia_distilled_select" ON mia_distilled_patterns FOR SELECT USING (
    active = true AND (
        scope = 'global' OR
        scope LIKE 'role:%' OR
        scope = 'user:' || auth.uid()::text
    )
);

-- ============================================================
-- 6. mia_proactive_queue — fila de notificações proativas (L4)
-- ============================================================
CREATE TABLE IF NOT EXISTS mia_proactive_queue (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    type         text NOT NULL,    -- 'morning_digest' | 'anomaly' | 'pattern_insight' | 'loop_friction'
    title        text NOT NULL,
    body         text NOT NULL,
    context      jsonb NOT NULL DEFAULT '{}',
    priority     int4 NOT NULL DEFAULT 5,   -- 1=crítico, 10=informacional
    delivered    bool NOT NULL DEFAULT false,
    delivered_at timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL DEFAULT (now() + interval '24 hours')
);

CREATE INDEX IF NOT EXISTS mia_proactive_user_idx ON mia_proactive_queue(user_id, delivered, created_at DESC);

ALTER TABLE mia_proactive_queue ENABLE ROW LEVEL SECURITY;
CREATE POLICY "mia_proactive_own" ON mia_proactive_queue FOR SELECT USING (auth.uid() = user_id);

-- ============================================================
-- 7. Extensão de mia_user_patterns (novas colunas comportamentais)
-- ============================================================
DO $$ BEGIN
    -- top_pages: rotas mais acessadas com frequência
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'top_pages'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN top_pages jsonb DEFAULT '[]';
    END IF;

    -- top_flows: sequências de navegação mais comuns (array de arrays)
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'top_flows'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN top_flows jsonb DEFAULT '[]';
    END IF;

    -- peak_hours: {hour: count} — quando o usuário é mais ativo
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'peak_hours'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN peak_hours jsonb DEFAULT '{}';
    END IF;

    -- avg_dwell_ms por página: {route: avg_ms}
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'avg_dwell_ms'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN avg_dwell_ms jsonb DEFAULT '{}';
    END IF;

    -- feature_usage_map: {feature_id: count}
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'feature_usage_map'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN feature_usage_map jsonb DEFAULT '{}';
    END IF;

    -- loop_count: total de loops de fricção detectados
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'loop_count'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN loop_count int4 DEFAULT 0;
    END IF;

    -- last_loop_detected_at
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'last_loop_detected_at'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN last_loop_detected_at timestamptz;
    END IF;

    -- mia_suggestion_act_rate: taxa de aceitação de sugestões da MIA (0.0–1.0)
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'mia_suggestion_act_rate'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN mia_suggestion_act_rate float4 DEFAULT 0;
    END IF;

    -- counterfactual_avg_dwell_ms: tempo médio em páginas SEM MIA (baseline)
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'counterfactual_avg_dwell_ms'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN counterfactual_avg_dwell_ms int8;
    END IF;

    -- behavioral_updated_at: última vez que o perfil comportamental foi recalculado
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'behavioral_updated_at'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN behavioral_updated_at timestamptz;
    END IF;
END $$;

-- ============================================================
-- 8. Trigger: atualiza perfil comportamental em tempo real
--    após cada insert em gidape_events
-- ============================================================
CREATE OR REPLACE FUNCTION fn_update_behavioral_profile()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_hour int4;
    v_peak jsonb;
    v_feat jsonb;
    v_feat_id text;
    v_feat_count int4;
    v_pages jsonb;
    v_page_entry jsonb;
    v_page_found bool := false;
    v_dwell_ms int8;
    v_page text;
    v_from text;
    v_to text;
BEGIN
    v_hour := EXTRACT(HOUR FROM NEW.created_at)::int4;
    v_page := NEW.page;

    -- Garante linha em mia_user_patterns
    INSERT INTO mia_user_patterns(user_id)
        VALUES(NEW.user_id)
        ON CONFLICT (user_id) DO NOTHING;

    -- Atualiza peak_hours
    SELECT COALESCE(peak_hours, '{}') INTO v_peak FROM mia_user_patterns WHERE user_id = NEW.user_id;
    v_peak := jsonb_set(v_peak, ARRAY[v_hour::text], to_jsonb(COALESCE((v_peak ->> v_hour::text)::int4, 0) + 1));

    -- Contabiliza feature_use
    IF NEW.event_type = 'feature_use' THEN
        v_feat_id := NEW.properties->>'feature_id';
        IF v_feat_id IS NOT NULL THEN
            SELECT COALESCE(feature_usage_map, '{}') INTO v_feat FROM mia_user_patterns WHERE user_id = NEW.user_id;
            v_feat_count := COALESCE((v_feat ->> v_feat_id)::int4, 0) + 1;
            v_feat := jsonb_set(v_feat, ARRAY[v_feat_id], to_jsonb(v_feat_count));
            UPDATE mia_user_patterns
                SET feature_usage_map = v_feat,
                    peak_hours = v_peak,
                    behavioral_updated_at = now()
                WHERE user_id = NEW.user_id;
            RETURN NEW;
        END IF;
    END IF;

    -- page_exit: atualiza avg_dwell_ms por página e nav_graph
    IF NEW.event_type = 'page_exit' THEN
        v_dwell_ms := (NEW.properties->>'dwell_ms')::int8;
        v_from := v_page;
        v_to := NEW.properties->>'next_page';

        -- Atualiza avg_dwell_ms no perfil
        IF v_dwell_ms IS NOT NULL AND v_dwell_ms > 0 THEN
            DECLARE
                v_dwell_map jsonb;
                v_old_avg int8;
                v_old_count int4;
                v_new_avg int8;
            BEGIN
                SELECT COALESCE(avg_dwell_ms, '{}') INTO v_dwell_map FROM mia_user_patterns WHERE user_id = NEW.user_id;
                v_old_avg := COALESCE((v_dwell_map -> v_page ->> 'avg')::int8, 0);
                v_old_count := COALESCE((v_dwell_map -> v_page ->> 'count')::int4, 0);
                v_new_avg := ((v_old_avg * v_old_count) + v_dwell_ms) / (v_old_count + 1);
                v_dwell_map := jsonb_set(
                    v_dwell_map,
                    ARRAY[v_page],
                    jsonb_build_object('avg', v_new_avg, 'count', v_old_count + 1)
                );
                UPDATE mia_user_patterns
                    SET avg_dwell_ms = v_dwell_map, peak_hours = v_peak, behavioral_updated_at = now()
                    WHERE user_id = NEW.user_id;
            END;
        END IF;

        -- Atualiza nav_graph (from → to)
        IF v_from IS NOT NULL AND v_to IS NOT NULL AND v_from != v_to THEN
            INSERT INTO user_nav_graph(user_id, from_page, to_page, weight, last_seen_at)
                VALUES(NEW.user_id, v_from, v_to, 1, now())
                ON CONFLICT (user_id, from_page, to_page)
                DO UPDATE SET weight = user_nav_graph.weight + 1, last_seen_at = now();
        END IF;

        RETURN NEW;
    END IF;

    -- mia_suggestion_acted: atualiza taxa de aceitação
    IF NEW.event_type = 'mia_suggestion_acted' THEN
        UPDATE mia_user_patterns
            SET mia_suggestion_act_rate = (
                -- média móvel exponencial simples (α=0.2)
                COALESCE(mia_suggestion_act_rate, 0) * 0.8 +
                CASE WHEN (NEW.properties->>'acted')::bool THEN 0.2 ELSE 0 END
            ),
            peak_hours = v_peak,
            behavioral_updated_at = now()
            WHERE user_id = NEW.user_id;
        RETURN NEW;
    END IF;

    -- Atualiza top_pages
    IF NEW.event_type = 'page_enter' THEN
        SELECT COALESCE(top_pages, '[]') INTO v_pages FROM mia_user_patterns WHERE user_id = NEW.user_id;

        -- Procura página existente no array e incrementa count
        SELECT
            (SELECT jsonb_agg(
                CASE WHEN elem->>'page' = v_page
                    THEN jsonb_set(elem, '{count}', to_jsonb((elem->>'count')::int4 + 1))
                    ELSE elem END
            ) FROM jsonb_array_elements(v_pages) elem),
            EXISTS(SELECT 1 FROM jsonb_array_elements(v_pages) elem WHERE elem->>'page' = v_page)
        INTO v_pages, v_page_found;

        IF NOT v_page_found THEN
            v_pages := v_pages || jsonb_build_object('page', v_page, 'count', 1);
        END IF;

        -- Mantém top-20 por count
        SELECT jsonb_agg(elem ORDER BY (elem->>'count')::int4 DESC)
            FROM (SELECT elem FROM jsonb_array_elements(v_pages) elem LIMIT 20) sub
            INTO v_pages;

        UPDATE mia_user_patterns
            SET top_pages = COALESCE(v_pages, '[]'),
                peak_hours = v_peak,
                behavioral_updated_at = now()
            WHERE user_id = NEW.user_id;
        RETURN NEW;
    END IF;

    -- Fallback: só atualiza peak_hours
    UPDATE mia_user_patterns
        SET peak_hours = v_peak, behavioral_updated_at = now()
        WHERE user_id = NEW.user_id;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_gidape_events_update_profile ON gidape_events;
CREATE TRIGGER trg_gidape_events_update_profile
    AFTER INSERT ON gidape_events
    FOR EACH ROW EXECUTE FUNCTION fn_update_behavioral_profile();

-- ============================================================
-- 9. View: behavioral profile rico para MIA consumir
-- ============================================================
CREATE OR REPLACE VIEW vw_user_behavioral_profile AS
SELECT
    p.user_id,
    p.total_queries,
    p.preferred_format,
    p.verbosity_pref,
    p.expertise_level,
    p.top_tools,
    p.top_intents,
    p.top_modules,
    p.top_pages,
    p.top_flows,
    p.peak_hours,
    p.avg_dwell_ms,
    p.feature_usage_map,
    p.loop_count,
    p.last_loop_detected_at,
    p.mia_suggestion_act_rate,
    p.counterfactual_avg_dwell_ms,
    p.behavioral_updated_at,
    -- Top 5 transições de navegação mais frequentes
    (
        SELECT jsonb_agg(jsonb_build_object('from', from_page, 'to', to_page, 'weight', weight) ORDER BY weight DESC)
        FROM (SELECT from_page, to_page, weight FROM user_nav_graph WHERE user_id = p.user_id ORDER BY weight DESC LIMIT 5) t
    ) AS top_nav_transitions,
    -- Loop mais recente não resolvido
    (
        SELECT jsonb_build_object('pages', loop_pages, 'occurrences', occurrences, 'last_seen', last_seen_at)
        FROM user_loops WHERE user_id = p.user_id AND resolved = false ORDER BY last_seen_at DESC LIMIT 1
    ) AS active_loop
FROM mia_user_patterns p;

COMMENT ON VIEW vw_user_behavioral_profile IS 'Perfil comportamental completo por usuário — injetado no prompt MIA a cada turn';

-- ============================================================
-- 10. RPC para MIA buscar perfil comportamental
-- ============================================================
CREATE OR REPLACE FUNCTION get_behavioral_profile(p_user_id uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER AS $$
    SELECT row_to_json(v)::jsonb FROM vw_user_behavioral_profile v WHERE user_id = p_user_id;
$$;

-- ============================================================
-- 11. Distilled patterns ativos por scope
-- ============================================================
CREATE OR REPLACE FUNCTION get_distilled_patterns(p_scope text DEFAULT 'global')
RETURNS TABLE (title text, content text, category text, confidence float4) LANGUAGE sql STABLE SECURITY DEFINER AS $$
    SELECT title, content, category, confidence
    FROM mia_distilled_patterns
    WHERE active = true
        AND (scope = p_scope OR scope = 'global')
        AND (expires_at IS NULL OR expires_at > now())
    ORDER BY confidence DESC, distilled_at DESC
    LIMIT 20;
$$;

toolUseResult.content:
-- MIA Behavioral Intelligence — SOTA learning pipeline
-- Captura completa de comportamento + aprendizado contínuo + proativo

-- ============================================================
-- 1. gidape_events — stream behavioural (L1)
-- ============================================================
CREATE TABLE IF NOT EXISTS gidape_events (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    session_id  text NOT NULL,
    event_type  text NOT NULL,   -- page_enter | page_exit | feature_use | search_query | mia_opened | mia_suggestion_acted | click | form_submit | error_seen
    page        text NOT NULL,   -- route pathname
    properties  jsonb NOT NULL DEFAULT '{}',
    -- derivado para filtragem rápida
    loja_id     int4,
    role        text,
    device_type text,            -- mobile | tablet | desktop
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS gidape_events_user_id_idx    ON gidape_events(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS gidape_events_session_idx    ON gidape_events(session_id, created_at);
CREATE INDEX IF NOT EXISTS gidape_events_type_idx       ON gidape_events(event_type, created_at DESC);
CREATE INDEX IF NOT EXISTS gidape_events_page_idx       ON gidape_events(page, created_at DESC);

ALTER TABLE gidape_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "gidape_events_insert_own" ON gidape_events FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "gidape_events_select_own" ON gidape_events FOR SELECT USING (auth.uid() = user_id);
-- admins podem ver todos
CREATE POLICY "gidape_events_select_admin" ON gidape_events FOR SELECT
    USING (EXISTS (
        SELECT 1 FROM profiles WHERE id = auth.uid()
            AND role IN ('admin', 'master', 'administrator')
    ));

-- ============================================================
-- 2. user_nav_graph — grafo de transições de página (L3)
-- ============================================================
CREATE TABLE IF NOT EXISTS user_nav_graph (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    from_page   text NOT NULL,
    to_page     text NOT NULL,
    weight      int4 NOT NULL DEFAULT 1,   -- frequência acumulada
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(user_id, from_page, to_page)
);

CREATE INDEX IF NOT EXISTS user_nav_graph_user_idx ON user_nav_graph(user_id, weight DESC);

ALTER TABLE user_nav_graph ENABLE ROW LEVEL SECURITY;
CREATE POLICY "nav_graph_own" ON user_nav_graph FOR ALL USING (auth.uid() = user_id);

-- ============================================================
-- 3. user_loops — loops de fricção detectados (L3)
-- ============================================================
CREATE TABLE IF NOT EXISTS user_loops (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    loop_pages    text[] NOT NULL,    -- sequência que se repete (ex: ['/estoque', '/requisicao', '/estoque'])
    occurrences   int4 NOT NULL DEFAULT 1,
    first_seen_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at  timestamptz NOT NULL DEFAULT now(),
    resolved      bool NOT NULL DEFAULT false
);

CREATE INDEX IF NOT EXISTS user_loops_user_idx ON user_loops(user_id, last_seen_at DESC);

ALTER TABLE user_loops ENABLE ROW LEVEL SECURITY;
CREATE POLICY "user_loops_own" ON user_loops FOR ALL USING (auth.uid() = user_id);

-- ============================================================
-- 4. mia_counterfactual_sessions — sessões sem MIA (Padrão 2)
-- ============================================================
CREATE TABLE IF NOT EXISTS mia_counterfactual_sessions (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    session_id      text NOT NULL UNIQUE,
    started_at      timestamptz NOT NULL DEFAULT now(),
    ended_at        timestamptz,
    duration_ms     int8,
    pages_visited   text[] NOT NULL DEFAULT '{}',
    page_count      int4 NOT NULL DEFAULT 0,
    loops_detected  int4 NOT NULL DEFAULT 0,
    mia_opened      bool NOT NULL DEFAULT false,   -- se true → sessão de controle, não counterfactual
    -- métricas de tarefa (estimadas via dwell_time)
    avg_dwell_ms    int8,
    total_clicks    int4 NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS mia_cf_sessions_user_idx ON mia_counterfactual_sessions(user_id, started_at DESC);

ALTER TABLE mia_counterfactual_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "mia_cf_own" ON mia_counterfactual_sessions FOR ALL USING (auth.uid() = user_id);

-- ============================================================
-- 5. mia_distilled_patterns — output do distillation loop (Padrão 1)
-- ============================================================
CREATE TABLE IF NOT EXISTS mia_distilled_patterns (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    scope        text NOT NULL,    -- 'global' | 'role:gerente' | 'user:<uuid>'
    category     text NOT NULL,    -- 'skill_update' | 'workflow_pattern' | 'language_pattern' | 'friction_insight'
    title        text NOT NULL,
    content      text NOT NULL,    -- texto injetável no prompt MIA
    evidence     jsonb NOT NULL DEFAULT '{}',   -- métricas que suportam o pattern
    confidence   float4 NOT NULL DEFAULT 0.7,
    active       bool NOT NULL DEFAULT true,
    distilled_at timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz,      -- null = permanente
    created_by   text NOT NULL DEFAULT 'mia-distillation'
);

CREATE INDEX IF NOT EXISTS mia_distilled_active_idx ON mia_distilled_patterns(active, scope, distilled_at DESC);

ALTER TABLE mia_distilled_patterns ENABLE ROW LEVEL SECURITY;
-- só service_role escreve; usuários lêem apenas os de scope global/role
CREATE POLICY "mia_distilled_select" ON mia_distilled_patterns FOR SELECT USING (
    active = true AND (
        scope = 'global' OR
        scope LIKE 'role:%' OR
        scope = 'user:' || auth.uid()::text
    )
);

-- ============================================================
-- 6. mia_proactive_queue — fila de notificações proativas (L4)
-- ============================================================
CREATE TABLE IF NOT EXISTS mia_proactive_queue (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    type         text NOT NULL,    -- 'morning_digest' | 'anomaly' | 'pattern_insight' | 'loop_friction'
    title        text NOT NULL,
    body         text NOT NULL,
    context      jsonb NOT NULL DEFAULT '{}',
    priority     int4 NOT NULL DEFAULT 5,   -- 1=crítico, 10=informacional
    delivered    bool NOT NULL DEFAULT false,
    delivered_at timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL DEFAULT (now() + interval '24 hours')
);

CREATE INDEX IF NOT EXISTS mia_proactive_user_idx ON mia_proactive_queue(user_id, delivered, created_at DESC);

ALTER TABLE mia_proactive_queue ENABLE ROW LEVEL SECURITY;
CREATE POLICY "mia_proactive_own" ON mia_proactive_queue FOR SELECT USING (auth.uid() = user_id);

-- ============================================================
-- 7. Extensão de mia_user_patterns (novas colunas comportamentais)
-- ============================================================
DO $$ BEGIN
    -- top_pages: rotas mais acessadas com frequência
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'top_pages'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN top_pages jsonb DEFAULT '[]';
    END IF;

    -- top_flows: sequências de navegação mais comuns (array de arrays)
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'top_flows'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN top_flows jsonb DEFAULT '[]';
    END IF;

    -- peak_hours: {hour: count} — quando o usuário é mais ativo
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'peak_hours'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN peak_hours jsonb DEFAULT '{}';
    END IF;

    -- avg_dwell_ms por página: {route: avg_ms}
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'avg_dwell_ms'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN avg_dwell_ms jsonb DEFAULT '{}';
    END IF;

    -- feature_usage_map: {feature_id: count}
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'feature_usage_map'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN feature_usage_map jsonb DEFAULT '{}';
    END IF;

    -- loop_count: total de loops de fricção detectados
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'loop_count'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN loop_count int4 DEFAULT 0;
    END IF;

    -- last_loop_detected_at
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'last_loop_detected_at'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN last_loop_detected_at timestamptz;
    END IF;

    -- mia_suggestion_act_rate: taxa de aceitação de sugestões da MIA (0.0–1.0)
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'mia_suggestion_act_rate'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN mia_suggestion_act_rate float4 DEFAULT 0;
    END IF;

    -- counterfactual_avg_dwell_ms: tempo médio em páginas SEM MIA (baseline)
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'counterfactual_avg_dwell_ms'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN counterfactual_avg_dwell_ms int8;
    END IF;

    -- behavioral_updated_at: última vez que o perfil comportamental foi recalculado
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'mia_user_patterns' AND column_name = 'behavioral_updated_at'
    ) THEN
        ALTER TABLE mia_user_patterns ADD COLUMN behavioral_updated_at timestamptz;
    END IF;
END $$;

-- ============================================================
-- 8. Trigger: atualiza perfil comportamental em tempo real
--    após cada insert em gidape_events
-- ============================================================
CREATE OR REPLACE FUNCTION fn_update_behavioral_profile()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_hour int4;
    v_peak jsonb;
    v_feat jsonb;
    v_feat_id text;
    v_feat_count int4;
    v_pages jsonb;
    v_page_entry jsonb;
    v_page_found bool := false;
    v_dwell_ms int8;
    v_page text;
    v_from text;
    v_to text;
BEGIN
    v_hour := EXTRACT(HOUR FROM NEW.created_at)::int4;
    v_page := NEW.page;

    -- Garante linha em mia_user_patterns
    INSERT INTO mia_user_patterns(user_id)
        VALUES(NEW.user_id)
        ON CONFLICT (user_id) DO NOTHING;

    -- Atualiza peak_hours
    SELECT COALESCE(peak_hours, '{}') INTO v_peak FROM mia_user_patterns WHERE user_id = NEW.user_id;
    v_peak := jsonb_set(v_peak, ARRAY[v_hour::text], to_jsonb(COALESCE((v_peak ->> v_hour::text)::int4, 0) + 1));

    -- Contabiliza feature_use
    IF NEW.event_type = 'feature_use' THEN
        v_feat_id := NEW.properties->>'feature_id';
        IF v_feat_id IS NOT NULL THEN
            SELECT COALESCE(feature_usage_map, '{}') INTO v_feat FROM mia_user_patterns WHERE user_id = NEW.user_id;
            v_feat_count := COALESCE((v_feat ->> v_feat_id)::int4, 0) + 1;
            v_feat := jsonb_set(v_feat, ARRAY[v_feat_id], to_jsonb(v_feat_count));
            UPDATE mia_user_patterns
                SET feature_usage_map = v_feat,
                    peak_hours = v_peak,
                    behavioral_updated_at = now()
                WHERE user_id = NEW.user_id;
            RETURN NEW;
        END IF;
    END IF;

    -- page_exit: atualiza avg_dwell_ms por página e nav_graph
    IF NEW.event_type = 'page_exit' THEN
        v_dwell_ms := (NEW.properties->>'dwell_ms')::int8;
        v_from := v_page;
        v_to := NEW.properties->>'next_page';

        -- Atualiza avg_dwell_ms no perfil
        IF v_dwell_ms IS NOT NULL AND v_dwell_ms > 0 THEN
            DECLARE
                v_dwell_map jsonb;
                v_old_avg int8;
                v_old_count int4;
                v_new_avg int8;
            BEGIN
                SELECT COALESCE(avg_dwell_ms, '{}') INTO v_dwell_map FROM mia_user_patterns WHERE user_id = NEW.user_id;
                v_old_avg := COALESCE((v_dwell_map -> v_page ->> 'avg')::int8, 0);
                v_old_count := COALESCE((v_dwell_map -> v_page ->> 'count')::int4, 0);
                v_new_avg := ((v_old_avg * v_old_count) + v_dwell_ms) / (v_old_count + 1);
                v_dwell_map := jsonb_set(
                    v_dwell_map,
                    ARRAY[v_page],
                    jsonb_build_object('avg', v_new_avg, 'count', v_old_count + 1)
                );
                UPDATE mia_user_patterns
                    SET avg_dwell_ms = v_dwell_map, peak_hours = v_peak, behavioral_updated_at = now()
                    WHERE user_id = NEW.user_id;
            END;
        END IF;

        -- Atualiza nav_graph (from → to)
        IF v_from IS NOT NULL AND v_to IS NOT NULL AND v_from != v_to THEN
            INSERT INTO user_nav_graph(user_id, from_page, to_page, weight, last_seen_at)
                VALUES(NEW.user_id, v_from, v_to, 1, now())
                ON CONFLICT (user_id, from_page, to_page)
                DO UPDATE SET weight = user_nav_graph.weight + 1, last_seen_at = now();
        END IF;

        RETURN NEW;
    END IF;

    -- mia_suggestion_acted: atualiza taxa de aceitação
    IF NEW.event_type = 'mia_suggestion_acted' THEN
        UPDATE mia_user_patterns
            SET mia_suggestion_act_rate = (
                -- média móvel exponencial simples (α=0.2)
                COALESCE(mia_suggestion_act_rate, 0) * 0.8 +
                CASE WHEN (NEW.properties->>'acted')::bool THEN 0.2 ELSE 0 END
            ),
            peak_hours = v_peak,
            behavioral_updated_at = now()
            WHERE user_id = NEW.user_id;
        RETURN NEW;
    END IF;

    -- Atualiza top_pages
    IF NEW.event_type = 'page_enter' THEN
        SELECT COALESCE(top_pages, '[]') INTO v_pages FROM mia_user_patterns WHERE user_id = NEW.user_id;

        -- Procura página existente no array e incrementa count
        SELECT
            (SELECT jsonb_agg(
                CASE WHEN elem->>'page' = v_page
                    THEN jsonb_set(elem, '{count}', to_jsonb((elem->>'count')::int4 + 1))
                    ELSE elem END
            ) FROM jsonb_array_elements(v_pages) elem),
            EXISTS(SELECT 1 FROM jsonb_array_elements(v_pages) elem WHERE elem->>'page' = v_page)
        INTO v_pages, v_page_found;

        IF NOT v_page_found THEN
            v_pages := v_pages || jsonb_build_object('page', v_page, 'count', 1);
        END IF;

        -- Mantém top-20 por count
        SELECT jsonb_agg(elem ORDER BY (elem->>'count')::int4 DESC)
            FROM (SELECT elem FROM jsonb_array_elements(v_pages) elem LIMIT 20) sub
            INTO v_pages;

        UPDATE mia_user_patterns
            SET top_pages = COALESCE(v_pages, '[]'),
                peak_hours = v_peak,
                behavioral_updated_at = now()
            WHERE user_id = NEW.user_id;
        RETURN NEW;
    END IF;

    -- Fallback: só atualiza peak_hours
    UPDATE mia_user_patterns
        SET peak_hours = v_peak, behavioral_updated_at = now()
        WHERE user_id = NEW.user_id;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_gidape_events_update_profile ON gidape_events;
CREATE TRIGGER trg_gidape_events_update_profile
    AFTER INSERT ON gidape_events
    FOR EACH ROW EXECUTE FUNCTION fn_update_behavioral_profile();

-- ============================================================
-- 9. View: behavioral profile rico para MIA consumir
-- ============================================================
CREATE OR REPLACE VIEW vw_user_behavioral_profile AS
SELECT
    p.user_id,
    p.total_queries,
    p.preferred_format,
    p.verbosity_pref,
    p.expertise_level,
    p.top_tools,
    p.top_intents,
    p.top_modules,
    p.top_pages,
    p.top_flows,
    p.peak_hours,
    p.avg_dwell_ms,
    p.feature_usage_map,
    p.loop_count,
    p.last_loop_detected_at,
    p.mia_suggestion_act_rate,
    p.counterfactual_avg_dwell_ms,
    p.behavioral_updated_at,
    -- Top 5 transições de navegação mais frequentes
    (
        SELECT jsonb_agg(jsonb_build_object('from', from_page, 'to', to_page, 'weight', weight) ORDER BY weight DESC)
        FROM (SELECT from_page, to_page, weight FROM user_nav_graph WHERE user_id = p.user_id ORDER BY weight DESC LIMIT 5) t
    ) AS top_nav_transitions,
    -- Loop mais recente não resolvido
    (
        SELECT jsonb_build_object('pages', loop_pages, 'occurrences', occurrences, 'last_seen', last_seen_at)
        FROM user_loops WHERE user_id = p.user_id AND resolved = false ORDER BY last_seen_at DESC LIMIT 1
    ) AS active_loop
FROM mia_user_patterns p;

COMMENT ON VIEW vw_user_behavioral_profile IS 'Perfil comportamental completo por usuário — injetado no prompt MIA a cada turn';

-- ============================================================
-- 10. RPC para MIA buscar perfil comportamental
-- ============================================================
CREATE OR REPLACE FUNCTION get_behavioral_profile(p_user_id uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER AS $$
    SELECT row_to_json(v)::jsonb FROM vw_user_behavioral_profile v WHERE user_id = p_user_id;
$$;

-- ============================================================
-- 11. Distilled patterns ativos por scope
-- ============================================================
CREATE OR REPLACE FUNCTION get_distilled_patterns(p_scope text DEFAULT 'global')
RETURNS TABLE (title text, content text, category text, confidence float4) LANGUAGE sql STABLE SECURITY DEFINER AS $$
    SELECT title, content, category, confidence
    FROM mia_distilled_patterns
    WHERE active = true
        AND (scope = p_scope OR scope = 'global')
        AND (expires_at IS NULL OR expires_at > now())
    ORDER BY confidence DESC, distilled_at DESC
    LIMIT 20;
$$;

