// Hook global de rastreamento comportamental para MIA.
// Captura: page_enter/exit (com dwell_ms, scroll_pct, next_page),
// feature_use, search_query, mia_opened, mia_suggestion_acted.
//
// Usado no DashboardLayout — não instanciar em páginas individuais.

import { useEffect, useRef, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { useStore } from '@/shared/contexts/StoreContext';
import { enqueueEvent, type GidapeEvent } from './analyticsQueue';

const SESSION_KEY = 'momma_behavior_session';

function getSessionId(): string {
  let sid = sessionStorage.getItem(SESSION_KEY);
  if (!sid) {
    sid = crypto.randomUUID();
    sessionStorage.setItem(SESSION_KEY, sid);
  }
  return sid;
}

function getDeviceType(): string {
  const w = window.innerWidth;
  if (w < 768) return 'mobile';
  if (w < 1024) return 'tablet';
  return 'desktop';
}

function getScrollPct(): number {
  const el = document.documentElement;
  const scrollable = el.scrollHeight - el.clientHeight;
  if (scrollable <= 0) return 100;
  return Math.round((window.scrollY / scrollable) * 100);
}

export function useMiaBehaviorTracker() {
  const { user } = useAuth();
  const location = useLocation();
  const { currentStore } = useStore() as any;

  const pageEnterRef = useRef<number>(performance.now());
  const prevPageRef = useRef<string>('');
  const sessionId = getSessionId();

  const makeBase = useCallback((): Omit<GidapeEvent, 'event_type' | 'properties'> => ({
    user_id: user?.id ?? '',
    session_id: sessionId,
    page: location.pathname,
    loja_id: currentStore?.id ?? null,
    role: (user as any)?.role ?? null,
    device_type: getDeviceType(),
  }), [user, sessionId, location.pathname, currentStore]);

  // page_exit para página anterior + page_enter para nova
  useEffect(() => {
    if (!user?.id) return;

    const now = performance.now();
    const prevPage = prevPageRef.current;
    const currentPage = location.pathname;

    if (prevPage && prevPage !== currentPage) {
      const dwell_ms = Math.round(now - pageEnterRef.current);
      enqueueEvent({
        ...makeBase(),
        page: prevPage,
        event_type: 'page_exit',
        properties: {
          dwell_ms,
          scroll_pct: getScrollPct(),
          next_page: currentPage,
        },
      });
    }

    enqueueEvent({
      ...makeBase(),
      event_type: 'page_enter',
      properties: { referrer: prevPage || null },
    });

    pageEnterRef.current = now;
    prevPageRef.current = currentPage;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.pathname, user?.id]);

  /** Rastreia uso de feature específica */
  const trackFeature = useCallback((featureId: string, action: string, extra?: Record<string, unknown>) => {
    if (!user?.id) return;
    enqueueEvent({
      ...makeBase(),
      event_type: 'feature_use',
      properties: { feature_id: featureId, action, ...extra },
    });
  }, [makeBase, user?.id]);

  /** Rastreia query de busca */
  const trackSearch = useCallback((term: string, resultCount: number, clickedResult?: string) => {
    if (!user?.id) return;
    enqueueEvent({
      ...makeBase(),
      event_type: 'search_query',
      properties: { term: term.slice(0, 200), result_count: resultCount, clicked_result: clickedResult ?? null },
    });
  }, [makeBase, user?.id]);

  /** Rastreia abertura do chat MIA */
  const trackMiaOpened = useCallback((trigger: 'fab' | 'shortcut' | 'proactive' = 'fab') => {
    if (!user?.id) return;
    enqueueEvent({
      ...makeBase(),
      event_type: 'mia_opened',
      properties: { trigger },
    });
  }, [makeBase, user?.id]);

  /** Rastreia se sugestão da MIA foi aceita ou ignorada */
  const trackMiaSuggestion = useCallback((suggestionId: string, acted: boolean) => {
    if (!user?.id) return;
    enqueueEvent({
      ...makeBase(),
      event_type: 'mia_suggestion_acted',
      properties: { suggestion_id: suggestionId, acted },
    });
  }, [makeBase, user?.id]);

  return { trackFeature, trackSearch, trackMiaOpened, trackMiaSuggestion };
}

