export function formatUserContextForPrompt(bundle: UserContextBundle): string {
    const hasData = bundle.workflows.length > 0 || bundle.memories.length > 0 ||
        bundle.behavioral !== null || bundle.distilledPatterns.length > 0
    if (!hasData) return ''

    const lines: string[] = ['## L4 — Contexto personalizado deste usuário']

    // Distilled patterns (Padrão 1 — aprendizado acumulado do uso real)
    if (bundle.distilledPatterns.length > 0) {
        lines.push('', '### Padrões aprendidos do uso real da Momma')
        for (const p of bundle.distilledPatterns) {
            lines.push(`**[${p.category}] ${p.title}**`)
            lines.push(p.content)
        }
    }

    // Perfil comportamental (L3 — como este usuário usa o sistema)
    if (bundle.behavioral) {
        const b = bundle.behavioral
        lines.push('', '### Comportamento observado (analytics)')

        if (b.top_pages?.length > 0) {
            const pages = b.top_pages.slice(0, 5).map(p => `${p.page}(${p.count}×)`).join(', ')
            lines.push(`- Páginas mais acessadas: ${pages}`)
        }

        if (b.top_nav_transitions?.length > 0) {
            const flows = b.top_nav_transitions.slice(0, 3).map(t => `${t.from}→${t.to}`).join('; ')
            lines.push(`- Fluxos mais comuns: ${flows}`)
        }

        const peakHour = b.peak_hours
            ? Object.entries(b.peak_hours).sort(([, a], [, b]) => Number(b) - Number(a))[0]
            : null
        if (peakHour) {
            lines.push(`- Horário de pico: ${peakHour[0]}h`)
        }

        if (b.mia_suggestion_act_rate > 0) {
            lines.push(`- Taxa de ação em sugestões MIA: ${Math.round(b.mia_suggestion_act_rate * 100)}%`)
        }

        if (b.active_loop) {
            const loopPages = b.active_loop.pages.join('→')
            lines.push(`- ⚠️ Loop de fricção detectado: ${loopPages} (${b.active_loop.occurrences}×) — considere oferecer atalho`)
        }

        if (b.counterfactual_avg_dwell_ms && b.avg_dwell_ms) {
            lines.push(`- Baseline sem MIA: ${Math.round(b.counterfactual_avg_dwell_ms / 1000)}s médios por página`)
        }
    }

    if (bundle.workflows.length > 0) {
        lines.push('', '### Workflows salvos (atalhos pessoais)')
        for (const w of bundle.workflows) {
            const triggerStr = w.triggers.length > 0 ? ` — gatilhos: ${w.triggers.join(', ')}` : ''
            const pageStr = w.page_path ? ` (página: ${w.page_path})` : ''
            lines.push(`- **${w.name}** (${w.steps_count} passos, usado ${w.use_count}×)${triggerStr}${pageStr}`)
        }
        lines.push('', 'Se intent do user casa com gatilho de algum workflow acima, OFEREÇA executar esse workflow em vez de planejar do zero.')
    }

    if (bundle.memories.length > 0) {
        lines.push('', '### Memórias e preferências')
        for (const m of bundle.memories) {
            const confStr = m.confidence !== null ? ` (conf=${Math.round(m.confidence * 100)}%)` : ''
            lines.push(`- [${m.type}] ${m.fact}${confStr}`)
        }
        lines.push('', 'Use essas preferências como defaults. Se intent não as contradiz, aplique sem perguntar.')
    }

    return lines.join('\n')
}

