// MIA 2.0 — User Context Loader (L4 — User Mirror)
//
// Injeta workflows + memories DESTE user no prompt. Roda antes do LLM call
// pra que MIA "saiba" os atalhos e preferências do user atual.
//
// Padrão: top-N por relevância (use_count + recência).
//
// Doc: docs/mia/ARCHITECTURE.md (Section 6 — Memory Hierarchy, L4)

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const SUPABASE_URL = Deno.env.get('SUPABASE_URL')
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')

const supabase = (SUPABASE_URL && SUPABASE_SERVICE_ROLE_KEY)
    ? createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)
    : null

const MAX_WORKFLOWS = 5
const MAX_MEMORIES = 10

export interface BehavioralProfile {
    top_pages: Array<{ page: string; count: number }>
    top_nav_transitions: Array<{ from: string; to: string; weight: number }>
    peak_hours: Record<string, number>
    feature_usage_map: Record<string, number>
    avg_dwell_ms: Record<string, { avg: number; count: number }>
    mia_suggestion_act_rate: number
    loop_count: number
    active_loop: { pages: string[]; occurrences: number } | null
    counterfactual_avg_dwell_ms: number | null
}

export interface UserContextBundle {
    workflows: Array<{
        name: string
        triggers: string[]
        steps_count: number
        page_path: string | null
        use_count: number
    }>
    memories: Array<{
        type: string
        fact: string
        description: string | null
        confidence: number | null
        source: string | null
    }>
    behavioral: BehavioralProfile | null
    distilledPatterns: Array<{ title: string; content: string; category: string }>
}

/**
 * Carrega top-N workflows + top-N memories do user, ordenados por
 * RELEVÂNCIA ao userQuery (Crítico #3: semantic retrieval via tsvector
 * portuguese). Quando query vazio/curto, fallback ordering use_count.
 *
 * Best-effort — retorna empty bundle se Supabase não configurado.
 *
 * @param userId UUID do user
 * @param userQuery Mensagem do user pra ranking — usa tsvector portuguese
 *                  (plainto_tsquery + ts_rank). Boost por use_count/confidence.
 */
export async function loadUserContext(
    userId: string | null | undefined,
    userQuery?: string,
): Promise<UserContextBundle> {
    if (!supabase || !userId) {
        return { workflows: [], memories: [] }
    }

    const empty: UserContextBundle = { workflows: [], memories: [], behavioral: null, distilledPatterns: [] }
    const query = (userQuery ?? '').trim()

    try {
        const [wfResult, memResult, behavioralResult, distilledResult] = await Promise.all([
            // RPC com relevance ranking (tsvector portuguese + boost use_count)
            supabase.rpc('mia_workflows_by_relevance', {
                p_user_id: userId,
                p_query: query,
                p_limit: MAX_WORKFLOWS,
            }),
            supabase.rpc('mia_memories_by_relevance', {
                p_user_id: userId,
                p_query: query,
                p_limit: MAX_MEMORIES,
            }),
            // Perfil comportamental completo (L3)
            supabase.rpc('get_behavioral_profile', { p_user_id: userId }),
            // Distilled patterns globais + por role (Padrão 1)
            supabase.from('mia_distilled_patterns')
                .select('title, content, category, confidence')
                .eq('active', true)
                .or('scope.eq.global,scope.eq.role:all')
                .order('confidence', { ascending: false })
                .limit(10),
        ])

        const workflows = (wfResult.data ?? []).map((w: any) => ({
            name: String(w.name ?? ''),
            triggers: Array.isArray(w.trigger_phrases) ? w.trigger_phrases : [],
            steps_count: Array.isArray(w.steps) ? w.steps.length : 0,
            page_path: w.page_path ?? null,
            use_count: Number(w.use_count ?? 0),
            // relevance retornado pela RPC; útil pra debug, não enviado pro prompt
        }))

        const memories = (memResult.data ?? []).map((m: any) => ({
            type: String(m.type ?? 'fact'),
            fact: String(m.fact ?? ''),
            description: m.description ?? null,
            confidence: typeof m.confidence === 'number' ? m.confidence : null,
            source: m.extracted_by ?? null,
        }))

        const behavioral = behavioralResult.data ? (behavioralResult.data as BehavioralProfile) : null
        const distilledPatterns = ((distilledResult.data ?? []) as Array<{ title: string; content: string; category: string }>)

        return { workflows, memories, behavioral, distilledPatterns }
    } catch (err) {
        console.warn('[MIA UserContext] load failed:', err)
        return empty
    }
}

/**
 * Formata bundle em seção markdown pro prompt. Vazio se ambos arrays empty.
 */
export function formatUserContextForPrompt(bundle: UserContextBundle): string {
    if (bundle.workflows.length === 0 && bundle.memories.length === 0) {
        return ''
    }

    const lines: string[] = ['## L4 — Suas preferências e atalhos (deste user)']

    if (bundle.workflows.length > 0) {
        lines.push('', '### Workflows que VOCÊ já salvou (atalhos pessoais)')
        for (const w of bundle.workflows) {
            const triggerStr = w.triggers.length > 0 ? ` — gatilhos: ${w.triggers.join(', ')}` : ''
            const pageStr = w.page_path ? ` (página: ${w.page_path})` : ''
            lines.push(`- **${w.name}** (${w.steps_count} passos, usado ${w.use_count}×)${triggerStr}${pageStr}`)
        }
        lines.push('', 'Se intent do user casa com gatilho de algum workflow acima, OFEREÇA executar esse workflow em vez de planejar do zero. Não execute direto — pergunte: "Você quer usar o atalho \'X\'?"')
    }

    if (bundle.memories.length > 0) {
        lines.push('', '### Preferências/fatos sobre este user')
        for (const m of bundle.memories) {
            const confStr = m.confidence !== null ? ` (conf=${Math.round(m.confidence * 100)}%)` : ''
            const sourceStr = m.source ? ` [${m.source}]` : ''
            lines.push(`- [${m.type}] ${m.fact}${confStr}${sourceStr}`)
        }
        lines.push('', 'Use essas preferências como defaults. Se intent não as contradiz, aplique sem perguntar.')
    }

    return lines.join('\n')
}

input.content:
// mia-morning-digest — cron 07:30 diário
// Gera digest personalizado por usuário ativo com base em:
//   1. Padrão comportamental (top_pages, horário de pico)
//   2. Dados do dia anterior (vendas, estoque, produção, alertas)
//   3. Notificações abertas
// Grava em mia_proactive_queue + notificacoes_master

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const supabase = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
)

const OPENROUTER_API_KEY = Deno.env.get('OPENROUTER_API_KEY')

interface ActiveUser {
    user_id: string
    role: string
    loja_id: number | null
    full_name: string | null
    top_pages: Array<{ page: string; count: number }>
    peak_hours: Record<string, number>
    expertise_level: string | null
    verbosity_pref: string | null
}

async function fetchActiveUsers(): Promise<ActiveUser[]> {
    // Usuários que usaram o sistema nos últimos 7 dias
    const since = new Date(Date.now() - 7 * 86_400_000).toISOString()
    const { data } = await supabase
        .from('gidape_events')
        .select('user_id')
        .gte('created_at', since)
        .limit(500)

    if (!data?.length) return []

    const uniqueIds = [...new Set(data.map(r => r.user_id))]

    const { data: profiles } = await supabase
        .from('profiles')
        .select('id, role, loja_id, full_name')
        .in('id', uniqueIds)

    const { data: patterns } = await supabase
        .from('mia_user_patterns')
        .select('user_id, top_pages, peak_hours, expertise_level, verbosity_pref')
        .in('user_id', uniqueIds)

    const patternMap = new Map(patterns?.map(p => [p.user_id, p]) ?? [])

    return (profiles ?? []).map(p => ({
        user_id: p.id,
        role: p.role ?? 'operador',
        loja_id: p.loja_id,
        full_name: p.full_name,
        top_pages: patternMap.get(p.id)?.top_pages ?? [],
        peak_hours: patternMap.get(p.id)?.peak_hours ?? {},
        expertise_level: patternMap.get(p.id)?.expertise_level,
        verbosity_pref: patternMap.get(p.id)?.verbosity_pref,
    }))
}

async function fetchContextForUser(user: ActiveUser): Promise<string> {
    const yesterday = new Date(Date.now() - 86_400_000).toISOString().slice(0, 10)
    const lojaFilter = user.loja_id ? { loja_id: user.loja_id } : {}
    const ctxParts: string[] = []

    // Produção ontem
    const { data: prod } = await supabase
        .from('daily_production')
        .select('date, total_boxes, notes')
        .eq('date', yesterday)
        .limit(1)
    if (prod?.length) ctxParts.push(`Produção ontem: ${prod[0].total_boxes} caixas`)

    // Alertas de estoque (abaixo do mínimo)
    const { data: estoque } = await (supabase as any)
        .from('estoque')
        .select('produto_id, quantidade, quantidade_minima, produtos_master(nome)')
        .filter('quantidade', 'lt', supabase.rpc('col_min', {}))
        .limit(5)
        .maybeSingle()
    if (estoque) ctxParts.push(`Alertas de estoque: ${JSON.stringify(estoque)}`)

    // Notificações master abertas
    const { data: notifs } = await (supabase as any)
        .from('notificacoes_master')
        .select('type, message, created_at')
        .is('read_at', null)
        .order('created_at', { ascending: false })
        .limit(3)
    if (notifs?.length) ctxParts.push(`Notificações pendentes: ${notifs.map((n: any) => n.message).join('; ')}`)

    return ctxParts.join('\n') || 'Nenhum dado crítico ontem.'
}

async function generateDigest(user: ActiveUser, context: string): Promise<string> {
    if (!OPENROUTER_API_KEY) return `Bom dia${user.full_name ? `, ${user.full_name.split(' ')[0]}` : ''}. Aqui está seu resumo: ${context}`

    const verbosity = user.verbosity_pref === 'conciso' ? 'Seja muito conciso (2-3 linhas).' : 'Seja direto mas completo (4-6 linhas).'
    const prompt = `Você é MIA, assistente do ERP Momma (doces saudáveis em Brasília).
Role do usuário: ${user.role}${user.loja_id ? ` — Loja ${user.loja_id}` : ' — Matriz'}.
${verbosity}

Com base nos dados abaixo, gere um digest matinal personalizado em pt-BR.
Comece com saudação pelo nome se disponível. Destaque o mais importante primeiro.
Termine oferecendo ajuda específica relacionada ao contexto.

Dados:
${context}

Páginas que esse usuário mais usa: ${user.top_pages.slice(0, 3).map(p => p.page).join(', ')}
`
    try {
        const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${OPENROUTER_API_KEY}`,
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                model: 'x-ai/grok-4.1-fast',
                messages: [{ role: 'user', content: prompt }],
                max_tokens: 250,
                temperature: 0.5,
            }),
        })
        const json = await res.json()
        return json.choices?.[0]?.message?.content ?? context
    } catch {
        return context
    }
}

async function deliverDigest(userId: string, digest: string, context: string): Promise<void> {
    const now = new Date().toISOString()
    const expires = new Date(Date.now() + 12 * 3_600_000).toISOString()

    await Promise.allSettled([
        // 1. Fila proativa MIA (aparece na próxima abertura do chat)
        supabase.from('mia_proactive_queue').insert({
            user_id: userId,
            type: 'morning_digest',
            title: 'Bom dia — seu resumo',
            body: digest,
            context: { raw: context, generated_at: now },
            priority: 3,
            expires_at: expires,
        }),
        // 2. notificacoes_master (bell icon na UI)
        (supabase as any).from('notificacoes_master').insert({
            user_id: userId,
            type: 'morning_digest',
            message: digest.slice(0, 300),
            created_at: now,
        }),
    ])
}

Deno.serve(async () => {
    try {
        const users = await fetchActiveUsers()
        console.log(`[morning-digest] processando ${users.length} usuários`)

        const results = await Promise.allSettled(
            users.map(async (user) => {
                const context = await fetchContextForUser(user)
                const digest = await generateDigest(user, context)
                await deliverDigest(user.user_id, digest, context)
                return { user_id: user.user_id, ok: true }
            })
        )

        const ok = results.filter(r => r.status === 'fulfilled').length
        const fail = results.filter(r => r.status === 'rejected').length
        console.log(`[morning-digest] done: ${ok} ok, ${fail} fail`)

        return new Response(JSON.stringify({ ok, fail, total: users.length }), {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
        })
    } catch (err) {
        console.error('[morning-digest] fatal:', err)
        return new Response(JSON.stringify({ error: String(err) }), { status: 500 })
    }
})

