        console.log(`[morning-digest] processando ${users.length} usuários`)

        const results = await Promise.allSettled(
            users.map(async (user) => {
                const context = await fetchContextForUser(user)
                const digest = await generateDigest(user, context)
                await deliverDigest(user.user_id, digest, context)
                return { user_id: user.user_id, ok: true }
            })
        )

        const ok = results.filter(r => r.status === 'fulfilled').length
        const fail = results.filter(r => r.status === 'rejected').length
        console.log(`[morning-digest] done: ${ok} ok, ${fail} fail`)

        return new Response(JSON.stringify({ ok, fail, total: users.length }), {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
        })
    } catch (err) {
        console.error('[morning-digest] fatal:', err)
        return new Response(JSON.stringify({ error: String(err) }), { status: 500 })
    }
})

