                body: `Notei que você frequentemente vai de ${loop[0]} para ${loop[1]} e volta. Posso criar um atalho para isso?`,
                context: { loop_pages: loop },
                priority: 5,
                expires_at: new Date(Date.now() + 24 * 3_600_000).toISOString(),
            })

            // Atualiza contador no perfil
            await supabase.from('mia_user_patterns').upsert({
                user_id: userId,
                loop_count: loopSequences.length,
                last_loop_detected_at: new Date().toISOString(),
            }, { onConflict: 'user_id', ignoreDuplicates: false })
        }
    }

    // Calcula top_flows (sequências de 3 páginas mais comuns)
    const trigramMap = new Map<string, number>()
    for (let i = 0; i < transitions.length - 1; i++) {
        if (i + 1 < transitions.length && transitions[i].to === transitions[i + 1].from) {
            const trigram = `${transitions[i].from}→${transitions[i].to}→${transitions[i + 1].to}`
            trigramMap.set(trigram, (trigramMap.get(trigram) ?? 0) + 1)
        }
    }

    const topFlows = [...trigramMap.entries()]
        .sort(([, a], [, b]) => b - a)
        .slice(0, 5)
        .map(([flow, count]) => ({ flow: flow.split('→'), count }))

    if (topFlows.length > 0) {
        await supabase.from('mia_user_patterns').upsert({
            user_id: userId,
            top_flows: topFlows,
            behavioral_updated_at: new Date().toISOString(),
        }, { onConflict: 'user_id', ignoreDuplicates: false })
    }

    return { loops: loopSequences.length, flowsUpdated: topFlows.length > 0 }
}

// Atualiza counterfactual baseline por usuário
async function updateCounterfactualBaseline(): Promise<void> {
    const { data: sessions } = await supabase
        .from('mia_counterfactual_sessions')
        .select('user_id, mia_opened, avg_dwell_ms, duration_ms')
        .not('avg_dwell_ms', 'is', null)

    if (!sessions?.length) return

    const grouped = new Map<string, { noMia: number[]; withMia: number[] }>()
    for (const s of sessions) {
        if (!grouped.has(s.user_id)) grouped.set(s.user_id, { noMia: [], withMia: [] })
        const g = grouped.get(s.user_id)!
        if (s.mia_opened) g.withMia.push(s.avg_dwell_ms)
        else g.noMia.push(s.avg_dwell_ms)
    }

    await Promise.allSettled(
        [...grouped.entries()].map(([userId, data]) => {
            if (!data.noMia.length) return Promise.resolve()
            const avgNoMia = Math.round(data.noMia.reduce((a, b) => a + b, 0) / data.noMia.length)
            return supabase.from('mia_user_patterns').upsert({
                user_id: userId,
                counterfactual_avg_dwell_ms: avgNoMia,
                behavioral_updated_at: new Date().toISOString(),
            }, { onConflict: 'user_id', ignoreDuplicates: false })
        })
    )
}

Deno.serve(async () => {
    try {
        const since = new Date(Date.now() - ANALYSIS_WINDOW_HOURS * 3_600_000).toISOString()

        // Busca usuários ativos hoje
        const { data: activeUsers } = await supabase
            .from('gidape_events')
            .select('user_id')
            .gte('created_at', since)

        const uniqueIds = [...new Set((activeUsers ?? []).map(r => r.user_id))]
        console.log(`[pattern-analyzer] analisando ${uniqueIds.length} usuários`)

        const results = await Promise.allSettled(uniqueIds.map(uid => analyzeUser(uid)))
        const totalLoops = results
            .filter(r => r.status === 'fulfilled')
            .reduce((sum, r) => sum + ((r as any).value?.loops ?? 0), 0)

        // Atualiza baselines counterfactual
        await updateCounterfactualBaseline()

        console.log(`[pattern-analyzer] done: ${totalLoops} loops detectados`)

        return new Response(JSON.stringify({ users: uniqueIds.length, total_loops: totalLoops }), {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
        })
    } catch (err) {
        console.error('[pattern-analyzer] fatal:', err)
        return new Response(JSON.stringify({ error: String(err) }), { status: 500 })
    }
})

