// mia-distillation — cron domingo 02:00 (Padrão 1 SOTA)
//
// Analisa batch de conversas + ações + outcomes da última semana.
// Extrai padrões que o LLM aprendeu mas os skills ainda não sabem.
// Grava em mia_distilled_patterns — injetado no prompt em runtime.
//
// Isso é o Claude Code auto-memory, aplicado ao ERP:
// a MIA aprende com o uso real e atualiza sua própria inteligência.

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const supabase = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
)

const OPENROUTER_API_KEY = Deno.env.get('OPENROUTER_API_KEY')
const ANALYSIS_WINDOW_DAYS = 7

interface ConversationSample {
    user_role: string
    messages: Array<{ role: string; content: string }>
    tools_used: string[]
    satisfaction: number | null  // -1 | 0 | 1 | null
    session_pages: string[]
}

async function fetchConversationSamples(): Promise<ConversationSample[]> {
    const since = new Date(Date.now() - ANALYSIS_WINDOW_DAYS * 86_400_000).toISOString()

    // Busca sessões MIA da última semana
    const { data: sessions } = await supabase
        .from('mia_sessions')
        .select('id, user_id, channel, message_count, domain_hint')
        .gte('last_activity_at', since)
        .gt('message_count', 2)  // só sessões com conversa real
        .limit(100)

    if (!sessions?.length) return []

    const samples: ConversationSample[] = []

    for (const session of sessions.slice(0, 30)) {  // top 30 sessões
        const [messagesResult, profileResult, feedbackResult] = await Promise.all([
            supabase.from('chat_messages')
                .select('role, content')
                .eq('session_id', session.id)
                .order('created_at', { ascending: true })
                .limit(20),
            supabase.from('profiles')
                .select('role')
                .eq('id', session.user_id)
                .maybeSingle(),
            supabase.from('mia_feedback_signals')
                .select('polarity')
                .eq('session_id', session.id),
        ])

        const messages = (messagesResult.data ?? [])
            .filter(m => m.role !== 'system' && m.content?.length > 5)
            .map(m => ({ role: m.role, content: String(m.content).slice(0, 500) }))

        if (messages.length < 2) continue

        const satisfaction = (() => {
            const signals = feedbackResult.data ?? []
            if (!signals.length) return null
            const sum = signals.reduce((s: number, r: any) => s + r.polarity, 0)
            return sum > 0 ? 1 : sum < 0 ? -1 : 0
        })()

        // Páginas visitadas durante a sessão
        const { data: pageEvents } = await supabase
            .from('gidape_events')
            .select('page')
            .eq('session_id', session.id)
            .eq('event_type', 'page_enter')
            .limit(10)

        samples.push({
            user_role: profileResult.data?.role ?? 'unknown',
            messages,
            tools_used: [],  // extraído da conversa pelo LLM
            satisfaction,
            session_pages: [...new Set((pageEvents ?? []).map(e => e.page))],
        })
    }

    return samples
}

async function distillPatterns(samples: ConversationSample[]): Promise<Array<{
    scope: string
    category: string
    title: string
    content: string
    confidence: number
    evidence: Record<string, unknown>
}>> {
    if (!OPENROUTER_API_KEY || !samples.length) return []

    const sampleText = samples.slice(0, 20).map((s, i) => `
--- Conversa ${i + 1} (role: ${s.user_role}, satisfação: ${s.satisfaction ?? 'desconhecida'}) ---
${s.messages.map(m => `${m.role.toUpperCase()}: ${m.content}`).join('\n')}
Páginas visitadas: ${s.session_pages.join(', ')}
`).join('\n')

    const prompt = `Você é um especialista em análise de uso de ERP.
Analise as conversas abaixo com a assistente MIA do ERP Momma (doces saudáveis, Brasília).

Extraia padrões que devem ser incorporados ao conhecimento da MIA.

Tipos de padrão:
- skill_update: algo que MIA erra ou poderia fazer melhor com base nos pedidos
- workflow_pattern: fluxo de trabalho recorrente que MIA deveria conhecer
- language_pattern: termos, jargões, abreviações da Momma que MIA deve entender
- friction_insight: pontos onde usuários repetem perguntas ou mostram frustração

REGRAS:
- Extraia APENAS padrões que aparecem em múltiplas conversas (evidência real)
- NÃO invente padrões — cada um deve ter evidência direta no texto
- Seja específico: "usuários de /estoque frequentemente pedem relatório semanal" > "usuários querem relatórios"
- Confidence: 0.7 = 2-3 exemplos, 0.85 = 4-5 exemplos, 0.95 = 6+ exemplos

Responda APENAS com JSON válido:
[{
  "scope": "global" | "role:gerente" | "role:master" | "role:admin",
  "category": "skill_update" | "workflow_pattern" | "language_pattern" | "friction_insight",
  "title": "Título conciso do padrão",
  "content": "Instrução para a MIA incorporar. Máx 200 chars.",
  "confidence": 0.7,
  "evidence_summary": "Breve evidência das conversas"
}]

CONVERSAS:
${sampleText}`

    try {
        const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${OPENROUTER_API_KEY}`,
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                model: 'x-ai/grok-4.1-fast',
                messages: [{ role: 'user', content: prompt }],
                max_tokens: 2000,
                temperature: 0.1,
            }),
        })
        const json = await res.json()
        const text = json.choices?.[0]?.message?.content ?? ''
        const match = text.match(/\[[\s\S]*\]/)
        if (!match) return []

        const raw = JSON.parse(match[0])
        return Array.isArray(raw) ? raw.filter((p: any) =>
            p?.scope && p?.category && p?.title && p?.content &&
            typeof p.confidence === 'number' && p.confidence >= 0.65
        ).map((p: any) => ({
            scope: String(p.scope),
            category: String(p.category),
            title: String(p.title).slice(0, 200),
            content: String(p.content).slice(0, 500),
            confidence: Math.min(1, Math.max(0.65, Number(p.confidence))),
            evidence: { summary: p.evidence_summary ?? '', sample_count: samples.length },
        })) : []
    } catch (e) {
        console.warn('[distillation] LLM call failed:', e)
        return []
    }
}

async function savePatterns(patterns: Array<{
    scope: string; category: string; title: string;
    content: string; confidence: number; evidence: Record<string, unknown>
}>): Promise<number> {
    if (!patterns.length) return 0

    const expires = new Date(Date.now() + 30 * 86_400_000).toISOString()  // 30 dias

    // Desativa padrões antigos da mesma categoria/scope
    for (const p of patterns) {
        await supabase.from('mia_distilled_patterns')
            .update({ active: false })
            .eq('scope', p.scope)
            .eq('category', p.category)
    }

    const { data, error } = await supabase.from('mia_distilled_patterns').insert(
        patterns.map(p => ({
            scope: p.scope,
            category: p.category,
            title: p.title,
            content: p.content,
            confidence: p.confidence,
            evidence: p.evidence,
            active: true,
            expires_at: expires,
            distilled_at: new Date().toISOString(),
            created_by: 'mia-distillation',
        }))
    ).select('id')

    if (error) {
        console.error('[distillation] save failed:', error)
        return 0
    }

    return data?.length ?? 0
}

Deno.serve(async () => {
    try {
        console.log('[distillation] iniciando análise semanal...')

        const samples = await fetchConversationSamples()
        console.log(`[distillation] ${samples.length} conversas coletadas`)

        if (samples.length < 3) {
            return new Response(JSON.stringify({ skipped: true, reason: 'insufficient_data', samples: samples.length }), {
                status: 200,
                headers: { 'Content-Type': 'application/json' },
            })
        }

        const patterns = await distillPatterns(samples)
        console.log(`[distillation] ${patterns.length} padrões extraídos`)

        const saved = await savePatterns(patterns)
        console.log(`[distillation] ${saved} padrões gravados em mia_distilled_patterns`)

        return new Response(JSON.stringify({
            samples: samples.length,
            patterns_extracted: patterns.length,
            patterns_saved: saved,
            categories: patterns.map(p => `${p.scope}/${p.category}`),
        }), {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
        })
    } catch (err) {
        console.error('[distillation] fatal:', err)
        return new Response(JSON.stringify({ error: String(err) }), { status: 500 })
    }
})

