}

export function useMiaBehaviorTracker() {
  const { user } = useAuth();
  const location = useLocation();
  const { currentStore } = useStore() as any;

  const pageEnterRef = useRef<number>(performance.now());
  const prevPageRef = useRef<string>('');
  const sessionId = getSessionId();

  const makeBase = useCallback((): Omit<GidapeEvent, 'event_type' | 'properties'> => ({
    user_id: user?.id ?? '',
    session_id: sessionId,
    page: location.pathname,
    loja_id: currentStore?.id ?? null,
    role: (user as any)?.role ?? null,
    device_type: getDeviceType(),
  }), [user, sessionId, location.pathname, currentStore]);

  // page_exit para página anterior + page_enter para nova
  useEffect(() => {
    if (!user?.id) return;

    const now = performance.now();
    const prevPage = prevPageRef.current;
    const currentPage = location.pathname;

    if (prevPage && prevPage !== currentPage) {
      const dwell_ms = Math.round(now - pageEnterRef.current);
      enqueueEvent({
        ...makeBase(),
        page: prevPage,
        event_type: 'page_exit',
        properties: {
          dwell_ms,
          scroll_pct: getScrollPct(),
          next_page: currentPage,
        },
      });
    }

    enqueueEvent({
      ...makeBase(),
      event_type: 'page_enter',
      properties: { referrer: prevPage || null },
    });

    pageEnterRef.current = now;
    prevPageRef.current = currentPage;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.pathname, user?.id]);

  /** Rastreia uso de feature específica */
  const trackFeature = useCallback((featureId: string, action: string, extra?: Record<string, unknown>) => {
    if (!user?.id) return;
    enqueueEvent({
      ...makeBase(),
      event_type: 'feature_use',
      properties: { feature_id: featureId, action, ...extra },
    });
  }, [makeBase, user?.id]);

