  const trackSearch = useCallback((term: string, resultCount: number, clickedResult?: string) => {
    if (!user?.id) return;
    enqueueEvent({
      ...makeBase(),
      event_type: 'search_query',
      properties: { term: term.slice(0, 200), result_count: resultCount, clicked_result: clickedResult ?? null },
    });
  }, [makeBase, user?.id]);

  /** Rastreia abertura do chat MIA */
  const trackMiaOpened = useCallback((trigger: 'fab' | 'shortcut' | 'proactive' = 'fab') => {
    if (!user?.id) return;
    enqueueEvent({
      ...makeBase(),
      event_type: 'mia_opened',
      properties: { trigger },
    });
