// Fire-and-forget batched event queue — nunca bloqueia UX.
// Acumula eventos e faz flush em lote via Supabase REST.
// Usa sendBeacon no beforeunload para confiabilidade mobile.

import { supabase } from '@/integrations/supabase/client';

export interface GidapeEvent {
  user_id: string;
  session_id: string;
  event_type:
    | 'page_enter'
    | 'page_exit'
    | 'feature_use'
    | 'search_query'
    | 'mia_opened'
    | 'mia_suggestion_acted'
    | 'click'
    | 'form_submit'
    | 'error_seen';
  page: string;
  properties?: Record<string, unknown>;
  loja_id?: number | null;
  role?: string | null;
  device_type?: string;
}

const FLUSH_INTERVAL_MS = 8_000;
const MAX_BATCH = 50;

let _queue: GidapeEvent[] = [];
let _flushTimer: ReturnType<typeof setTimeout> | null = null;
let _initialized = false;

function getDeviceType(): string {
  const w = window.innerWidth;
  if (w < 768) return 'mobile';
  if (w < 1024) return 'tablet';
  return 'desktop';
}

async function _flush(): Promise<void> {
  if (_queue.length === 0) return;
  const batch = _queue.splice(0, MAX_BATCH);
  try {
    await (supabase as any).from('gidape_events').insert(
      batch.map((e) => ({ ...e, device_type: e.device_type ?? getDeviceType() }))
    );
  } catch {
    // Fire-and-forget — never throw, never break UX
  }
}

function _scheduleFlush(): void {
  if (_flushTimer) return;
  _flushTimer = setTimeout(() => {
    _flushTimer = null;
    _flush();
  }, FLUSH_INTERVAL_MS);
}

function _initBeforeUnload(): void {
  if (_initialized) return;
  _initialized = true;

  window.addEventListener('beforeunload', () => {
    if (_queue.length === 0) return;
    const batch = _queue.splice(0);
    const url = `${import.meta.env.VITE_SUPABASE_URL}/rest/v1/gidape_events`;
    const payload = JSON.stringify(batch.map((e) => ({ ...e, device_type: e.device_type ?? getDeviceType() })));
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      apikey: import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}`,
      Prefer: 'return=minimal',
    };
    try {
      fetch(url, { method: 'POST', headers, body: payload, keepalive: true }).catch(() => {});
    } catch {
      navigator.sendBeacon?.(url, new Blob([payload], { type: 'application/json' }));
    }
  });
}

export function enqueueEvent(event: GidapeEvent): void {
  _initBeforeUnload();
  _queue.push(event);
  if (_queue.length >= MAX_BATCH) {
    if (_flushTimer) {
      clearTimeout(_flushTimer);
      _flushTimer = null;
    }
    _flush();
  } else {
    _scheduleFlush();
  }
}

/** Flush imediato — chamar quando necessário (ex: logout) */
export function flushAnalytics(): Promise<void> {
  if (_flushTimer) {
    clearTimeout(_flushTimer);
    _flushTimer = null;
  }
  return _flush();
}

