// Consumer da fila proativa da MIA (mia_proactive_queue).
//
// Os crons (mia-morning-digest, mia-anomaly-watcher, mia-pattern-analyzer)
// gravam mensagens proativas nessa fila. Quando o usuário abre a MIA,
// buscamos os itens não-entregues, surgimos com eles como saudação
// contextual, e marcamos como entregues para não repetir.

import { supabase } from '@/integrations/supabase/client';

export interface ProactiveItem {
  id: string;
  type: 'morning_digest' | 'anomaly' | 'pattern_insight' | 'loop_friction';
  title: string;
  body: string;
  priority: number;
  context: Record<string, unknown>;
}

/** Busca itens proativos não-entregues e não-expirados, por prioridade. */
export async function fetchPendingProactive(userId: string): Promise<ProactiveItem[]> {
  if (!userId) return [];
  try {
    const { data, error } = await (supabase as any)
      .from('mia_proactive_queue')
      .select('id, type, title, body, priority, context')
      .eq('user_id', userId)
      .eq('delivered', false)
      .gt('expires_at', new Date().toISOString())
      .order('priority', { ascending: true })
      .order('created_at', { ascending: false })
      .limit(5);
    if (error) return [];
    return (data ?? []) as ProactiveItem[];
  } catch {
    return [];
  }
}

/** Marca itens como entregues — fire-and-forget. */
export async function markProactiveDelivered(ids: string[]): Promise<void> {
  if (!ids.length) return;
  try {
    await (supabase as any)
      .from('mia_proactive_queue')
      .update({ delivered: true, delivered_at: new Date().toISOString() })
      .in('id', ids);
  } catch {
    // never break UX
  }
}

/** Formata os itens proativos num único bloco markdown de saudação. */
export function formatProactiveGreeting(items: ProactiveItem[]): string {
  if (!items.length) return '';
  const icon: Record<ProactiveItem['type'], string> = {
    morning_digest: '☀️',
    anomaly: '⚠️',
    pattern_insight: '💡',
    loop_friction: '💡',
  };
  const parts = items.map((it) => {
    const i = icon[it.type] ?? '📌';
    // morning_digest já vem com saudação pronta do LLM — não duplica título
    if (it.type === 'morning_digest') return it.body;
    return `${i} **${it.title}**\n${it.body}`;
  });
  return parts.join('\n\n');
}

