      id: `proactive-${generateId()}`,
      role: 'assistant',
      content: greeting,
      isProactive: true,
      timestamp: new Date(),
    };
    // Prepend como primeira mensagem da visão atual (não persiste no DB).
    setMessages((prev) => {
      if (prev.some((m) => m.isProactive)) return prev;
      return [proactiveMsg, ...prev];
    });
    markProactiveDelivered(items.map((i) => i.id));
  })();
}, [isOpen, user?.id]);

