          id: dbc.id,
          title: dbc.title,
          createdAt: dbc.createdAt,
          updatedAt: dbc.updatedAt,
          messageCount: Math.max(dbc.messageCount, byId.get(dbc.id)?.messageCount ?? 0),
        });
      }
      return [...byId.values()].sort(
        (a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
      );
    });

    // Se a activeConversationId local não existe no DB, é uma conv local
    // sem persistência. Em fresh device é o caso comum. Switcha pra latest.
    if (opts?.switchToLatestIfMissing) {
      const activeIsInDb = dbConvs.some(c => c.id === activeConversationId);
      const localHasMessages = messages.length > 0;
      if (!activeIsInDb && !localHasMessages) {
        const latest = dbConvs[0];
        setActiveConversationId(latest.id);
        setActiveConvId(latest.id);
        const dbMsgs = await loadConversationMessagesFromDB(latest.id, user.id, 200);
        setMessages(dbMsgs);
        return;
      }
    }
  }

  if (activeConversationId) {
    const dbMsgs = await loadConversationMessagesFromDB(activeConversationId, user.id, 200);
    if (dbMsgs.length > 0) {
      // DB vence se tem mais histórico (outro device escreveu) ou se o
      // último timestamp do DB é mais novo que o local.
      setMessages(current => {
        if (dbMsgs.length > current.length) return dbMsgs;
        const lastDb = dbMsgs[dbMsgs.length - 1]?.timestamp?.getTime() ?? 0;
        const lastLocal = current[current.length - 1]?.timestamp?.getTime() ?? 0;
        if (lastDb > lastLocal) return dbMsgs;
        return current;
      });
    }
  }
} catch (e) {
  console.warn('[mia] sync from DB failed', e);

