import { useState, useRef, useCallback, useEffect } from 'react';
import { Sparkles, X } from 'lucide-react';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { cn } from '@/shared/lib/utils';
import { useLocation, useNavigate } from 'react-router-dom';

const FAB_HIDDEN_KEY = 'mia_fab_hidden';
const FAB_POS_KEY = 'mia_fab_pos';

function getHidden(): boolean {
  try { return localStorage.getItem(FAB_HIDDEN_KEY) === '1'; } catch { return false; }
}
function getSavedPos(): { x: number; y: number } | null {
  try {
    const raw = localStorage.getItem(FAB_POS_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}

/**
 * MiaFab — botão flutuante draggable com dismiss.
 *
 * Comportamento:
 * - Clique → NAVEGA pra /mia (página dedicada). Antes abria chat inline.
 * - Drag (touch/mouse) → reposiciona livremente, posição persiste em localStorage.
 * - Long press (500ms desktop) ou hover → revela botão X de dismiss.
 * - Dismiss → esconde permanentemente até `showMiaFab()` ser chamado.
 *
 * Decisão de UX: usuários estavam usando o chat inline sem necessidade. A MIA
 * tem página dedicada (/mia) com UX completa — o FAB vira atalho de navegação,
 * mantendo drag e dismiss pra usuários poderem reposicionar/esconder.
 */
export function MiaFab() {
  const { canViewMia } = usePermissions();
  const location = useLocation();
  const navigate = useNavigate();

  const [hidden, setHidden] = useState(getHidden);
  const [showClose, setShowClose] = useState(false);

  // Drag state
  const [pos, setPos] = useState<{ x: number; y: number } | null>(null);
  const dragRef = useRef<{ startX: number; startY: number; startPosX: number; startPosY: number; moved: boolean } | null>(null);
  const fabRef = useRef<HTMLDivElement>(null);
  const closeTimeout = useRef<ReturnType<typeof setTimeout>>();

  // Reaparece quando showMiaFab() é chamado em outro lugar
  useEffect(() => {
    const onShow = () => setHidden(false);
    window.addEventListener('mia-fab-show', onShow);
    return () => window.removeEventListener('mia-fab-show', onShow);
  }, []);

  // Inicializa posição salva (clamped pro viewport atual)
  useEffect(() => {
    const saved = getSavedPos();
    if (saved) {
      const x = Math.min(Math.max(0, saved.x), window.innerWidth - 48);
      const y = Math.min(Math.max(0, saved.y), window.innerHeight - 48);
      setPos({ x, y });
    }
  }, []);

  const clampPos = useCallback((x: number, y: number) => {
    const size = 48;
    return {
      x: Math.min(Math.max(0, x), window.innerWidth - size),
      y: Math.min(Math.max(0, y), window.innerHeight - size),
    };
  }, []);

  const savePos = useCallback((x: number, y: number) => {
    try { localStorage.setItem(FAB_POS_KEY, JSON.stringify({ x, y })); } catch { /* noop */ }
  }, []);

  // Touch handlers (drag em mobile/tablet)
  const onTouchStart = useCallback((e: React.TouchEvent) => {
    const touch = e.touches[0];
    const rect = fabRef.current?.getBoundingClientRect();
    if (!rect) return;
    dragRef.current = {
      startX: touch.clientX,
      startY: touch.clientY,
      startPosX: rect.left,
      startPosY: rect.top,
      moved: false,
    };
  }, []);

  const onTouchMove = useCallback((e: React.TouchEvent) => {
    if (!dragRef.current) return;
    const touch = e.touches[0];
    const dx = touch.clientX - dragRef.current.startX;
    const dy = touch.clientY - dragRef.current.startY;
    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) {
      dragRef.current.moved = true;
    }
    if (dragRef.current.moved) {
      e.preventDefault();
      const newPos = clampPos(
        dragRef.current.startPosX + dx,
        dragRef.current.startPosY + dy,
      );
      setPos(newPos);
    }
  }, [clampPos]);

  const onTouchEnd = useCallback(() => {
    if (dragRef.current?.moved && pos) {
      savePos(pos.x, pos.y);
    }
    if (!dragRef.current?.moved) {
      // Tap sem drag → navega pra /mia
      navigate('/mia');
    }
    dragRef.current = null;
  }, [pos, savePos, navigate]);

  // Desktop: long press revela X (dismiss); click navega
  const onMouseDown = useCallback(() => {
    closeTimeout.current = setTimeout(() => setShowClose(true), 500);
  }, []);
  const onMouseUp = useCallback(() => {
    if (closeTimeout.current) clearTimeout(closeTimeout.current);
  }, []);

  const handleDismiss = useCallback((e: React.MouseEvent | React.TouchEvent) => {
    e.stopPropagation();
    e.preventDefault();
    setHidden(true);
    try { localStorage.setItem(FAB_HIDDEN_KEY, '1'); } catch { /* noop */ }
  }, []);

  const handleClick = useCallback(() => {
    // Se long-press revelou o X, primeiro click só fecha o X
    if (showClose) {
      setShowClose(false);
      return;
    }
    navigate('/mia');
  }, [showClose, navigate]);

  if (!canViewMia() || location.pathname === '/mia' || hidden) return null;

  const style: React.CSSProperties = pos
    ? { position: 'fixed', left: pos.x, top: pos.y, right: 'auto', bottom: 'auto' }
    : {};

  return (
    <div
      ref={fabRef}
      className={cn(
        "z-40 group",
        !pos && "fixed bottom-6 right-6"
      )}
      style={style}
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      {/* Botão de dismiss (X) — revelado via long-press ou hover */}
      <button
        type="button"
        onClick={handleDismiss}
        onTouchEnd={(e) => { e.stopPropagation(); handleDismiss(e); }}
        className={cn(
          "absolute -top-1.5 -right-1.5 z-50 h-5 w-5 rounded-full",
          "bg-zinc-700/90 text-white flex items-center justify-center",
          "shadow-md transition-all duration-200",
          "sm:opacity-0 sm:scale-75 sm:group-hover:opacity-100 sm:group-hover:scale-100",
          showClose && "!opacity-100 !scale-100"
        )}
        aria-label="Esconder atalho da MIA"
      >
        <X className="h-3 w-3" />
      </button>

      {/* FAB principal */}
      <button
        type="button"
        onClick={handleClick}
        onMouseDown={onMouseDown}
        onMouseUp={onMouseUp}
        onMouseLeave={onMouseUp}
        className={cn(
          "h-12 w-12 rounded-full shadow-lg flex items-center justify-center",
          "bg-gradient-to-br from-emerald-500 to-teal-600 hover:from-emerald-600 hover:to-teal-700",
          "transition-all duration-200 hover:scale-105 hover:shadow-xl",
          "touch-none select-none"
        )}
        aria-label="Abrir Mia (página dedicada)"
        title="Abrir MIA"
      >
        <Sparkles className="h-5 w-5 text-white" />
      </button>
    </div>
  );
}

/** Re-show o FAB após dismiss (chamável em settings) */
export function showMiaFab() {
  try { localStorage.removeItem(FAB_HIDDEN_KEY); } catch { /* noop */ }
  window.dispatchEvent(new Event('mia-fab-show'));
}

