-- Fix: branch page_enter do trigger não acumulava top_pages.
-- Bug: jsonb_agg sobre array vazio retorna NULL, e `NULL || obj = NULL`,
-- então top_pages permanecia vazio para sempre. Separamos found/not-found
-- e usamos COALESCE em todos os pontos onde jsonb_agg pode retornar NULL.

CREATE OR REPLACE FUNCTION fn_update_behavioral_profile()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_hour int4;
    v_peak jsonb;
    v_feat jsonb;
    v_feat_id text;
    v_feat_count int4;
    v_pages jsonb;
    v_page_found bool := false;
    v_dwell_ms int8;
    v_page text;
    v_from text;
    v_to text;
BEGIN
    v_hour := EXTRACT(HOUR FROM NEW.created_at)::int4;
    v_page := NEW.page;

    INSERT INTO mia_user_patterns(user_id)
        VALUES(NEW.user_id)
        ON CONFLICT (user_id) DO NOTHING;

    SELECT COALESCE(peak_hours, '{}') INTO v_peak FROM mia_user_patterns WHERE user_id = NEW.user_id;
    v_peak := jsonb_set(v_peak, ARRAY[v_hour::text], to_jsonb(COALESCE((v_peak ->> v_hour::text)::int4, 0) + 1));

    -- feature_use
    IF NEW.event_type = 'feature_use' THEN
        v_feat_id := NEW.properties->>'feature_id';
        IF v_feat_id IS NOT NULL THEN
            SELECT COALESCE(feature_usage_map, '{}') INTO v_feat FROM mia_user_patterns WHERE user_id = NEW.user_id;
            v_feat_count := COALESCE((v_feat ->> v_feat_id)::int4, 0) + 1;
            v_feat := jsonb_set(v_feat, ARRAY[v_feat_id], to_jsonb(v_feat_count));
            UPDATE mia_user_patterns
                SET feature_usage_map = v_feat, peak_hours = v_peak, behavioral_updated_at = now()
                WHERE user_id = NEW.user_id;
            RETURN NEW;
        END IF;
    END IF;

    -- page_exit: avg_dwell_ms + nav_graph
    IF NEW.event_type = 'page_exit' THEN
        v_dwell_ms := (NEW.properties->>'dwell_ms')::int8;
        v_from := v_page;
        v_to := NEW.properties->>'next_page';

        IF v_dwell_ms IS NOT NULL AND v_dwell_ms > 0 THEN
            DECLARE
                v_dwell_map jsonb;
                v_old_avg int8;
                v_old_count int4;
                v_new_avg int8;
            BEGIN
                SELECT COALESCE(avg_dwell_ms, '{}') INTO v_dwell_map FROM mia_user_patterns WHERE user_id = NEW.user_id;
                v_old_avg := COALESCE((v_dwell_map -> v_page ->> 'avg')::int8, 0);
                v_old_count := COALESCE((v_dwell_map -> v_page ->> 'count')::int4, 0);
                v_new_avg := ((v_old_avg * v_old_count) + v_dwell_ms) / (v_old_count + 1);
                v_dwell_map := jsonb_set(v_dwell_map, ARRAY[v_page],
                    jsonb_build_object('avg', v_new_avg, 'count', v_old_count + 1));
                UPDATE mia_user_patterns
                    SET avg_dwell_ms = v_dwell_map, peak_hours = v_peak, behavioral_updated_at = now()
                    WHERE user_id = NEW.user_id;
            END;
        END IF;

        IF v_from IS NOT NULL AND v_to IS NOT NULL AND v_from != v_to THEN
            INSERT INTO user_nav_graph(user_id, from_page, to_page, weight, last_seen_at)
                VALUES(NEW.user_id, v_from, v_to, 1, now())
                ON CONFLICT (user_id, from_page, to_page)
                DO UPDATE SET weight = user_nav_graph.weight + 1, last_seen_at = now();
        END IF;

        RETURN NEW;
    END IF;

    -- mia_suggestion_acted
    IF NEW.event_type = 'mia_suggestion_acted' THEN
        UPDATE mia_user_patterns
            SET mia_suggestion_act_rate = (
                COALESCE(mia_suggestion_act_rate, 0) * 0.8 +
                CASE WHEN (NEW.properties->>'acted')::bool THEN 0.2 ELSE 0 END
            ),
            peak_hours = v_peak, behavioral_updated_at = now()
            WHERE user_id = NEW.user_id;
        RETURN NEW;
    END IF;

    -- page_enter: top_pages (FIX — separa found/not-found, COALESCE em todo agg)
    IF NEW.event_type = 'page_enter' THEN
        SELECT COALESCE(top_pages, '[]'::jsonb) INTO v_pages FROM mia_user_patterns WHERE user_id = NEW.user_id;

        v_page_found := EXISTS(
            SELECT 1 FROM jsonb_array_elements(v_pages) elem WHERE elem->>'page' = v_page
        );

        IF v_page_found THEN
            -- incrementa count da página existente
            v_pages := COALESCE((
                SELECT jsonb_agg(
                    CASE WHEN elem->>'page' = v_page
                        THEN jsonb_set(elem, '{count}', to_jsonb((elem->>'count')::int4 + 1))
                        ELSE elem END
                ) FROM jsonb_array_elements(v_pages) elem
            ), '[]'::jsonb);
        ELSE
            -- nova página — append seguro (v_pages nunca é NULL aqui)
            v_pages := v_pages || jsonb_build_object('page', v_page, 'count', 1);
        END IF;

        -- mantém top-20 por count (ORDER BY antes do LIMIT)
        v_pages := COALESCE((
            SELECT jsonb_agg(elem ORDER BY (elem->>'count')::int4 DESC)
            FROM (
                SELECT elem FROM jsonb_array_elements(v_pages) elem
                ORDER BY (elem->>'count')::int4 DESC LIMIT 20
            ) sub
        ), v_pages);

        UPDATE mia_user_patterns
            SET top_pages = COALESCE(v_pages, '[]'::jsonb), peak_hours = v_peak, behavioral_updated_at = now()
            WHERE user_id = NEW.user_id;
        RETURN NEW;
    END IF;

    -- fallback: só peak_hours
    UPDATE mia_user_patterns
        SET peak_hours = v_peak, behavioral_updated_at = now()
        WHERE user_id = NEW.user_id;

    RETURN NEW;
END;
$$;

