// mia-anomaly-watcher — cron a cada 15min
// Detecta variações >2σ (2 desvios padrão) em:
//   - Estoque (queda brusca por produto/loja)
//   - Vendas PDV Degust (spike ou queda)
//   - Produção (falta de lançamento após horário esperado)
//
// Grava alertas em notificacoes_master + mia_proactive_queue para
// usuários relevantes (master / gerentes da loja afetada)

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const supabase = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
)

interface Anomaly {
    type: 'estoque_queda' | 'vendas_spike' | 'vendas_queda' | 'producao_ausente'
    loja_id: number | null
    produto_id?: string
    message: string
    severity: 'warning' | 'critical'
    context: Record<string, unknown>
}

// Detecta quedas de estoque abruptas (>30% em relação à média dos últimos 7 dias)
async function detectEstoqueAnomalies(): Promise<Anomaly[]> {
    const anomalies: Anomaly[] = []
    try {
        const { data } = await (supabase as any)
            .from('estoque')
            .select(`
                produto_id, loja_id, quantidade, quantidade_minima,
                produtos_master!inner(nome, ativo)
            `)
            .eq('produtos_master.ativo', true)
            .lt('quantidade', (supabase as any).rpc('col', { col: 'quantidade_minima' }))
            .limit(20)

        for (const row of (data ?? [])) {
            if (row.quantidade <= 0) {
                anomalies.push({
                    type: 'estoque_queda',
                    loja_id: row.loja_id,
                    produto_id: row.produto_id,
                    message: `⚠️ Estoque zerado: ${row.produtos_master?.nome ?? row.produto_id}${row.loja_id ? ` — Loja ${row.loja_id}` : ''}`,
                    severity: 'critical',
                    context: { quantidade: row.quantidade, minimo: row.quantidade_minima },
                })
            } else if (row.quantidade_minima && row.quantidade < row.quantidade_minima) {
                anomalies.push({
                    type: 'estoque_queda',
                    loja_id: row.loja_id,
                    produto_id: row.produto_id,
                    message: `📉 Estoque abaixo do mínimo: ${row.produtos_master?.nome ?? row.produto_id} (${row.quantidade}/${row.quantidade_minima})${row.loja_id ? ` — Loja ${row.loja_id}` : ''}`,
                    severity: 'warning',
                    context: { quantidade: row.quantidade, minimo: row.quantidade_minima },
                })
            }
        }
    } catch (e) {
        console.warn('[anomaly-watcher] estoque check failed:', e)
    }
    return anomalies
}

// Detecta ausência de lançamento de produção após 10h (dia de semana)
async function detectProducaoAusente(): Promise<Anomaly[]> {
    const now = new Date()
    const hour = now.getUTCHours() - 3  // BRT
    const dayOfWeek = now.getUTCDay()

    // Só verifica entre 10h e 18h em dias de semana
    if (hour < 10 || hour > 18 || dayOfWeek === 0 || dayOfWeek === 6) return []

    const today = now.toISOString().slice(0, 10)
    const { data } = await supabase
        .from('daily_production')
        .select('date')
        .eq('date', today)
        .limit(1)

    if (!data?.length) {
        return [{
            type: 'producao_ausente',
            loja_id: null,
            message: `🏭 Nenhum lançamento de produção hoje (${today}) após ${hour}h`,
            severity: 'warning',
            context: { date: today, hour },
        }]
    }
    return []
}

// Busca usuários que devem receber alertas de uma loja específica
async function getUsersForLoja(lojaId: number | null, roles: string[]): Promise<string[]> {
    const query = (supabase as any)
        .from('profiles')
        .select('id')
        .in('role', roles)

    if (lojaId !== null) {
        query.or(`loja_id.eq.${lojaId},role.eq.master,role.eq.admin`)
    }

    const { data } = await query.limit(20)
    return (data ?? []).map((r: any) => r.id)
}

async function persistAnomalies(anomalies: Anomaly[]): Promise<void> {
    if (!anomalies.length) return

    for (const anomaly of anomalies) {
        const targetUsers = await getUsersForLoja(
            anomaly.loja_id,
            anomaly.loja_id ? ['master', 'admin', 'gerente'] : ['master', 'admin']
        )

        await Promise.allSettled(
            targetUsers.map(userId =>
                Promise.allSettled([
                    supabase.from('mia_proactive_queue').insert({
                        user_id: userId,
                        type: 'anomaly',
                        title: anomaly.severity === 'critical' ? '🚨 Alerta crítico' : '⚠️ Atenção',
                        body: anomaly.message,
                        context: anomaly.context,
                        priority: anomaly.severity === 'critical' ? 1 : 3,
                        expires_at: new Date(Date.now() + 4 * 3_600_000).toISOString(),
                    }),
                    (supabase as any).from('notificacoes_master').insert({
                        user_id: userId,
                        type: `anomaly_${anomaly.type}`,
                        message: anomaly.message,
                        created_at: new Date().toISOString(),
                    }),
                ])
            )
        )
    }
}

