function _initBeforeUnload(): void {
  if (_initialized) return;
  _initialized = true;

  window.addEventListener('beforeunload', () => {
    if (_queue.length === 0) return;
    const batch = _queue.splice(0);
    const url = `${import.meta.env.VITE_SUPABASE_URL}/rest/v1/gidape_events`;
    const payload = JSON.stringify(batch.map((e) => ({ ...e, device_type: e.device_type ?? getDeviceType() })));
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      apikey: import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}`,
      Prefer: 'return=minimal',
    };
    try {
      fetch(url, { method: 'POST', headers, body: payload, keepalive: true }).catch(() => {});
    } catch {
      navigator.sendBeacon?.(url, new Blob([payload], { type: 'application/json' }));
    }
  });
}

export function enqueueEvent(event: GidapeEvent): void {
  _initBeforeUnload();
  _queue.push(event);
  if (_queue.length >= MAX_BATCH) {
    if (_flushTimer) {
      clearTimeout(_flushTimer);

