// Cache do access token do user — necessário no beforeunload flush, onde a RLS
// de gidape_events exige auth.uid()=user_id. A anon key não satisfaz isso.
let _accessToken: string | null = null;
let _tokenSubscribed = false;

function _subscribeToken(): void {
  if (_tokenSubscribed) return;
  _tokenSubscribed = true;
  (supabase as any).auth.getSession().then(({ data }: any) => {
    _accessToken = data?.session?.access_token ?? null;
  }).catch(() => {});
  (supabase as any).auth.onAuthStateChange((_event: string, session: any) => {
    _accessToken = session?.access_token ?? null;
  });
}

