// Badge + toast de proatividade da MIA.
//
// - Conta itens não-entregues em mia_proactive_queue (badge no item MIA da sidebar).
// - Realtime: quando um item de alta prioridade chega, salta um toast na hora,
//   mesmo sem o usuário abrir a MIA. É o que torna a MIA realmente proativa
//   (push, não pull).
// - Reseta o badge quando a MIA consome a fila (evento 'mia-proactive-consumed').

import { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

const HIGH_PRIORITY = 2; // priority <= 2 → toast imediato

export function useMiaProactiveBadge(): number {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [count, setCount] = useState(0);

  const refetch = useCallback(async () => {
    if (!user?.id) {
      setCount(0);
      return;
    }
    try {
      const { count: c } = await (supabase as any)
        .from('mia_proactive_queue')
        .select('id', { count: 'exact', head: true })
        .eq('user_id', user.id)
        .eq('delivered', false)
        .gt('expires_at', new Date().toISOString());
      setCount(c ?? 0);
    } catch {
      setCount(0);
    }
  }, [user?.id]);

  // Fetch inicial + reset quando a MIA consome a fila
  useEffect(() => {
    refetch();
    const onConsumed = () => setCount(0);
    window.addEventListener('mia-proactive-consumed', onConsumed);
    return () => window.removeEventListener('mia-proactive-consumed', onConsumed);
  }, [refetch]);

  // Realtime: novo item → incrementa badge + toast se alta prioridade
  useEffect(() => {
    if (!user?.id) return;
    const channel = supabase
      .channel(`mia-proactive-${user.id}`)
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'mia_proactive_queue', filter: `user_id=eq.${user.id}` },
        (payload: any) => {
          const item = payload.new;
          if (!item || item.delivered) return;
          setCount((c) => c + 1);
          if ((item.priority ?? 5) <= HIGH_PRIORITY) {
            toast(item.title || 'MIA', {
              description: String(item.body || '').slice(0, 160),
              action: { label: 'Ver', onClick: () => navigate('/mia') },
              duration: 10000,
            });
          }
        },
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [user?.id, navigate]);

  return count;
}

