input.content:
// Kill-switch da proatividade da MIA (lê mia_runtime_config.proactive_enabled).
//
// Default OFF: enquanto a flag não carrega ou está false, NADA proativo aparece
// (badge, toast, greeting). A captura/aprendizado seguem normalmente.
// Ligar em ~2026-06-16 via: update mia_runtime_config set value='true' where key='proactive_enabled'.

import { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';

let _enabled = false;
let _loaded = false;
let _inflight: Promise<boolean> | null = null;

async function _fetchFlag(): Promise<boolean> {
  try {
    const { data } = await (supabase as any)
      .from('mia_runtime_config')
      .select('value')
      .eq('key', 'proactive_enabled')
      .maybeSingle();
    // value é jsonb boolean (true/false)
    _enabled = data?.value === true || data?.value === 'true';
  } catch {
    _enabled = false;
  }
  _loaded = true;
  return _enabled;
}

/** Garante que a flag foi carregada (cache compartilhado, 1 fetch). */
export function ensureProactiveConfig(): Promise<boolean> {
  if (_loaded) return Promise.resolve(_enabled);
  if (!_inflight) _inflight = _fetchFlag();
  return _inflight;
}

/** Leitura síncrona do cache (false até carregar). */
export function isProactiveEnabledSync(): boolean {
  return _enabled;
}

