// mia-anomaly-watcher — cron a cada 15min
// Detecta:
//   - Estoque zerado ou abaixo do mínimo (por produto/loja)
//   - Ausência de lançamento de produção em dia útil após 10h BRT
// Entrega SÓ em mia_proactive_queue, para usuários ativos com role
// master/admin/gerente (resolvido via mia_get_user_role).

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const supabase = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
)

interface Anomaly {
    type: 'estoque_zerado' | 'estoque_baixo' | 'producao_ausente'
    loja_id: number | null
    message: string
    severity: 'warning' | 'critical'
    context: Record<string, unknown>
}

async function detectEstoque(): Promise<Anomaly[]> {
    const anomalies: Anomaly[] = []
    try {
        const { data } = await supabase
            .from('estoque')
            .select('quantidade_atual, quantidade_minima, loja_id, produto_master_id, produtos_master:produto_master_id(nome, ativo)')
            .not('quantidade_minima', 'is', null)
            .limit(2000)

        for (const row of (data ?? []) as any[]) {
            if (!row.produtos_master?.ativo) continue
            const qtd = Number(row.quantidade_atual)
            const min = Number(row.quantidade_minima)
            const nome = row.produtos_master?.nome ?? row.produto_master_id
            const loja = row.loja_id ? ` — Loja ${row.loja_id}` : ''
            if (qtd <= 0) {
                anomalies.push({
                    type: 'estoque_zerado', loja_id: row.loja_id, severity: 'critical',
                    message: `🚨 Estoque zerado: ${nome}${loja}`,
                    context: { quantidade: qtd, minimo: min },
                })
            } else if (min > 0 && qtd < min) {
                anomalies.push({
                    type: 'estoque_baixo', loja_id: row.loja_id, severity: 'warning',
                    message: `📉 Estoque abaixo do mínimo: ${nome} (${qtd}/${min})${loja}`,
                    context: { quantidade: qtd, minimo: min },
                })
            }
        }
    } catch (e) {
        console.warn('[anomaly-watcher] estoque check failed:', e)
    }
    // Limita ruído: no máximo 10 anomalias de estoque por ciclo
    return anomalies.slice(0, 10)
}

async function detectProducaoAusente(): Promise<Anomaly[]> {
    const now = new Date()
    const hourBrt = ((now.getUTCHours() - 3) + 24) % 24
    const dow = now.getUTCDay()
    if (hourBrt < 10 || hourBrt > 18 || dow === 0 || dow === 6) return []

    const today = now.toISOString().slice(0, 10)
    const { data } = await supabase
        .from('daily_production')
        .select('id')
        .eq('date', today)
        .limit(1)

    if (!data?.length) {
        return [{
            type: 'producao_ausente', loja_id: null, severity: 'warning',
            message: `🏭 Nenhum lançamento de produção hoje (${today}) até ${hourBrt}h`,
            context: { date: today, hour: hourBrt },
        }]
    }
    return []
}

// Resolve usuários ativos (24h) com role de gestão para receber alertas
async function getTargetUsers(): Promise<Array<{ user_id: string; role: string; store_id: number | null }>> {
    const since = new Date(Date.now() - 86_400_000).toISOString()
    const { data: ev } = await supabase
        .from('gidape_events').select('user_id').gte('created_at', since).limit(2000)
    if (!ev?.length) return []
    const uniqueIds = [...new Set(ev.map(r => r.user_id))]

    const { data: profiles } = await supabase
        .from('profiles').select('user_id, default_store_id').in('user_id', uniqueIds)

    const targets = await Promise.all((profiles ?? []).map(async (p) => {
        let role = 'operador'
        try {
            const { data } = await supabase.rpc('mia_get_user_role', { p_user_id: p.user_id })
            role = (typeof data === 'string' ? data : (data?.[0]?.role ?? data?.role)) || 'operador'
        } catch { /* keep default */ }
        return { user_id: p.user_id, role: String(role).toLowerCase(), store_id: p.default_store_id }
    }))

    const gestao = ['master', 'admin', 'administrator', 'administrador', 'gerente', 'gerentes', 'operacoes', 'operações']
    return targets.filter(t => gestao.includes(t.role))
}

async function persist(anomalies: Anomaly[]): Promise<number> {
    if (!anomalies.length) return 0
    const targets = await getTargetUsers()
    if (!targets.length) return 0

    let delivered = 0
    for (const a of anomalies) {
        // Gerente só recebe alertas da própria loja; master/admin recebem tudo
        const recipients = targets.filter(t =>
            t.role.startsWith('master') || t.role.startsWith('admin') ||
            a.loja_id === null || t.store_id === a.loja_id
        )
        await Promise.allSettled(recipients.map(t =>
            supabase.from('mia_proactive_queue').insert({
                user_id: t.user_id,
                type: 'anomaly',
                title: a.severity === 'critical' ? '🚨 Alerta crítico' : '⚠️ Atenção',
                body: a.message,
                context: a.context,
                priority: a.severity === 'critical' ? 1 : 3,
                expires_at: new Date(Date.now() + 4 * 3_600_000).toISOString(),
            })
        ))
        delivered += recipients.length
    }
    return delivered
}

Deno.serve(async () => {
    try {
        const [est, prod] = await Promise.all([detectEstoque(), detectProducaoAusente()])
        const all = [...est, ...prod]
        const delivered = await persist(all)
        console.log(`[anomaly-watcher] ${all.length} anomalias, ${delivered} entregas`)
        return new Response(JSON.stringify({
            anomalies: all.length, delivered, details: all.map(a => a.message),
        }), { status: 200, headers: { 'Content-Type': 'application/json' } })
    } catch (err) {
        console.error('[anomaly-watcher] fatal:', err)
        return new Response(JSON.stringify({ error: String(err) }), { status: 500 })
    }
})

