// mia-pattern-analyzer — cron 23:00 diário
// Analisa comportamento do dia:
//   1. Detecta loops de fricção por usuário (A→B→A→B = travado)
//   2. Atualiza top_flows por usuário (sequências mais comuns)
//   3. Cross-user patterns por role (padrões organizacionais)
//   4. Atualiza counterfactual baseline (sessões sem MIA vs com MIA)
//   5. Grava insights em mia_proactive_queue para loops detectados

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const supabase = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
)

const LOOP_THRESHOLD = 3      // mínimo de repetições para considerar loop
const ANALYSIS_WINDOW_HOURS = 25  // janela de análise (um pouco mais que 24h)

interface NavEvent {
    user_id: string
    page: string
    next_page: string | null
    created_at: string
}

// Detecta sequências repetitivas: A→B→A→B com threshold
function detectLoops(transitions: Array<{ from: string; to: string }>): Array<string[]> {
    if (transitions.length < LOOP_THRESHOLD * 2) return []

    const loops: Array<string[]> = []
    const seen = new Map<string, number>()

    // Sliding window de pares
    for (let i = 0; i < transitions.length - 1; i++) {
        const pair = `${transitions[i].from}→${transitions[i].to}`
        const reversePair = `${transitions[i].to}→${transitions[i].from}`

        const count = seen.get(pair) || 0
        seen.set(pair, count + 1)

        // Verifica se par e seu reverso aparecem alternadamente
        if ((seen.get(pair) ?? 0) >= LOOP_THRESHOLD && (seen.get(reversePair) ?? 0) >= LOOP_THRESHOLD) {
            loops.push([transitions[i].from, transitions[i].to])
        }
    }

    return [...new Map(loops.map(l => [l.join('→'), l])).values()]
}

// Processa um usuário: detecta loops e atualiza top_flows
async function analyzeUser(userId: string): Promise<{ loops: number; flowsUpdated: boolean }> {
    const since = new Date(Date.now() - ANALYSIS_WINDOW_HOURS * 3_600_000).toISOString()

    // Busca transições de navegação do dia
    const { data: navData } = await supabase
        .from('gidape_events')
        .select('page, properties, created_at')
        .eq('user_id', userId)
        .eq('event_type', 'page_exit')
        .gte('created_at', since)
        .order('created_at', { ascending: true })
        .limit(200)

    if (!navData?.length) return { loops: 0, flowsUpdated: false }

    const transitions = navData
        .filter(e => e.properties?.next_page)
        .map(e => ({ from: e.page, to: e.properties.next_page as string }))

    if (!transitions.length) return { loops: 0, flowsUpdated: false }

    // Detecta loops
    const loopSequences = detectLoops(transitions)

    if (loopSequences.length > 0) {
        for (const loop of loopSequences) {
            await supabase.from('user_loops').upsert({
                user_id: userId,
                loop_pages: loop,
                occurrences: LOOP_THRESHOLD,
                last_seen_at: new Date().toISOString(),
            }, { onConflict: 'user_id,loop_pages', ignoreDuplicates: false })

            // Agenda notificação de loop para o usuário
            await supabase.from('mia_proactive_queue').insert({
                user_id: userId,
                type: 'loop_friction',
                title: '💡 Atalho detectado',
                body: `Notei que você frequentemente vai de ${loop[0]} para ${loop[1]} e volta. Posso criar um atalho para isso?`,
                context: { loop_pages: loop },
                priority: 5,
                expires_at: new Date(Date.now() + 24 * 3_600_000).toISOString(),
            })

            // Atualiza contador no perfil
            await supabase.from('mia_user_patterns').upsert({
                user_id: userId,
                loop_count: loopSequences.length,
                last_loop_detected_at: new Date().toISOString(),
            }, { onConflict: 'user_id', ignoreDuplicates: false })
        }
    }

    // Calcula top_flows (sequências de 3 páginas mais comuns)
    const trigramMap = new Map<string, number>()
    for (let i = 0; i < transitions.length - 1; i++) {
        if (i + 1 < transitions.length && transitions[i].to === transitions[i + 1].from) {
            const trigram = `${transitions[i].from}→${transitions[i].to}→${transitions[i + 1].to}`
            trigramMap.set(trigram, (trigramMap.get(trigram) ?? 0) + 1)
        }
    }

    const topFlows = [...trigramMap.entries()]
        .sort(([, a], [, b]) => b - a)
        .slice(0, 5)
