            user_id: userId,
            top_flows: topFlows,
            behavioral_updated_at: new Date().toISOString(),
        }, { onConflict: 'user_id', ignoreDuplicates: false })
    }

    return { loops: loopSequences.length, flowsUpdated: topFlows.length > 0 }
}

