        const uniqueIds = [...new Set((activeUsers ?? []).map(r => r.user_id))]
        console.log(`[pattern-analyzer] analisando ${uniqueIds.length} usuários`)

        const results = await Promise.allSettled(uniqueIds.map(uid => analyzeUser(uid)))
        const totalLoops = results
            .filter(r => r.status === 'fulfilled')
            .reduce((sum, r) => sum + ((r as any).value?.loops ?? 0), 0)

        // Atualiza baselines counterfactual
        await updateCounterfactualBaseline()

        console.log(`[pattern-analyzer] done: ${totalLoops} loops detectados`)

        return new Response(JSON.stringify({ users: uniqueIds.length, total_loops: totalLoops }), {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
        })
    } catch (err) {
        console.error('[pattern-analyzer] fatal:', err)
        return new Response(JSON.stringify({ error: String(err) }), { status: 500 })
    }
})

