  // Rastreia mudança de página
  useEffect(() => {
    const s = getOrInit();
    if (!s) return;
    const now = Date.now();
    const dwell = now - s.last_page_enter;
    if (dwell > 500 && dwell < 3_600_000) {
      s.dwell_samples.push(dwell);
    }
    s.pages.push(location.pathname);
    s.last_page_enter = now;
    saveSession(s);
    schedulePersist();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.pathname, user?.id]);

  // Click tracking global
  useEffect(() => {
    if (!user?.id) return;
    const handler = () => {
      const s = getOrInit();
      if (!s) return;
      s.clicks++;
      saveSession(s);
    };
    document.addEventListener('click', handler, { passive: true });
    return () => document.removeEventListener('click', handler);
  }, [user?.id, getOrInit]);

  // Flush no beforeunload
  useEffect(() => {
    if (!user?.id) return;
    const handler = () => {
      const s = sessionRef.current;
      if (!s) return;
      const dwell = Date.now() - s.last_page_enter;
      if (dwell > 500) s.dwell_samples.push(dwell);
      s.pages.push(location.pathname);
      persistSession(s, user!.id!, true);
    };
    window.addEventListener('beforeunload', handler);
    return () => window.removeEventListener('beforeunload', handler);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  /** Chamar quando MIA for aberta — marca sessão como assistida */
  const markMiaOpened = useCallback(() => {
    const s = getOrInit();
    if (!s) return;
    s.mia_opened = true;
    saveSession(s);
    schedulePersist();
  }, [getOrInit, schedulePersist]);

  return { markMiaOpened };
}

