  // Ref com a rota atual — evita stale closure no handler de saída (que tem
  // deps [user?.id] e não re-roda na navegação).
  const locationRef = useRef(location.pathname);

  // Rastreia mudança de página
  useEffect(() => {
    locationRef.current = location.pathname;
    const s = getOrInit();
    if (!s) return;
    const now = Date.now();
    const dwell = now - s.last_page_enter;
    if (dwell > 500 && dwell < 3_600_000) {
      s.dwell_samples.push(dwell);
    }
    // Evita double-count da última página (handler de saída também faz push)
    if (s.pages[s.pages.length - 1] !== location.pathname) {
      s.pages.push(location.pathname);
    }
    s.last_page_enter = now;
    saveSession(s);
    schedulePersist();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.pathname, user?.id]);

  // Click tracking global
  useEffect(() => {
    if (!user?.id) return;
    const handler = () => {
      const s = getOrInit();
      if (!s) return;
      s.clicks++;
      saveSession(s);
    };
    document.addEventListener('click', handler, { passive: true });
    return () => document.removeEventListener('click', handler);
  }, [user?.id, getOrInit]);

  // Flush na saída — beforeunload + visibilitychange (este último é o
  // confiável em mobile/PWA; beforeunload some quando o app vai pra background).
  useEffect(() => {
    if (!user?.id) return;
    const flushExit = () => {
      const s = sessionRef.current;
      if (!s) return;
      const dwell = Date.now() - s.last_page_enter;
      if (dwell > 500 && dwell < 3_600_000) s.dwell_samples.push(dwell);
      // usa locationRef (rota atual), não a do closure inicial
      if (s.pages[s.pages.length - 1] !== locationRef.current) {
        s.pages.push(locationRef.current);
      }
      persistSession(s, user!.id!, true);
    };
    const onVisibility = () => {
      if (document.visibilityState === 'hidden') flushExit();
    };
    window.addEventListener('beforeunload', flushExit);
    document.addEventListener('visibilitychange', onVisibility);
    return () => {
      window.removeEventListener('beforeunload', flushExit);
      document.removeEventListener('visibilitychange', onVisibility);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  /** Marca a sessão como assistida (MIA foi aberta). */
  const markMiaOpened = useCallback(() => {
    const s = getOrInit();
    if (!s || s.mia_opened) return;
    s.mia_opened = true;
    saveSession(s);
    schedulePersist();
  }, [getOrInit, schedulePersist]);

  // Auto-wire: quando a MIA abre (useMia dispara 'mia-opened'), marca a sessão.
  useEffect(() => {
    const onOpened = () => markMiaOpened();
    window.addEventListener('mia-opened', onOpened);
    return () => window.removeEventListener('mia-opened', onOpened);
  }, [markMiaOpened]);

  return { markMiaOpened };
}

