// Rastreamento de sessões sem MIA (Padrão 2 — Counterfactual).
// Registra o que usuários fazem quando NÃO usam o chat MIA.
// Permite medir impacto real da IA: compara sessões com vs sem assistência.
//
// Usado no DashboardLayout junto com useMiaBehaviorTracker.

import { useEffect, useRef, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/integrations/supabase/client';

const SESSION_KEY = 'momma_cf_session';
const FLUSH_DEBOUNCE_MS = 5_000;

interface CfSession {
  id: string;
  mia_opened: boolean;
  pages: string[];
  clicks: number;
  dwell_samples: number[];
  started_at: number;
  last_page_enter: number;
}

function loadSession(userId: string): CfSession {
  try {
    const raw = sessionStorage.getItem(SESSION_KEY);
    if (raw) return JSON.parse(raw);
  } catch {}
  const id = crypto.randomUUID();
  const session: CfSession = {
    id,
    mia_opened: false,
    pages: [],
    clicks: 0,
    dwell_samples: [],
    started_at: Date.now(),
    last_page_enter: Date.now(),
  };
  sessionStorage.setItem(SESSION_KEY, JSON.stringify(session));
  return session;
}

function saveSession(s: CfSession): void {
  sessionStorage.setItem(SESSION_KEY, JSON.stringify(s));
}

async function persistSession(s: CfSession, userId: string, ended = false): Promise<void> {
  const avgDwell = s.dwell_samples.length > 0
    ? Math.round(s.dwell_samples.reduce((a, b) => a + b, 0) / s.dwell_samples.length)
    : null;
  const payload = {
    id: s.id,
    user_id: userId,
    session_id: s.id,
    started_at: new Date(s.started_at).toISOString(),
    ended_at: ended ? new Date().toISOString() : undefined,
    duration_ms: ended ? Date.now() - s.started_at : undefined,
    pages_visited: [...new Set(s.pages)],
    page_count: s.pages.length,
    mia_opened: s.mia_opened,
    avg_dwell_ms: avgDwell,
    total_clicks: s.clicks,
  };
  try {
    await (supabase as any).from('mia_counterfactual_sessions').upsert(payload, {
      onConflict: 'session_id',
      ignoreDuplicates: false,
    });
  } catch {
    // fire-and-forget
  }
}

export function useCounterfactualTracker() {
  const { user } = useAuth();
  const location = useLocation();
  const sessionRef = useRef<CfSession | null>(null);
  const flushTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const getOrInit = useCallback((): CfSession | null => {
    if (!user?.id) return null;
    if (!sessionRef.current) {
      sessionRef.current = loadSession(user.id);
    }
    return sessionRef.current;
  }, [user?.id]);

  const schedulePersist = useCallback((ended = false) => {
    if (!user?.id) return;
    const s = sessionRef.current;
    if (!s) return;
    if (flushTimer.current) clearTimeout(flushTimer.current);
    flushTimer.current = setTimeout(() => {
      if (sessionRef.current) persistSession(sessionRef.current, user!.id!, ended);
    }, ended ? 0 : FLUSH_DEBOUNCE_MS);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id, user]);

  // Rastreia mudança de página
  useEffect(() => {
    const s = getOrInit();
    if (!s) return;
    const now = Date.now();
    const dwell = now - s.last_page_enter;
    if (dwell > 500 && dwell < 3_600_000) {
      s.dwell_samples.push(dwell);
    }
    s.pages.push(location.pathname);
    s.last_page_enter = now;
    saveSession(s);
    schedulePersist();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.pathname, user?.id]);

  // Click tracking global
  useEffect(() => {
    if (!user?.id) return;
    const handler = () => {
      const s = getOrInit();
      if (!s) return;
      s.clicks++;
      saveSession(s);
    };
    document.addEventListener('click', handler, { passive: true });
    return () => document.removeEventListener('click', handler);
  }, [user?.id, getOrInit]);

  // Flush no beforeunload
  useEffect(() => {
    if (!user?.id) return;
    const handler = () => {
      const s = sessionRef.current;
      if (!s) return;
      const dwell = Date.now() - s.last_page_enter;
      if (dwell > 500) s.dwell_samples.push(dwell);
      s.pages.push(location.pathname);
      persistSession(s, user!.id!, true);
    };
    window.addEventListener('beforeunload', handler);
    return () => window.removeEventListener('beforeunload', handler);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  /** Chamar quando MIA for aberta — marca sessão como assistida */
  const markMiaOpened = useCallback(() => {
    const s = getOrInit();
    if (!s) return;
    s.mia_opened = true;
    saveSession(s);
    schedulePersist();
  }, [getOrInit, schedulePersist]);

  return { markMiaOpened };
}

