// mia-morning-digest — cron 07:30 BRT (10:30 UTC)
// Digest personalizado por usuário ativo:
//   1. Padrão comportamental (top_pages, verbosidade)
//   2. Produção de ontem (daily_production)
//   3. Estoque abaixo do mínimo na loja do usuário
// Entrega SÓ em mia_proactive_queue (per-user). notificacoes_master é
// tabela de RH (schema incompatível) — não usar.

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const supabase = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
)

const OPENROUTER_API_KEY = Deno.env.get('OPENROUTER_API_KEY')

interface ActiveUser {
    user_id: string
    nome: string | null
    store_id: number | null
    role: string
    verbosity_pref: string | null
    top_pages: Array<{ page: string; count: number }>
}

async function resolveRole(userId: string): Promise<string> {
    try {
        const { data } = await supabase.rpc('mia_get_user_role', { p_user_id: userId })
        return (typeof data === 'string' ? data : (data?.[0]?.role ?? data?.role ?? 'operador')) || 'operador'
    } catch {
        return 'operador'
    }
}

async function fetchActiveUsers(): Promise<ActiveUser[]> {
    const since = new Date(Date.now() - 7 * 86_400_000).toISOString()
    const { data: ev } = await supabase
        .from('gidape_events')
        .select('user_id')
        .gte('created_at', since)
        .limit(2000)
    if (!ev?.length) return []

    const uniqueIds = [...new Set(ev.map(r => r.user_id))]

    const [{ data: profiles }, { data: patterns }] = await Promise.all([
        supabase.from('profiles')
            .select('user_id, nome, default_store_id')
            .in('user_id', uniqueIds),
        supabase.from('mia_user_patterns')
            .select('user_id, verbosity_pref, top_pages')
            .in('user_id', uniqueIds),
    ])

    const patternMap = new Map((patterns ?? []).map(p => [p.user_id, p]))

    const users = await Promise.all((profiles ?? []).map(async (p) => ({
        user_id: p.user_id,
        nome: p.nome,
        store_id: p.default_store_id,
        role: await resolveRole(p.user_id),
        verbosity_pref: patternMap.get(p.user_id)?.verbosity_pref ?? null,
        top_pages: (patternMap.get(p.user_id)?.top_pages ?? []) as Array<{ page: string; count: number }>,
    })))

    return users
}

async function fetchContextForUser(user: ActiveUser): Promise<string> {
    const yesterday = new Date(Date.now() - 86_400_000).toISOString().slice(0, 10)
    const parts: string[] = []

    // Produção de ontem (agregada por produto)
    try {
        const { data: prod } = await supabase
            .from('daily_production')
            .select('product_name, quantity')
            .eq('date', yesterday)
            .limit(200)
        if (prod?.length) {
            const total = prod.reduce((s, r) => s + (Number(r.quantity) || 0), 0)
            const top = [...prod].sort((a, b) => (Number(b.quantity) || 0) - (Number(a.quantity) || 0)).slice(0, 3)
            parts.push(`Produção ontem: ${total} unidades. Destaques: ${top.map(t => `${t.product_name} (${t.quantity})`).join(', ')}.`)
        }
    } catch { /* best-effort */ }

    // Estoque abaixo do mínimo na loja do usuário
    if (user.store_id) {
        try {
            const { data: est } = await supabase
                .from('estoque')
                .select('quantidade_atual, quantidade_minima, produtos_master:produto_master_id(nome, ativo)')
                .eq('loja_id', user.store_id)
                .not('quantidade_minima', 'is', null)
                .limit(500)
            const low = (est ?? []).filter((r: any) =>
                r.produtos_master?.ativo &&
                r.quantidade_minima > 0 &&
                Number(r.quantidade_atual) < Number(r.quantidade_minima)
            ).slice(0, 5)
            if (low.length) {
                parts.push(`Estoque em atenção: ${low.map((r: any) => `${r.produtos_master?.nome} (${r.quantidade_atual}/${r.quantidade_minima})`).join(', ')}.`)
            }
        } catch { /* best-effort */ }
    }

    return parts.join('\n') || 'Nenhum alerta crítico de ontem.'
}

async function generateDigest(user: ActiveUser, context: string): Promise<string> {
    const firstName = user.nome ? user.nome.split(' ')[0] : ''
    if (!OPENROUTER_API_KEY) {
        return `☀️ Bom dia${firstName ? `, ${firstName}` : ''}! ${context}`
    }
    const verbosity = user.verbosity_pref === 'conciso' ? 'Seja muito conciso (2-3 linhas).' : 'Seja direto mas completo (4-6 linhas).'
    const prompt = `Você é MIA, assistente do ERP Momma (doces saudáveis, Brasília).
Usuário: ${firstName || 'operador'} — role ${user.role}${user.store_id ? `, Loja ${user.store_id}` : ', Matriz'}.
${verbosity}
Gere um digest matinal em pt-BR. Saudação pelo nome, destaque o mais importante primeiro,
e termine oferecendo ajuda específica relacionada ao contexto. Não invente dados.

Dados de hoje:
${context}

Páginas que esse usuário mais usa: ${user.top_pages.slice(0, 3).map(p => p.page).join(', ') || 'n/d'}`
    try {
        const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${OPENROUTER_API_KEY}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({
                model: 'x-ai/grok-4.1-fast',
                messages: [{ role: 'user', content: prompt }],
                max_tokens: 250,
                temperature: 0.5,
            }),
        })
        const json = await res.json()
        return json.choices?.[0]?.message?.content ?? `☀️ Bom dia${firstName ? `, ${firstName}` : ''}! ${context}`
    } catch {
        return `☀️ Bom dia${firstName ? `, ${firstName}` : ''}! ${context}`
    }
}

async function deliverDigest(userId: string, digest: string, context: string): Promise<void> {
    const expires = new Date(Date.now() + 12 * 3_600_000).toISOString()
    await supabase.from('mia_proactive_queue').insert({
        user_id: userId,
        type: 'morning_digest',
        title: 'Bom dia — seu resumo',
        body: digest,
        context: { raw: context },
        priority: 3,
        expires_at: expires,
    })
}

// Kill-switch: enquanto a proatividade está desligada, não gera nem entrega
// digests. Captura/aprendizado seguem em outros crons. Fail-safe: false.
async function proactiveEnabled(): Promise<boolean> {
    try {
        const { data } = await supabase.from('mia_runtime_config')
            .select('value').eq('key', 'proactive_enabled').maybeSingle()
        return (data as any)?.value === true || (data as any)?.value === 'true'
    } catch { return false }
}

Deno.serve(async () => {
    try {
        if (!(await proactiveEnabled())) {
            return new Response(JSON.stringify({ skipped: 'proactive_disabled' }), {
                status: 200, headers: { 'Content-Type': 'application/json' },
            })
        }
        const users = await fetchActiveUsers()
        console.log(`[morning-digest] processando ${users.length} usuários`)

        const results = await Promise.allSettled(
            users.map(async (user) => {
                const context = await fetchContextForUser(user)
                const digest = await generateDigest(user, context)
                await deliverDigest(user.user_id, digest, context)
            })
        )
        const ok = results.filter(r => r.status === 'fulfilled').length
        const fail = results.filter(r => r.status === 'rejected').length
        console.log(`[morning-digest] done: ${ok} ok, ${fail} fail`)
        return new Response(JSON.stringify({ ok, fail, total: users.length }), {
            status: 200, headers: { 'Content-Type': 'application/json' },
        })
    } catch (err) {
        console.error('[morning-digest] fatal:', err)
        return new Response(JSON.stringify({ error: String(err) }), { status: 500 })
    }
})

