    v_peak jsonb;
    v_feat jsonb;
    v_feat_id text;
    v_feat_count int4;
    v_pages jsonb;
    v_page_found bool := false;
    v_dwell_ms int8;
    v_page text;
    v_from text;
    v_to text;
BEGIN
    v_hour := EXTRACT(HOUR FROM NEW.created_at)::int4;
    v_page := NEW.page;

    INSERT INTO mia_user_patterns(user_id) VALUES(NEW.user_id) ON CONFLICT (user_id) DO NOTHING;

    SELECT COALESCE(peak_hours, '{}') INTO v_peak FROM mia_user_patterns WHERE user_id = NEW.user_id;
    v_peak := jsonb_set(v_peak, ARRAY[v_hour::text], to_jsonb(COALESCE((v_peak ->> v_hour::text)::int4, 0) + 1));

    IF NEW.event_type = 'feature_use' THEN
        v_feat_id := NEW.properties->>'feature_id';
        IF v_feat_id IS NOT NULL THEN
            SELECT COALESCE(feature_usage_map, '{}') INTO v_feat FROM mia_user_patterns WHERE user_id = NEW.user_id;
            v_feat_count := COALESCE((v_feat ->> v_feat_id)::int4, 0) + 1;
            v_feat := jsonb_set(v_feat, ARRAY[v_feat_id], to_jsonb(v_feat_count));
            UPDATE mia_user_patterns SET feature_usage_map = v_feat, peak_hours = v_peak, behavioral_updated_at = now()
                WHERE user_id = NEW.user_id;
            RETURN NEW;
        END IF;
    END IF;

    IF NEW.event_type = 'page_exit' THEN
        v_dwell_ms := (NEW.properties->>'dwell_ms')::int8;
        v_from := v_page;
        v_to := NEW.properties->>'next_page';

        IF v_dwell_ms IS NOT NULL AND v_dwell_ms > 0 THEN
            DECLARE
                v_dwell_map jsonb;
                v_old_avg numeric;
                v_old_count int4;
                v_new_avg int8;
            BEGIN
                SELECT COALESCE(avg_dwell_ms, '{}') INTO v_dwell_map FROM mia_user_patterns WHERE user_id = NEW.user_id;
                v_old_avg := COALESCE((v_dwell_map -> v_page ->> 'avg')::numeric, 0);
                v_old_count := COALESCE((v_dwell_map -> v_page ->> 'count')::int4, 0);
                -- média em numeric, arredondada (sem truncamento sistemático)
                v_new_avg := round(((v_old_avg * v_old_count) + v_dwell_ms) / (v_old_count + 1))::int8;
