            INSERT INTO user_nav_graph(user_id, from_page, to_page, weight, last_seen_at)
                VALUES(NEW.user_id, v_from, v_to, 1, now())
                ON CONFLICT (user_id, from_page, to_page)
                DO UPDATE SET weight = user_nav_graph.weight + 1, last_seen_at = now();
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.event_type = 'mia_suggestion_acted' THEN
        UPDATE mia_user_patterns
            SET mia_suggestion_act_rate = (
                COALESCE(mia_suggestion_act_rate, 0) * 0.8 +
                CASE WHEN (NEW.properties->>'acted')::bool THEN 0.2 ELSE 0 END
            ), peak_hours = v_peak, behavioral_updated_at = now()
            WHERE user_id = NEW.user_id;
        RETURN NEW;
    END IF;

    IF NEW.event_type = 'page_enter' THEN
        SELECT COALESCE(top_pages, '[]'::jsonb) INTO v_pages FROM mia_user_patterns WHERE user_id = NEW.user_id;
        v_page_found := EXISTS(SELECT 1 FROM jsonb_array_elements(v_pages) elem WHERE elem->>'page' = v_page);

        IF v_page_found THEN
            v_pages := COALESCE((
                SELECT jsonb_agg(
                    CASE WHEN elem->>'page' = v_page
                        THEN jsonb_set(elem, '{count}', to_jsonb((elem->>'count')::int4 + 1))
                        ELSE elem END
                ) FROM jsonb_array_elements(v_pages) elem
            ), '[]'::jsonb);
        ELSE
            v_pages := v_pages || jsonb_build_object('page', v_page, 'count', 1);
        END IF;

