        -- pra uma página recém-vista não ser podada no mesmo insert que a criou.
        v_pages := COALESCE((
            SELECT jsonb_agg(elem ORDER BY (elem->>'count')::int4 DESC)
            FROM (
                SELECT elem FROM jsonb_array_elements(v_pages) elem
                ORDER BY (CASE WHEN elem->>'page' = v_page THEN 1 ELSE 0 END) DESC,
