                LIMIT 20
            ) sub
        ), v_pages);

        UPDATE mia_user_patterns SET top_pages = COALESCE(v_pages, '[]'::jsonb), peak_hours = v_peak, behavioral_updated_at = now()
            WHERE user_id = NEW.user_id;
        RETURN NEW;
    END IF;

    UPDATE mia_user_patterns SET peak_hours = v_peak, behavioral_updated_at = now() WHERE user_id = NEW.user_id;
    RETURN NEW;
END;
$$;

