Set-Location "C:\Users\olive_\OneDrive\Documentos\codigo\Momma\momma-stock-insight"
function Deploy-Fn($fn) {
  for ($i=1; $i -le 6; $i++) {
    $out = & $sb functions deploy $fn --project-ref jaumyfyeueayibbxunxc --no-verify-jwt 2>&1 | Out-String
    if ($out -match "Deployed Functions") { Write-Output "$fn : OK (tentativa $i)"; return }
    Start-Sleep -Seconds 4
  }
  Write-Output "$fn : FALHOU"
}
Deploy-Fn "mia-morning-digest"
