$headers = @{ "Authorization" = "Bearer $anon"; "apikey" = $anon; "Content-Type" = "application/json" }
$base = "https://jaumyfyeueayibbxunxc.supabase.co/functions/v1"
function FlagSet($v) {
  for ($i=1; $i -le 6; $i++) {
    $out = & $sb db query "update mia_runtime_config set value='$v'::jsonb where key='proactive_enabled'; select value from mia_runtime_config where key='proactive_enabled';" --linked --output json 2>&1 | Out-String
    if ($out -notmatch "forcibly closed|wsasend|wsarecv|failed to initialise") { return $out }
    Start-Sleep -Seconds 3
  }
}
Write-Output "=== Liga flag ==="
FlagSet "true"
foreach ($fn in @("mia-anomaly-watcher","mia-morning-digest","mia-distillation")) {
  try {
    $r = Invoke-WebRequest -Uri "$base/$fn" -Method Post -Headers $headers -Body "{}" -UseBasicParsing -TimeoutSec 90
    Write-Output "$fn -> HTTP $($r.StatusCode): $($r.Content)"
  } catch { Write-Output "$fn -> ERRO: $($_.Exception.Message)" }
}
